    let _coachApplying=false;
    let _coachClients:any[]=[];
    function _coachPanelEl(){ return root.querySelector('#s-coach .c-p[data-p="health2"]')as HTMLElement|null; }
    function collectCoachProfile(){
      const p=_coachPanelEl(); if(!p) return null;
      // [data-nocap] elements (the payment Status dropdowns, which mirror the existing hidden
      // pills) are excluded so the positional field capture stays identical to before — existing
      // saved profiles keep restoring correctly.
      const f=Array.from(p.querySelectorAll("input,select,textarea")).filter((el:any)=>!el.hasAttribute("data-nocap")).map((el:any)=>(el.type==="checkbox"||el.type==="radio")?{c:!!el.checked}:{v:el.value});
      const pills=Array.from(p.querySelectorAll(".pill")).map((b:any)=>b.classList.contains("on"));
      const chips=Array.from(p.querySelectorAll(".chip-o")).map((b:any)=>b.classList.contains("on"));
      return {v:1,f,pills,chips,attachments:_coachAttachments.slice(),consStatus:_coachConsStatus,commitDate:((root.querySelector("#fuCommitDate")as HTMLInputElement|null)?.value)||"",reviewDate:((root.querySelector("#haReviewDate")as HTMLInputElement|null)?.value)||""};
    }
    function applyCoachProfile(obj:any){
      const p=_coachPanelEl(); if(!p||!obj) return;
      _coachApplying=true;
      try{
        const els=Array.from(p.querySelectorAll("input,select,textarea")).filter((el:any)=>!el.hasAttribute("data-nocap"));
        (obj.f||[]).forEach((rec:any,i:number)=>{ const el:any=els[i]; if(!el) return; if("c" in rec) el.checked=!!rec.c; else el.value=rec.v==null?"":rec.v; });
        const pills=Array.from(p.querySelectorAll(".pill")); (obj.pills||[]).forEach((on:boolean,i:number)=>{ if(pills[i]) (pills[i]as HTMLElement).classList.toggle("on",!!on); });
        const chipEls=Array.from(p.querySelectorAll(".chip-o")); (obj.chips||[]).forEach((on:boolean,i:number)=>{ if(chipEls[i]) (chipEls[i]as HTMLElement).classList.toggle("on",!!on); });
        _coachAttachments=Array.isArray(obj.attachments)?obj.attachments.slice():[]; renderCoachAtts();
        _haBmiCalc();
        // Re-trigger panel visibility based on restored consultation status pills
        const cs=root.querySelector("#consStatus"); if(cs){ const onPill=cs.querySelector(".pill.on")as HTMLElement; if(onPill){ const act=onPill.getAttribute("onclick")||""; const m=act.match(/consAct\('([^']+)'/); if(m) consAct(m[1],onPill); } }
        // Re-trigger payment method panel visibility
        const pm=root.querySelector("#payMethod")as HTMLSelectElement; if(pm&&pm.value) payBlk(pm.value);
        _syncProgramPricing();   // apply L1/L2 program-specific pricing view (also re-quotes)
        _syncPayStSelects();     // mirror restored payment-Status pills into their dropdowns
        _refreshPayEnrollChip(); // reflect the enrolled level (L1/L2) in the payment section
        try{ w._syncI2BalDue(); }catch(_){}   // rebuild Balance due date (Inst-1 + 30d) from restored Inst-1 date
        try{ w._syncAdvBalDue(); }catch(_){}   // same for Advance booking (Advance date + 30d)
      } finally { _coachApplying=false; }
    }
    // Part 2 — Balance due date = Installment-1 date + 30 days. Auto-filled + read-only (the user
    // never types it); displayed as DD MMM YYYY, with the ISO date kept in data-iso for persistence
    // and the Accounts auto-reminders. Recalculates whenever the Inst-1 date changes.
    w._syncI2BalDue=()=>{
      const tgt=root.querySelector("#i2BalDueDate")as HTMLInputElement|null; if(!tgt) return;
      const v=((root.querySelector("#i2Inst1Date")as HTMLInputElement|null)?.value||"").trim();
      if(!v){ tgt.value=""; delete tgt.dataset.iso; return; }
      const d=new Date(v+"T00:00:00"); if(isNaN(d.getTime())){ tgt.value=""; delete tgt.dataset.iso; return; }
      d.setDate(d.getDate()+30);
      const iso=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
      tgt.dataset.iso=iso; tgt.value=fmtISTDate(iso);
    };
    // Advance-booking twin of _syncI2BalDue: Balance due date = Advance date + 30 days, auto-filled
    // and read-only (ISO kept in data-iso for the balance due row + Accounts reminders).
    w._syncAdvBalDue=()=>{
      const tgt=root.querySelector("#advBalDueDate")as HTMLInputElement|null; if(!tgt) return;
      const v=((root.querySelector("#advDate")as HTMLInputElement|null)?.value||"").trim();
      if(!v){ tgt.value=""; delete tgt.dataset.iso; return; }
      const d=new Date(v+"T00:00:00"); if(isNaN(d.getTime())){ tgt.value=""; delete tgt.dataset.iso; return; }
      d.setDate(d.getDate()+30);
      const iso=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
      tgt.dataset.iso=iso; tgt.value=fmtISTDate(iso);
    };
    function renderCoachAtts(){
      const ba=root.querySelector("#coachAtts"); if(!ba) return;
      const e=(s:string)=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
      ba.innerHTML=_coachAttachments.length?_coachAttachments.map((a:any)=>'<span class="att"><svg class="icon"><use href="#i-clip"/></svg> <a href="'+e(_safeHref(a.url))+'" target="_blank" rel="noopener" style="color:inherit;text-decoration:none">'+e(a.name||"file")+(a.src==="advisor"?" · advisor":"")+'</a></span>').join(""):'<span style="font-size:12px;color:var(--faint)">No reports synced from the advisor yet.</span>';
    }
    const _coachpKey=(id:any)=>"wos_coachp_"+id;
    function readCoachLocal(id:any){ try{ const s=localStorage.getItem(_coachpKey(id)); return s?JSON.parse(s):null; }catch(_){ return null; } }
    function saveCoachLocal(id:any,obj:any){ try{ localStorage.setItem(_coachpKey(id),JSON.stringify(obj)); }catch(_){} }
    async function loadAndApplyCoach(lead:any){
      if(!lead) return;
      if(lead.coachProfile===undefined){
        let prof:any=null;
        try{ const {data}=await supabase.from("leads").select("coach_profile").eq("meta_lead_id",lead.id).limit(1); prof=(data&&data[0]&&data[0].coach_profile)||null; }catch(e:any){ prof=null; if(/coach_profile|column/i.test(e.message||"")) toastErr("Run supabase-migration-coach-screening.sql to enable coach profiles"); }
        if(!prof) prof=readCoachLocal(lead.id);
        lead.coachProfile=prof;
      }
      if(lead.coachProfile && String(_coachLeadId)===String(lead.id)) applyCoachProfile(lead.coachProfile);
    }
    // Pull blood-report attachments + recap fields the advisor saved (advisor_profile).
    async function _coachSyncAdvisorReports(lead:any){
      let ap:any=null;
      try{ const {data}=await supabase.from("leads").select("advisor_profile").eq("meta_lead_id",lead.id).limit(1); ap=data&&data[0]&&data[0].advisor_profile; }catch(_){}
      if(!ap){ try{ const s=localStorage.getItem("wos_advp_"+lead.id); if(s) ap=JSON.parse(s); }catch(_){} }
      if(String(_coachLeadId)!==String(lead.id)) return;
      // Populate recap fields from advisor profile using named labels
      if(ap&&ap.f){
        const named=_advNamed(ap.f);
        const setV=(id:string,v:string)=>{const el=root.querySelector("#"+id)as HTMLInputElement|null;if(el&&v)el.value=v;};
        setV("crSugar",named["Sugar level"]||lead.sugar||"");
        const fasting=named["Fasting (mg/dL)"]||""; const pp=named["Postprandial (mg/dL)"]||"";
        setV("crFasting",(fasting||pp)?((fasting||"--")+" / "+(pp||"--")):"");
        setV("crHba1c",named["HbA1c (%)"]||"");
        const ws=named["Walk-in status"]||""; const sel=root.querySelector("#crWalkIn")as HTMLSelectElement|null;
        if(sel&&ws){ for(let i=0;i<sel.options.length;i++){ if(sel.options[i].text===ws){sel.selectedIndex=i;break;} } }
      } else if(lead.sugar){
        const el=root.querySelector("#crSugar")as HTMLInputElement|null; if(el) el.value=lead.sugar;
      }
      // Sync attachments
      let atts:any[]=[]; if(ap&&Array.isArray(ap.attachments)) atts=ap.attachments;
      if(atts.length){ const have=new Set(_coachAttachments.map((a:any)=>a.url)); atts.forEach((a:any)=>{ if(!have.has(a.url)) _coachAttachments.push({name:a.name,url:a.url,src:"advisor"}); }); renderCoachAtts(); }
    }
    // Surface this client's Smartflo call recording into the recording-url field.
    async function _coachRenderRecordings(id:string){
      const fld=root.querySelector("#coachRecUrl")as HTMLInputElement|null; if(!fld) return;
      try{ const res=await _callRecordings(id); const recs=(res&&res.recordings)||[]; const ready=recs.find((r:any)=>r.recording_url); if(ready&&!fld.value&&String(_coachLeadId)===String(id)) fld.value=ready.recording_url; }catch(_){}
      // Restore the most recently saved Zoom link so it stays available on reopen/refresh.
      try{ if(!fld.value){ const {data}=await supabase.from("zoom_recordings").select("meeting_url,created_at").eq("lead_id",id).order("created_at",{ascending:false}).limit(1); const z=data&&data[0]; if(z&&z.meeting_url&&!fld.value&&String(_coachLeadId)===String(id)) fld.value=z.meeting_url; } }catch(_){}
    }
    // ===== Score card — hybrid: manual Progress+Consultation, auto Attendance+Follow-up =====
    let _scAuto={attendance:0,followup:0};
    function _scNum(sel:string){ const el=root.querySelector(sel)as HTMLInputElement|null; const n=parseInt(((el&&el.value)||"").replace(/[^\d]/g,""))||0; return Math.max(0,Math.min(100,n)); }
    function _scRecalcOverall(){
      const prog=_scNum("#scProgress"), cons=_scNum("#scConsult");
      // Weights (tunable): progress .30, consultation .25, attendance .25, follow-up .20.
      const overall=Math.round(0.30*prog+0.25*cons+0.25*_scAuto.attendance+0.20*_scAuto.followup);
      const ov=root.querySelector("#scOverallV"); if(ov) ov.textContent=String(overall);
      const tile=root.querySelector("#scOverallTile")as HTMLElement|null;
      if(tile) tile.style.borderColor=overall>=75?"var(--ok)":overall>=50?"var(--warn)":"var(--alert)";
    }
    w._scRecalcOverall=_scRecalcOverall;
    async function _renderScoreCard(id:string){
      let att=0, fu=80;
      try{
        const {data:appts}=await supabase.from("appointments").select("status").eq("lead_id",id);
        const rows=appts||[]; const tot=rows.length; const vis=rows.filter((a:any)=>a.status==="visited").length;
        att= tot? Math.round(100*vis/tot) : 0;
      }catch(_){}
      try{
        const {data:lr}=await supabase.from("leads").select("next_followup").eq("meta_lead_id",id).limit(1);
        const nf=lr&&lr[0]&&lr[0].next_followup;
        if(!nf) fu=80; else { const t=new Date(nf).getTime(); fu= t>=Date.now()?100:40; }   // future = on-track, overdue = poor
      }catch(_){}
      if(String(_coachLeadId)!==String(id)) return;
      _scAuto={attendance:att,followup:fu};
      const setTxt=(sel:string,v:any)=>{const el=root.querySelector(sel);if(el)el.textContent=String(v);};
      setTxt("#scAttendanceV",att); setTxt("#scFollowupV",fu);
      _scRecalcOverall();
    }
    // ===== Office-visit audio recording (MediaRecorder → /storage → office_recordings) =====
    let _ovrRec:any=null; let _ovrChunks:any[]=[]; let _ovrStartMs=0; let _ovrTimer:any=null; let _ovrLeadId="";
    // Recording-status pills (Open / Done / Not Done). Kept in sync with the actual recording
    // state: stopping a recording flips it to "Done" instantly, and on profile open it is derived
    // from the office_recordings backend rows so it always reflects the latest saved state.
    function _recStatusApply(key:"open"|"done"|"notdone"){
      const box=root.querySelector("#recStatusPills"); if(!box) return;
      const idx=({open:0,done:1,notdone:2} as any)[key]??0;
      const pills=Array.from(box.querySelectorAll(".pill"));
      pills.forEach((p:any,i:number)=>p.classList.toggle("on",i===idx));
    }
    w._recStatusSet=(key:"open"|"done"|"notdone")=>{ _recStatusApply(key); };   // manual override (saved with the coach profile on next Save)
    function _recStatusCurrent():"open"|"done"|"notdone"{
      const box=root.querySelector("#recStatusPills"); if(!box) return "open";
      const pills=Array.from(box.querySelectorAll(".pill")); const i=pills.findIndex((p:any)=>p.classList.contains("on"));
      return (["open","done","notdone"] as const)[i>=0?i:0];
    }
    function _ovrSetUi(recording:boolean){
      const mb=root.querySelector("#micBtn")as HTMLElement|null; const txt=root.querySelector("#micTxt"); const stop=root.querySelector("#ovrStopBtn")as HTMLElement|null; const start=root.querySelector("#ovrStartBtn")as HTMLElement|null; const st=root.querySelector("#ovrStatus");
      if(mb) mb.classList.toggle("rec",recording);
      if(txt) txt.textContent=recording?"Recording…":"Start office-visit recording";
      if(st) st.textContent=recording?"● Recording in progress — In-clinic Audio, auto-saving to this Customer Profile":"In-clinic Audio — Auto-saved to this Customer Profile";
      if(stop) stop.style.display=recording?"":"none";
      if(start) start.style.display=recording?"none":"";
      const t=root.querySelector("#ovrTimer"); if(t&&!recording) t.textContent="";
    }
    w._ovrToggle=async()=>{
      if(_ovrRec&&_ovrRec.state==="recording"){ w._ovrStop(); return; }
      if(!_coachLeadId){ toast("Open a visited client first"); return; }
      // Browsers only expose the microphone (getUserMedia/MediaRecorder) on a SECURE
      // context — HTTPS or localhost. On a plain http:// deployment navigator.mediaDevices
      // is undefined, so surface the real cause instead of a generic "not supported".
      if(!window.isSecureContext){ toastErr("Audio recording needs a secure (HTTPS) connection — it is blocked on this http:// address. Open the app over https:// to record."); return; }
      if(!navigator.mediaDevices||!(window as any).MediaRecorder){ toastErr("Audio recording is not supported in this browser"); return; }
      let stream:MediaStream;
      try{ stream=await navigator.mediaDevices.getUserMedia({audio:true}); }
      catch(e:any){ toastErr("Microphone permission denied"); return; }
      _ovrChunks=[];
      const MR=(window as any).MediaRecorder;
      const mime=MR.isTypeSupported&&MR.isTypeSupported("audio/webm")?"audio/webm":"";
      _ovrRec=new MR(stream,mime?{mimeType:mime}:undefined);
      _ovrRec.ondataavailable=(ev:any)=>{ if(ev.data&&ev.data.size) _ovrChunks.push(ev.data); };
      _ovrRec.onstop=()=>{ try{ stream.getTracks().forEach((t:any)=>t.stop()); }catch(_){} _ovrFinalize(); };
      _ovrRec.start();
      _ovrStartMs=Date.now();
      _ovrLeadId=String(_coachLeadId);
      _ovrSetUi(true);
      const tEl=root.querySelector("#ovrTimer");
      _ovrTimer=setInterval(()=>{ const s=Math.floor((Date.now()-_ovrStartMs)/1000); const mm=String(Math.floor(s/60)).padStart(2,"0"); const ss=String(s%60).padStart(2,"0"); if(tEl)tEl.textContent="● "+mm+":"+ss; },1000);
      toast("Recording started");
    };
    w._ovrStop=()=>{ if(_ovrRec&&_ovrRec.state!=="inactive"){ try{ _ovrRec.stop(); }catch(_){} } if(_ovrTimer){clearInterval(_ovrTimer);_ovrTimer=null;} _ovrSetUi(false); };
    async function _ovrFinalize(){
      const id=String(_ovrLeadId||_coachLeadId||""); if(!id||!_ovrChunks.length) return;
      const dur=Math.round((Date.now()-_ovrStartMs)/1000);
      const blob=new Blob(_ovrChunks,{type:(_ovrChunks[0]&&_ovrChunks[0].type)||"audio/webm"});
      _ovrChunks=[];
      const safe=id.replace(/[^a-zA-Z0-9._-]/g,"_");
      const path=safe+"/"+Date.now()+"_office-visit.webm";
      toast("Saving recording…");
      try{
        const up=await supabase.storage.from("office-recordings").upload(path,blob as any,{upsert:false});
        if(up.error) throw up.error;
        // Store the URL WITHOUT the session token. getPublicUrl signs with whoever is logged in,
        // so the stored link died when the uploader's token expired — and persisted a live token
        // in the database besides. Playback re-signs per viewer from file_path (_ovrUrl).
        const {data}=supabase.storage.from("office-recordings").getPublicUrl(path);
        const url=String((data&&data.publicUrl)||"").split("?")[0];
        await supabase.from("office_recordings").insert({lead_id:id,file_url:url,file_path:path,file_name:"Office visit "+fmtIST(new Date().toISOString()),duration_seconds:dur,recorded_by:_recBy(),created_at:new Date().toISOString()});
        toast("✓ Recording saved to profile");
        // Recording is now persisted in office_recordings (backend) → flip the status to "Done"
        // immediately, no refresh or manual click needed. Runs only if this lead is still open.
        if(String(_coachLeadId)===id){ _recStatusApply("done"); _ovrRenderList(id); }
      }catch(e:any){ toastErr("Recording save failed: "+(e.message||"upload error")); }
    }
    // Playback/download URL for a recording, built from file_path with the CURRENT viewer's session.
    // The stored file_url has the UPLOADER's token baked in from save time (getPublicUrl signs with
    // whoever is logged in), so anyone else's recording stopped playing the moment that token
    // expired — confirmed live: sugashini's 51m recording carried sugashini's token and 401'd for
    // the Owner, while the Owner's own 2s row played fine. Re-signing per viewer fixes every
    // existing row too, because file_path was always stored alongside the stale URL.
    function _ovrUrl(r:any):string{
      try{
        if(r&&r.file_path){ const {data}=supabase.storage.from("office-recordings").getPublicUrl(String(r.file_path)); if(data&&data.publicUrl) return data.publicUrl; }
      }catch(_){}
      return String(r&&r.file_url||"");   // legacy rows without a path — better a stale token than nothing
    }
    async function _ovrRenderList(id:string){
      const el=root.querySelector("#ovrList"); if(!el) return;
      let rows:any[]=[];
      try{ const {data}=await supabase.from("office_recordings").select("*").eq("lead_id",id).order("created_at",{ascending:false}).limit(50); rows=data||[]; }catch(_){ rows=[]; }
      if(String(_coachLeadId)!==String(id)) return;
      // Derive the recording status from the backend on every (re)load: a saved recording means
      // "Done". Only auto-promote — never downgrade a manual "Not Done" when a recording exists.
      if(rows.length && _recStatusCurrent()!=="notdone") _recStatusApply("done");
      const e=(s:any)=>(s==null?"":String(s)).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
      const dur=(s:number)=>{ s=s||0; const m=Math.floor(s/60); return (m?m+"m ":"")+(s%60)+"s"; };
      el.innerHTML=rows.length?('<div style="font-size:11px;color:var(--faint);font-weight:600;margin-bottom:4px">OFFICE-VISIT RECORDINGS ('+rows.length+')</div>'+rows.map((r:any)=>
        '<div style="display:flex;align-items:center;gap:8px;padding:6px 8px;border:1px solid var(--line);border-radius:8px;margin-bottom:6px;flex-wrap:wrap">'
        +'<span style="font-size:12px;font-weight:600">🎙 '+e(fmtIST(r.created_at))+'</span>'
        +'<span class="chipb neu" style="font-size:10px">'+e(dur(r.duration_seconds))+'</span>'
        +(r.recorded_by?'<span style="font-size:10.5px;color:var(--muted)">'+e(r.recorded_by)+'</span>':'')
        +'<audio controls preload="none" src="'+e(_safeHref(_ovrUrl(r)))+'" style="height:32px;flex:1;min-width:180px"></audio>'
        +'<a class="btn bsm" href="'+e(_safeHref(_ovrUrl(r)))+'" download style="text-decoration:none">⬇ Download</a>'
        +'</div>'
      ).join("")):'<div style="font-size:12px;color:var(--faint)">No office-visit recordings yet.</div>';
    }
    // ===== Recordings screen: cross-client Office-visit audio + Zoom meeting tables =====
    // Both reuse the shared Excel-style filter grid engine (regGrid/gridHead/gridApply),
    // shared pager helpers (_pgBtns/_pgApply) and CSV export (_downloadCsv).
    let _ovrRows:any[]=[], _zoomRows:any[]=[];
    let _ovrQuery="", _zoomQuery="", _ovrSearchT:any=null, _zoomSearchT:any=null;
    let _ovrApplied:{from:string;to:string}={from:"",to:""};
    let _zoomApplied:{from:string;to:string}={from:"",to:""};
    const REC_PER=12; let _ovrTblPageN=1, _zoomTblPageN=1;
    const _recDur=(s:number)=>{ s=Math.max(0,Math.round(s||0)); const m=Math.floor(s/60); return (m?m+"m ":"")+(s%60)+"s"; };
    const _ovrTblCols:any[]=[
      {key:"dt",label:"Recording Date & Time",filter:true,text:(r:any)=>fmtIST(r.created_at)},
      {key:"cust",label:"Customer Name",filter:true,text:(r:any)=>r._cust||""},
      {key:"by",label:"Recorded By",filter:true,text:(r:any)=>r.recorded_by||""},
      {key:"dur",label:"Duration",filter:true,text:(r:any)=>_recDur(r.duration_seconds)},
      {key:"status",label:"Recording Status",filter:true,text:(r:any)=>r.file_url?"Ready":"Processing"},
      {key:"act",label:"Actions",filter:false},
    ];
    regGrid("ovrTbl",()=>_ovrTblCols,()=>renderOvrTbl());
    const _zoomTblCols:any[]=[
      {key:"dt",label:"Meeting Date & Time",filter:true,text:(r:any)=>fmtIST(r.meeting_at||r.created_at)},
      {key:"cust",label:"Customer Name",filter:true,text:(r:any)=>r._cust||""},
      {key:"link",label:"Zoom Recording Link",filter:true,text:(r:any)=>r.meeting_url||""},
      {key:"dur",label:"Meeting Duration",filter:true,text:(r:any)=>_recDur(r.duration_seconds)},
      {key:"status",label:"Recording Status",filter:true,text:(r:any)=>r.status||(r.meeting_url?"Ready":"Pending")},
      {key:"act",label:"Actions",filter:false},
    ];
    regGrid("zoomTbl",()=>_zoomTblCols,()=>renderZoomTbl());
    async function loadRecordings(){
      // Health Advisor: this page shows only THEIR Call Status + Call Recordings (advisors don't do
      // office visits / Zoom consults). Every other role keeps the Office-Visit + Zoom tables.
      const isAdv=_isAdvisorRole();
      const _sh=(id:string,show:boolean)=>{ const el=root.querySelector("#"+id)as HTMLElement|null; if(el) el.style.display=show?"":"none"; };
      _sh("ovrTblSec",!isAdv); _sh("zoomTblSec",!isAdv); _sh("callRecSec",isAdv);
      const _rsub=root.querySelector("#recSubtitle");
      if(isAdv){
        if(_rsub) _rsub.textContent="Your call statuses and call recordings.";
        await loadCallRecordings();
        return;
      }
      // Role-aware subtitle: Advisor/Coach see only their OWN recordings, so don't claim
      // "across customers" (which reads like a bug when their list is empty).
      if(_rsub) _rsub.textContent=_selfScopeName()
        ? "Your in-clinic office-visit and Zoom consultation recordings."
        : "All in-clinic office-visit audio and Zoom consultation recordings across customers.";
      try{ const {data}=await supabase.from("office_recordings").select("*").order("created_at",{ascending:false}).limit(2000); _ovrRows=data||[]; }catch(_){ _ovrRows=[]; }
      try{ const {data}=await supabase.from("zoom_recordings").select("*").order("created_at",{ascending:false}).limit(2000); _zoomRows=data||[]; }catch(_){ _zoomRows=[]; }
      // Resolve customer name by lead_id (office rows have none; zoom rows keep their own).
      const ids=Array.from(new Set([..._ovrRows,..._zoomRows].map((r:any)=>String(r.lead_id)).filter(Boolean)));
      const nameMap:Record<string,string>={};
      if(ids.length){ try{ const {data}=await supabase.from("leads").select("meta_lead_id,name").in("meta_lead_id",ids); (data||[]).forEach((l:any)=>{ if(l.meta_lead_id!=null) nameMap[String(l.meta_lead_id)]=l.name||""; }); }catch(_){} }
      const resolve=(r:any,own?:string)=>own||nameMap[String(r.lead_id)]||("Lead #"+(r.lead_id||"?"));
      _ovrRows.forEach((r:any)=>{ r._cust=resolve(r); });
      _zoomRows.forEach((r:any)=>{ r._cust=resolve(r,r.customer_name); });
      _ovrTblPageN=1; _zoomTblPageN=1;
      renderOvrTbl(); renderZoomTbl();
    }
    function _recDateFilter(rows:any[],applied:{from:string;to:string},field:(r:any)=>any){
      const {from,to}=applied; if(!from&&!to)return rows;
      const f=from?new Date(from+"T00:00:00").getTime():0; const t=to?new Date(to+"T23:59:59").getTime():0;
      return rows.filter((r:any)=>{ const d=field(r); const x=d?new Date(d).getTime():0; if(f&&x<f)return false; if(t&&x>t)return false; return true; });
    }
    // Advisor / Coach see only recordings THEY made (matched on recorded_by); full-access roles see all.
    function _recScoped(rows:any[]):any[]{ const s=_selfScopeName(); if(!s) return rows; const sl=s.toLowerCase(); return rows.filter((r:any)=>String(r.recorded_by||"").trim().toLowerCase()===sl); }
    function _ovrBase(){
      let base=_recScoped(_ovrRows);
      const q=_ovrQuery.trim().toLowerCase();
      if(q) base=base.filter((r:any)=>[r._cust,r.recorded_by].some((v:any)=>String(v||"").toLowerCase().includes(q)));
      return _recDateFilter(base,_ovrApplied,(r:any)=>r.created_at);
    }
    function _zoomBase(){
      let base=_recScoped(_zoomRows);
      const q=_zoomQuery.trim().toLowerCase();
      if(q) base=base.filter((r:any)=>[r._cust,r.meeting_url].some((v:any)=>String(v||"").toLowerCase().includes(q)));
      return _recDateFilter(base,_zoomApplied,(r:any)=>r.meeting_at||r.created_at);
    }
    const _recE=(s:any)=>(s==null?"":String(s)).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
    const _recA=(s:any)=>(s==null?"":String(s)).replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;");
    function renderOvrTbl(){
      const head=root.querySelector("#ovrTblHead"); if(head)head.innerHTML=gridHead("ovrTbl");
      const rows=gridApply("ovrTbl",_ovrBase());
      const cnt=root.querySelector("#ovrTblCount"); if(cnt)cnt.textContent=String(rows.length);
      const body=root.querySelector("#ovrTblBody"); if(!body)return;
      const pages=Math.max(1,Math.ceil(rows.length/REC_PER));
      if(_ovrTblPageN>pages)_ovrTblPageN=pages; if(_ovrTblPageN<1)_ovrTblPageN=1;
      const pr=rows.slice((_ovrTblPageN-1)*REC_PER,(_ovrTblPageN-1)*REC_PER+REC_PER);
      body.innerHTML=pr.length?pr.map((r:any)=>{
        // Re-signed with the VIEWER's session — the stored URL carries the uploader's token,
        // which expires and 401s for everyone else (see _ovrUrl).
        const ready=!!(r.file_url||r.file_path); const url=_recA(_ovrUrl(r));
        return '<tr>'
          +'<td class="mono" style="font-size:11px;white-space:nowrap">'+_recE(fmtIST(r.created_at))+'</td>'
          +'<td style="font-weight:600">'+_recE(r._cust||"—")+'</td>'
          +'<td>'+_recE(r.recorded_by||"—")+'</td>'
          +'<td class="mono">'+_recE(_recDur(r.duration_seconds))+'</td>'
          +'<td><span class="chipb '+(ready?"ok":"neu")+'">'+(ready?"Ready":"Processing")+'</span></td>'
          +'<td>'+(ready?'<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><audio controls preload="none" src="'+url+'" style="height:30px;max-width:190px"></audio><a class="btn bsm" href="'+url+'" download style="text-decoration:none">⬇ Download</a></div>':'<span style="font-size:11px;color:var(--faint)">No file</span>')+'</td>'
          +'</tr>';
      }).join(""):'<tr><td colspan="6" style="text-align:center;color:var(--faint);padding:18px">No office-visit recordings match the filters</td></tr>';
      const info=root.querySelector("#ovrTblPageInfo"); if(info)info.textContent="Page "+_ovrTblPageN+" of "+pages;
      _pgBtns("ovrTbl",_ovrTblPageN,pages);
    }
    function renderZoomTbl(){
      const head=root.querySelector("#zoomTblHead"); if(head)head.innerHTML=gridHead("zoomTbl");
      const rows=gridApply("zoomTbl",_zoomBase());
      const cnt=root.querySelector("#zoomTblCount"); if(cnt)cnt.textContent=String(rows.length);
      const body=root.querySelector("#zoomTblBody"); if(!body)return;
      const pages=Math.max(1,Math.ceil(rows.length/REC_PER));
      if(_zoomTblPageN>pages)_zoomTblPageN=pages; if(_zoomTblPageN<1)_zoomTblPageN=1;
      const pr=rows.slice((_zoomTblPageN-1)*REC_PER,(_zoomTblPageN-1)*REC_PER+REC_PER);
      body.innerHTML=pr.length?pr.map((r:any)=>{
        const url=r.meeting_url||""; const has=!!url; const ua=_recA(url);
        const status=r.status||(has?"Ready":"Pending");
        const shortUrl=url.length>42?url.slice(0,42)+"…":url;
        return '<tr>'
          +'<td class="mono" style="font-size:11px;white-space:nowrap">'+_recE(fmtIST(r.meeting_at||r.created_at))+'</td>'
          +'<td style="font-weight:600">'+_recE(r._cust||"—")+'</td>'
          +'<td>'+(has?'<a href="'+ua+'" target="_blank" rel="noopener" class="mono" style="font-size:11px;color:var(--brand)">'+_recE(shortUrl)+'</a>':'<span style="color:var(--faint)">—</span>')+'</td>'
          +'<td class="mono">'+_recE(_recDur(r.duration_seconds))+'</td>'
          +'<td><span class="chipb '+(has?"ok":"neu")+'">'+_recE(status)+'</span></td>'
          +'<td>'+(has?'<div style="display:flex;gap:6px;flex-wrap:wrap"><a class="btn bsm" href="'+ua+'" target="_blank" rel="noopener" style="text-decoration:none">🔗 Open</a><a class="btn bsm bp" href="'+ua+'" target="_blank" rel="noopener" style="text-decoration:none">▶ Play</a><a class="btn bsm" href="'+ua+'" target="_blank" rel="noopener" download style="text-decoration:none">⬇ Download</a></div>':'<span style="font-size:11px;color:var(--faint)">No link</span>')+'</td>'
          +'</tr>';
      }).join(""):'<tr><td colspan="6" style="text-align:center;color:var(--faint);padding:18px">No Zoom recordings match the filters</td></tr>';
      const info=root.querySelector("#zoomTblPageInfo"); if(info)info.textContent="Page "+_zoomTblPageN+" of "+pages;
      _pgBtns("zoomTbl",_zoomTblPageN,pages);
    }
    w._ovrTblSearch=()=>{ if(_ovrSearchT)clearTimeout(_ovrSearchT); _ovrSearchT=setTimeout(()=>{ _ovrQuery=(root.querySelector("#ovrTblSearch")as HTMLInputElement)?.value||""; _ovrTblPageN=1; renderOvrTbl(); },180); };
    w._ovrTblApply=()=>{ _ovrApplied={from:(root.querySelector("#ovrTblFrom")as HTMLInputElement)?.value||"",to:(root.querySelector("#ovrTblTo")as HTMLInputElement)?.value||""}; _ovrTblPageN=1; renderOvrTbl(); };
    w._ovrTblClear=()=>{ const f=root.querySelector("#ovrTblFrom")as HTMLInputElement; const t=root.querySelector("#ovrTblTo")as HTMLInputElement; if(f)f.value=""; if(t)t.value=""; _ovrApplied={from:"",to:""}; _ovrTblPageN=1; renderOvrTbl(); };
    w._ovrTblPage=(dir:any)=>{ _ovrTblPageN=_pgApply(_ovrTblPageN,dir); renderOvrTbl(); };
    w._ovrTblDownload=()=>{
      const rows=gridApply("ovrTbl",_ovrBase());
      if(!rows.length){ toast("Nothing to download"); return; }
      const out:string[][]=[["Recording Date & Time","Customer Name","Recorded By","Duration","Recording Status","Recording URL"]];
      rows.forEach((r:any)=>out.push([fmtIST(r.created_at),r._cust||"",r.recorded_by||"",_recDur(r.duration_seconds),(r.file_url||r.file_path)?"Ready":"Processing",_ovrUrl(r)]));
      _downloadCsv("wellnessos_office_recordings.csv",out); toast("Downloaded "+rows.length+" office recordings");
    };
    w._zoomTblSearch=()=>{ if(_zoomSearchT)clearTimeout(_zoomSearchT); _zoomSearchT=setTimeout(()=>{ _zoomQuery=(root.querySelector("#zoomTblSearch")as HTMLInputElement)?.value||""; _zoomTblPageN=1; renderZoomTbl(); },180); };
    w._zoomTblApply=()=>{ _zoomApplied={from:(root.querySelector("#zoomTblFrom")as HTMLInputElement)?.value||"",to:(root.querySelector("#zoomTblTo")as HTMLInputElement)?.value||""}; _zoomTblPageN=1; renderZoomTbl(); };
    w._zoomTblClear=()=>{ const f=root.querySelector("#zoomTblFrom")as HTMLInputElement; const t=root.querySelector("#zoomTblTo")as HTMLInputElement; if(f)f.value=""; if(t)t.value=""; _zoomApplied={from:"",to:""}; _zoomTblPageN=1; renderZoomTbl(); };
    w._zoomTblPage=(dir:any)=>{ _zoomTblPageN=_pgApply(_zoomTblPageN,dir); renderZoomTbl(); };
    w._zoomTblDownload=()=>{
      const rows=gridApply("zoomTbl",_zoomBase());
      if(!rows.length){ toast("Nothing to download"); return; }
      const out:string[][]=[["Meeting Date & Time","Customer Name","Zoom Recording Link","Meeting Duration","Recording Status"]];
      rows.forEach((r:any)=>out.push([fmtIST(r.meeting_at||r.created_at),r._cust||"",r.meeting_url||"",_recDur(r.duration_seconds),r.status||(r.meeting_url?"Ready":"Pending")]));
      _downloadCsv("wellnessos_zoom_recordings.csv",out); toast("Downloaded "+rows.length+" Zoom recordings");
    };
    // ===== Call Recordings (Advisor role only) — the advisor's OWN calls from call_recordings,
    // shown in place of the coach-oriented Office-Visit + Zoom tables. Reuses the same grid engine,
    // pager and CSV export. Scoped by initiated_by_email = the login who placed the call. =====
    let _callRecRows:any[]=[]; let _callRecQuery=""; let _callRecSearchT:any=null; let _callRecApplied:{from:string;to:string}={from:"",to:""}; let _callRecPageN=1;
    const _callDir=(r:any)=>(/in/i.test(r.direction||"")&&!/out/i.test(r.direction||""))?"Incoming":"Outgoing";
    const _callRecCols:any[]=[
      {key:"dt",label:"Call Date & Time",filter:true,text:(r:any)=>fmtIST(r.created_at)},
      {key:"cust",label:"Customer Name",filter:true,text:(r:any)=>r._cust||""},
      {key:"dir",label:"Direction",filter:true,text:(r:any)=>_callDir(r)},
      {key:"dur",label:"Duration",filter:true,text:(r:any)=>_recDur(r.duration_seconds)},
      {key:"status",label:"Call Status",filter:true,text:(r:any)=>r.call_status||"—"},
      {key:"act",label:"Recording",filter:false},
    ];
    regGrid("callRec",()=>_callRecCols,()=>renderCallRecTbl());
    async function loadCallRecordings(){
      const email=String((_currentUser&&_currentUser.email)||"").trim().toLowerCase();
      let rows:any[]=[];
      // Fetch then filter to the advisor's own calls by login email (case-insensitive) — mirrors how
      // _loadAdvCallStats attributes calls, so a case mismatch can't drop or leak rows.
      try{ const {data}=await supabase.from("call_recordings").select("*").order("created_at",{ascending:false}).limit(5000); rows=(data||[]).filter((r:any)=>String(r.initiated_by_email||"").trim().toLowerCase()===email); }catch(_){ rows=[]; }
      const ids=Array.from(new Set(rows.map((r:any)=>String(r.contact_id)).filter(Boolean)));
      const nameMap:Record<string,string>={};
      if(ids.length){ try{ const {data}=await supabase.from("leads").select("meta_lead_id,name").in("meta_lead_id",ids); (data||[]).forEach((l:any)=>{ if(l.meta_lead_id!=null) nameMap[String(l.meta_lead_id)]=l.name||""; }); }catch(_){} }
      rows.forEach((r:any)=>{ r._cust=nameMap[String(r.contact_id)]||r.to_number||("Lead #"+(r.contact_id||"?")); });
      _callRecRows=rows; _callRecPageN=1; renderCallRecTbl();
    }
    function _callRecBase(){
      let base=_callRecRows;
      const q=_callRecQuery.trim().toLowerCase();
      if(q) base=base.filter((r:any)=>[r._cust,r.to_number,r.call_status].some((v:any)=>String(v||"").toLowerCase().includes(q)));
      return _recDateFilter(base,_callRecApplied,(r:any)=>r.created_at);
    }
    function renderCallRecTbl(){
      const head=root.querySelector("#callRecHead"); if(head)head.innerHTML=gridHead("callRec");
      const rows=gridApply("callRec",_callRecBase());
      const cnt=root.querySelector("#callRecCount"); if(cnt)cnt.textContent=String(rows.length);
      const body=root.querySelector("#callRecBody"); if(!body)return;
      const pages=Math.max(1,Math.ceil(rows.length/REC_PER));
      if(_callRecPageN>pages)_callRecPageN=pages; if(_callRecPageN<1)_callRecPageN=1;
      const pr=rows.slice((_callRecPageN-1)*REC_PER,(_callRecPageN-1)*REC_PER+REC_PER);
      body.innerHTML=pr.length?pr.map((r:any)=>{
        const url=_recA(r.recording_url||""); const has=!!r.recording_url;
        const st=r.call_status||"—"; const stc=/complet|answer|connect/i.test(st)?"ok":/miss|fail|no.?answer|busy|reject|cancel/i.test(st)?"al":"warn";
        return '<tr>'
          +'<td class="mono" style="font-size:11px;white-space:nowrap">'+_recE(fmtIST(r.created_at))+'</td>'
          +'<td style="font-weight:600">'+_recE(r._cust||"—")+'</td>'
          +'<td>'+_recE(_callDir(r))+'</td>'
          +'<td class="mono">'+_recE(_recDur(r.duration_seconds))+'</td>'
          +'<td><span class="chipb '+stc+'">'+_recE(st)+'</span></td>'
          +'<td>'+(has?'<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><audio controls preload="none" src="'+url+'" style="height:30px;max-width:190px"></audio><a class="btn bsm" href="'+url+'" download style="text-decoration:none">⬇ Download</a></div>':'<span style="font-size:11px;color:var(--faint)">No recording</span>')+'</td>'
          +'</tr>';
      }).join(""):'<tr><td colspan="6" style="text-align:center;color:var(--faint);padding:18px">No call recordings match the filters</td></tr>';
      const info=root.querySelector("#callRecPageInfo"); if(info)info.textContent="Page "+_callRecPageN+" of "+pages;
      _pgBtns("callRec",_callRecPageN,pages);
    }
    w._callRecSearch=()=>{ if(_callRecSearchT)clearTimeout(_callRecSearchT); _callRecSearchT=setTimeout(()=>{ _callRecQuery=(root.querySelector("#callRecSearch")as HTMLInputElement)?.value||""; _callRecPageN=1; renderCallRecTbl(); },180); };
    w._callRecApply=()=>{ _callRecApplied={from:(root.querySelector("#callRecFrom")as HTMLInputElement)?.value||"",to:(root.querySelector("#callRecTo")as HTMLInputElement)?.value||""}; _callRecPageN=1; renderCallRecTbl(); };
    w._callRecClear=()=>{ const f=root.querySelector("#callRecFrom")as HTMLInputElement|null; const t=root.querySelector("#callRecTo")as HTMLInputElement|null; if(f)f.value=""; if(t)t.value=""; _callRecApplied={from:"",to:""}; _callRecPageN=1; renderCallRecTbl(); };
    w._callRecPage=(dir:any)=>{ _callRecPageN=_pgApply(_callRecPageN,dir); renderCallRecTbl(); };
    w._callRecDownload=()=>{
      const rows=gridApply("callRec",_callRecBase());
      if(!rows.length){ toast("Nothing to download"); return; }
      const out:string[][]=[["Call Date & Time","Customer Name","Direction","Duration","Call Status","Recording URL"]];
      rows.forEach((r:any)=>out.push([fmtIST(r.created_at),r._cust||"",_callDir(r),_recDur(r.duration_seconds),r.call_status||"",r.recording_url||""]));
      _downloadCsv("wellnessos_call_recordings.csv",out); toast("Downloaded "+rows.length+" call recordings");
    };
    // Populate the coach lead profile's read-only "Reception record" (Visited / Registered / Consent).
    // The table (#coachRecepBody) was a static "—" placeholder — never wired to data. Visited comes
    // from the lead's visited_at, Registered from the lead's appointment created_at. Consent isn't
    // persisted per-lead in the DB, so it reflects that it was recorded as part of registration.
    async function _coachFillRecep(lead:any){
      const tb=root.querySelector("#coachRecepBody"); if(!tb||!lead) return;
      let visited=(lead.visitedAt)||""; let registered="";
      try{ const {data}=await supabase.from("appointments").select("visited_at,created_at").eq("lead_id",String(lead.id)).order("created_at",{ascending:true}).limit(1); const a=data&&data[0]; if(a){ if(!visited) visited=a.visited_at||""; registered=a.created_at||""; } }catch(_){}
      if(String(_coachLeadId)!==String(lead.id)) return;   // the coach opened another client during the fetch
      const f=(d:any)=>d?fmtIST(d):"—";
      const consent=(visited||registered)?'<span class="chipb ok">✓ Recorded at registration</span>':"—";
      tb.innerHTML='<tr><td style="color:var(--muted)">Visited</td><td class="mono">'+f(visited)+'</td><td style="color:var(--muted)">Registered</td><td class="mono">'+f(registered)+'</td><td style="color:var(--muted)">Consent</td><td>'+consent+'</td></tr>';
    }
    function fillCoachDetail(lead:any){
      if(!lead) return;
      _coachLeadId=String(lead.id);
      // The Request-to-BDM chip must describe THIS client. Requests load lazily on the first open,
      // then repaint from memory on every later one.
      try{ _bdmReqs.length?_bdmPaintState():_bdmLoad(); }catch(_){}
      const e=(s:string)=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
      const name=lead.name||lead.phone||"Client";
      const initials=(name.match(/[A-Za-z0-9]/g)||["C","L"]).slice(0,2).join("").toUpperCase();
      const setT=(sel:string,t:string)=>{const el=root.querySelector(sel);if(el)el.textContent=t;};
      const setHt=(sel:string,h:string)=>{const el=root.querySelector(sel);if(el)el.innerHTML=h;};
      const setV=(id:string,v:string)=>{const el=root.querySelector("#"+id)as HTMLInputElement|null;if(el)el.value=v;};
      setT("#coachAv",initials||"CL"); setT("#coachName",name);
      setHt("#coachSub",'<span class="mono">'+e(lead.phone||"—")+'</span><span>·</span><span class="mono">Lead #'+e(String(lead.id))+'</span>');
      setHt("#coachBadges",'<span class="chipb '+(lead.isValid?'ok':'neu')+'">'+(lead.isValid?'Valid':'No phone')+'</span><span class="chipb neu">'+e((lead.source==="Manual"?"Manual":(lead.source||"Meta"))+" · "+(lead.lang||"Tamil"))+'</span><span class="chipb ok">Visited</span>');
      const cb=root.querySelector("#coachBadge"); if(cb) cb.textContent="Status: Open";
      const p=_coachPanelEl();
      if(p){
        p.querySelectorAll("input").forEach((i:any)=>{ if(i.type==="checkbox"||i.type==="radio")i.checked=false; else i.value=""; });
        p.querySelectorAll("textarea").forEach((t:any)=>t.value="");
        p.querySelectorAll("select").forEach((s:any)=>s.selectedIndex=0);
        p.querySelectorAll(".pill.on").forEach((b:any)=>b.classList.remove("on"));
        p.querySelectorAll(".chip-o.on").forEach((b:any)=>b.classList.remove("on"));
      }
      _coachAttachments=[]; renderCoachAtts();
      Object.keys(_payProofs).forEach(k=>delete _payProofs[k]);   // clear per-client payment proofs
      // A coupon belongs to ONE enrolment — never let it leak onto the next client opened.
      _coachCoupon=null;
      ["coupon","emiCoupon"].forEach(cid=>{ const el=root.querySelector("#"+cid)as HTMLInputElement|null; if(el) el.value=""; });
      ["couponRes","emiCouponRes"].forEach(cid=>{ const el=root.querySelector("#"+cid); if(el) el.innerHTML=""; });
      _coachConsStatus="Open";   // reset; a restored profile re-sets it via consAct
      _fuDates={}; _fuActiveKey="";   // clear per-status follow-up dates so a new client starts fresh
      const crS=root.querySelector("#crSugar")as HTMLInputElement|null; if(crS&&lead.sugar) crS.value=lead.sugar;
      setV("haConsultDate",new Date().toISOString().slice(0,10));
      const fuNotes=root.querySelector("#fuNotes"); if(fuNotes) fuNotes.innerHTML="";
      // Reset score-card auto tiles until recomputed for this client.
      _scAuto={attendance:0,followup:0};
      ["#scAttendanceV","#scFollowupV","#scOverallV"].forEach(s=>{const el=root.querySelector(s);if(el)el.textContent="—";});
      const rdFld=root.querySelector("#reviewDateFld")as HTMLElement|null; if(rdFld) rdFld.style.display="none";
      try{ _recStatusApply("open"); }catch(_){}   // default until the backend-derived state loads
      renderCoachOpenList();
      // Re-derive the recording status AFTER the saved profile restores its pills, so a backend
      // recording always wins (office_recordings is the source of truth) without a manual click.
      loadAndApplyCoach(lead).then(()=>{ try{ _renderScoreCard(String(lead.id)); }catch(_){} try{ _ovrRenderList(String(lead.id)); }catch(_){} });
      _coachSyncAdvisorReports(lead);
      _coachSyncScreeningVitals(lead);
      _coachRenderRecordings(_coachLeadId);
      renderCallLogs(lead,"#coachCallLog",()=>String(_coachLeadId));   // Call History tab: logs + recordings (same as Advisor)
      _ovrRenderList(_coachLeadId);
      _renderCoachPayHistory(_coachLeadId);
      _coachPopulateReadOnly(lead);
      try{ _coachFillRecep(lead); }catch(_){}   // fill the read-only Reception record (Visited / Registered / Consent)
      // Show the enrolled chip immediately from the client's known enrolled level (paid programs /
      // consStatus) — don't wait for the async profile restore, or a genuinely-enrolled client
      // flashes "Not enrolled" on open. The async restore re-runs this with any live consStatus.
      try{ _refreshPayEnrollChip(); }catch(_){}
    }
    async function _coachSyncScreeningVitals(lead:any){
      let sv:any=null;
      try{ const {data}=await supabase.from("leads").select("screening_vitals,assigned_to").eq("meta_lead_id",lead.id).limit(1); sv=data&&data[0]; }catch(_){}
      if(String(_coachLeadId)!==String(lead.id)) return;
      const vitals=(sv&&sv.screening_vitals)||null;
      if(vitals){
        const setV=(id:string,v:string)=>{const el=root.querySelector("#"+id)as HTMLInputElement|null;if(el&&v)el.value=v;};
        setV("cs_h",vitals.height||""); setV("cs_w",vitals.weight||""); setV("cs_bp",vitals.bp||"");
        setV("cs_pu",vitals.pulse||""); setV("cs_sp",vitals.spo2||""); setV("cs_wa",vitals.waist||"");
        setV("cs_te",vitals.temp||""); setV("cs_gl",vitals.glucose||"");
        if(vitals.height&&vitals.weight){ const m=parseFloat(vitals.height)/100; const bmi=parseFloat(vitals.weight)/(m*m); if(bmi>0){const el=root.querySelector("#cs_bmi")as HTMLInputElement;if(el)el.value=bmi.toFixed(1);} }
        const se=root.querySelector("#scrEmpty")as HTMLElement;if(se)se.style.display="none";
        const sd=root.querySelector("#scrData")as HTMLElement;if(sd)sd.style.display="grid";
        const sc=root.querySelector("#scrChip")as HTMLElement;if(sc){sc.textContent="Completed";sc.className="chipb ok";}
        const haH=root.querySelector("#haHeight")as HTMLInputElement; const haW=root.querySelector("#haWeight")as HTMLInputElement;
        if(haH&&!haH.value&&vitals.height) haH.value=vitals.height;
        if(haW&&!haW.value&&vitals.weight) haW.value=vitals.weight;
        _haBmiCalc();
        const haB=root.querySelector("#haBp")as HTMLInputElement; if(haB&&!haB.value&&vitals.bp) haB.value=vitals.bp;
        const haP=root.querySelector("#haPulse")as HTMLInputElement; if(haP&&!haP.value&&vitals.pulse) haP.value=vitals.pulse;
        const haT=root.querySelector("#haTemp")as HTMLInputElement; if(haT&&!haT.value&&vitals.temp) haT.value=vitals.temp;
      }
      const assignedTo=(sv&&sv.assigned_to)||"Health Coach";
      const setAtt=(id:string)=>{const el=root.querySelector("#"+id)as HTMLInputElement;if(el&&!el.value) el.value=assignedTo;};
      setAtt("haAttendedBy"); setAtt("haAttendedBy2"); setAtt("haAttendedBy3");
    }
    async function _coachPopulateReadOnly(lead:any){
      let adv:any=null;
      try{ const {data}=await supabase.from("leads").select("advisor_profile,source,language,campaign,assigned_to").eq("meta_lead_id",lead.id).limit(1); adv=data&&data[0]; }catch(_){}
      let appt:any=null;
      try{ const {data:ap}=await supabase.from("appointments").select("appt_date,appt_time").eq("lead_id",String(lead.id)).order("appt_date",{ascending:false}).limit(1); appt=ap&&ap[0]; }catch(_){}
      if(String(_coachLeadId)!==String(lead.id)) return;
      const esc=(s:string)=>(s||"--").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
      const rb=root.querySelector("#roBasic"); if(rb&&adv){
        const named=adv.advisor_profile?_advNamed(adv.advisor_profile.f):null;
        const occ=(named&&named["Occupation"])||"--"; const loc=(named&&named["Location"])||"--";
        // Priority is the star rating — saved in advisor_profile.stars (a separate array), NOT in the
        // positional `f`, so named["Priority"] is always empty. Render the filled stars instead.
        const _st=(adv.advisor_profile&&adv.advisor_profile.stars)||[]; const _pn=(_st as any[]).filter((x:any)=>!!x).length;
        const pr=_pn?"★".repeat(_pn):((named&&named["Priority"])||"--");
        rb.innerHTML='<tr><td style="color:var(--muted)">Occupation</td><td>'+esc(occ)+'</td><td style="color:var(--muted)">Language</td><td>'+esc(adv.language||lead.lang)+'</td><td style="color:var(--muted)">Source</td><td>'+esc((adv.source||lead.source||"Meta")+" · "+(adv.campaign||""))+'</td></tr>'
          +'<tr><td style="color:var(--muted)">Location</td><td>'+esc(loc)+'</td><td style="color:var(--muted)">Salesperson</td><td style="font-weight:600">'+esc(adv.assigned_to||"--")+'</td><td style="color:var(--muted)">Priority</td><td>'+esc(pr)+'</td></tr>';
      }
      const rs=root.querySelector("#roSugar"); if(rs&&adv&&adv.advisor_profile){
        const named=_advNamed(adv.advisor_profile.f);
        const sl=named["Sugar level"]||lead.sugar||"--"; const fp=(named["Fasting (mg/dL)"]||"--")+" / "+(named["Postprandial (mg/dL)"]||"--");
        const hb=named["HbA1c (%)"]||"--"; const trt=named["Treatment"]||"--"; const mg=named["Managing with"]||"--";
        rs.innerHTML='<tr><td style="color:var(--muted)">Sugar level</td><td>'+esc(sl)+'</td><td style="color:var(--muted)">Fasting / PP</td><td class="mono">'+esc(fp)+'</td><td style="color:var(--muted)">HbA1c</td><td class="mono" style="font-weight:700">'+esc(hb)+'</td></tr>'
          +'<tr><td style="color:var(--muted)">Treatment</td><td>'+esc(trt)+'</td><td style="color:var(--muted)">Managing now</td><td>'+esc(mg)+'</td><td style="color:var(--muted)">Eligibility</td><td>'+esc(named["Eligibility"]||"--")+'</td></tr>';
      }
      const rc=root.querySelector("#roCalls"); if(rc&&adv){
        const named=adv.advisor_profile?_advNamed(adv.advisor_profile.f):null;
        // Call status = the lead's live status (the profile stores a raw code); Appointment = the
        // lead's appointment date/time (was hardcoded "--"); Last note = the "Call notes" field
        // (the old "Last note" key never matched the form label).
        const cs=(lead.callStatus)||(named&&named["Call status"])||"--"; const hc=adv.assigned_to||lead.hc||"--";
        const apptTxt=appt?(fmtISTDate(appt.appt_date)+(appt.appt_time?(", "+appt.appt_time):"")):"--";
        const note=(named&&(named["Call notes"]||named["Last note"]||named["Call notes / objections"]))||"--";
        rc.innerHTML='<tr><td style="color:var(--muted)">Call status</td><td>'+esc(cs)+'</td><td style="color:var(--muted)">Appointment</td><td class="mono">'+esc(apptTxt)+'</td><td style="color:var(--muted)">HC</td><td style="font-weight:600">'+esc(hc)+'</td></tr>'
          +'<tr><td style="color:var(--muted)">Last call note</td><td colspan="5">'+esc(note)+'</td></tr>';
      }
    }
    // Whether a visited lead belongs in the Health Coach (Diabetes) queue. Diabetes / Diabetes
    // Counselling → yes. An already-enrolled coach client → yes (kept regardless of service, so an
    // enrolled diabetes client is never dropped). An explicit NON-diabetes modality — Blood Test,
    // Physiotherapy, Weight Loss, Sauna Bath, Cold Plunge, HBOT — → no (each has its own module).
    // A combined service that INCLUDES Diabetes still qualifies. Blank/unrecognised → yes (this is a
    // diabetes clinic, so an un-tagged prospect should still reach the coach).
    function _coachQualifies(c:any):boolean{
      const s=String(c.service||"").toLowerCase();
      if(/diabet/.test(s)) return true;
      if(/enrol/i.test(String(c.consStatus||""))||!!c.enrolledAt||/l[12]/i.test(String(c.enrolledLevel||""))) return true;
      return !/(blood|phys|weight|sauna|cold|hbot|hyperbaric)/.test(s);
    }
    async function loadCoachClients(){
      try{
        let res=await supabase.from("leads").select("meta_lead_id,name,phone,source,language,service,is_valid,sugar_poll,coach_profile,screening_vitals,visited_at,call_status,enrolled_at").not("visited_at","is",null).order("visited_at",{ascending:false}).limit(100);
        if(res.error&&/column|screening_vitals/i.test(res.error.message||"")){
          res=await supabase.from("leads").select("meta_lead_id,name,phone,source,language,service,is_valid,sugar_poll,coach_profile,visited_at,call_status,enrolled_at").not("visited_at","is",null).order("visited_at",{ascending:false}).limit(100) as any;
        }
        if(res.error) throw res.error;
        const data=res.data;
        const apptStages:Record<string,string>={}; const apptHc:Record<string,string>={};
        try{ const {data:appts}=await supabase.from("appointments").select("lead_id,stage,status,hc_pt").limit(500); (appts||[]).forEach((a:any)=>{ if(a.lead_id){ if(a.stage) apptStages[a.lead_id]=a.stage; if(a.hc_pt&&!apptHc[a.lead_id]) apptHc[a.lead_id]=a.hc_pt; } }); }catch(_){}
        // Enrolled program level (L1 / L2 / L1 + L2) from PAID payments — the source of truth for
        // what a client is ACTUALLY enrolled in. consStatus may not carry it (payment-driven
        // enrollment via Reception/Accounts), so we derive from paid programs and fall back to
        // consStatus's "Enrolled – Lx" when present. Independent of the Suggested-Program dropdown.
        const _paidProg:Record<string,Set<string>>={};
        // L1/L2 is a DIABETES-only enrollment concept. Count a program-tagged paid payment toward
        // the coaching level ONLY when it is a Diabetes payment — otherwise a Blood Test / Physio
        // payment historically mis-tagged with a program would falsely read the client as
        // "Enrolled – L2". The payment's own service decides it; when the payment carries no
        // service, fall back to the LEAD's service.
        const _diaLead=new Set((data||[]).filter((r:any)=>_recSvcCode(r.service||"")==="dia").map((r:any)=>String(r.meta_lead_id)));
        try{ const _ids=(data||[]).map((r:any)=>String(r.meta_lead_id)).filter(Boolean); if(_ids.length){ const {data:_pays}=await supabase.from("payments").select("lead_id,program,status,service").in("lead_id",_ids); (_pays||[]).forEach((p:any)=>{ if(p.status!=="paid"||!p.program) return; const k=String(p.lead_id); const isDiaPay=(p.service&&String(p.service).trim())?_recSvcCode(p.service)==="dia":_diaLead.has(k); if(!isDiaPay) return; (_paidProg[k]=_paidProg[k]||new Set()).add(String(p.program).toUpperCase()); }); } }catch(_){}
        const _enrLevelFor=(id:any,cons:string):string=>{ const set=_paidProg[String(id)]; return _levelUnion(cons, set?[...set]:[]); };   // UNION of consStatus level + paid programs
        _coachClients=(data||[]).map((r:any)=>{
          const cp=r.coach_profile; const sv=r.screening_vitals||null; const apptStage=apptStages[r.meta_lead_id]||"";
          let stage="screening";
          if(cp&&cp._stage) stage=cp._stage;
          else if(apptStage==="enrolled") stage="enrolled";
          else if(apptStage==="payment") stage="payment";
          else if(apptStage==="consultation"||apptStage==="health") stage="consultation";
          else if(cp&&cp.f&&cp.f.length>3) stage="assessment";
          else if(sv&&sv.screened_at) stage="assessment";
          return {id:r.meta_lead_id,name:r.name,phone:r.phone,source:r.source,lang:r.language,service:r.service||"",isValid:r.is_valid,sugar:r.sugar_poll||"",coachProfile:cp||null,_stage:stage,visitedAt:r.visited_at,hc:apptHc[r.meta_lead_id]||"",consStatus:(cp&&cp.consStatus)||"Open",callStatus:r.call_status||"",enrolledAt:r.enrolled_at||"",enrolledLevel:_enrLevelFor(r.meta_lead_id,(cp&&cp.consStatus)||"")};
        });
        // Health Coach queue = Diabetes only: drop leads whose service is a non-diabetes modality
        // (Blood Test / Physiotherapy / etc.) so they no longer clutter the queue. Applied at the
        // source, so the dashboard cards, Visited-clients table, Kanban and CSV export all agree.
        _coachClients=_coachClients.filter(_coachQualifies);
        // Reconcile historical enrollments: a client marked Enrolled on the coach side whose
        // lead.call_status hasn't caught up → sync it (DB + memory) so the Advisor dashboard,
        // Enrolled card and Enrolled-clients table reflect it without needing a re-save.
        _coachClients.filter((c:any)=>/enrol/i.test(c.consStatus||"")&&c.callStatus!=="Enrolled").forEach((c:any)=>{
          const cid=String(c.id); c.callStatus="Enrolled";
          const enrIso=c.enrolledAt||c.visitedAt||new Date().toISOString();   // best-effort enrollment time for historical rows
          if(!c.enrolledAt) c.enrolledAt=enrIso;
          supabase.from("leads").update({call_status:"Enrolled",enrolled_at:enrIso}).eq("meta_lead_id",cid).then(()=>{});
          const setE=(arr:any[])=>arr.forEach((l:any)=>{ if(String(l.id)===cid){ l.callStatus="Enrolled"; if(!l.enrolledAt) l.enrolledAt=enrIso; } });
          setE(_metaLeads); setE(_assignedExtras);
        });
      }catch(_){ _coachClients=[]; }
      _coachPopulateFilters();
      renderCoachOpenList();
    }
    let _coachView="list";
    let _coachQuery=""; let _coachSearchT:any=null;
    // Dropdown/date filters are APPLIED on demand (Apply button); search stays live.
    let _coachApplied:{from:string;to:string;coach:string;status:string;source:string;service:string}={from:"",to:"",coach:"all",status:"all",source:"all",service:"all"};
    // Central filter set — dashboard cards, Visited-clients table, List and Kanban all read
    // this, so everything stays in sync with the applied filters.
    function _coachFiltered(){
      const scope=_coachScope();   // Health Coach role → always locked to their own clients
      const from=_coachApplied.from, to=_coachApplied.to, coach=_coachApplied.coach, st=_coachApplied.status, src=_coachApplied.source, svc=_coachApplied.service;
      const q=_coachQuery.trim().toLowerCase();
      const fromT=from?new Date(from+"T00:00:00").getTime():0;
      const toT=to?new Date(to+"T23:59:59").getTime():0;
      const _svcScope=_serviceScope();   // Service line → second, independent axis
      return _coachClients.filter((c:any)=>{
        if(!_serviceAllows(c,_svcScope)) return false;
        if(scope){ if((c.hc||"")!==scope) return false; }
        else if(coach!=="all"&&(c.hc||"")!==coach) return false;
        if(st!=="all"&&!_coachConsMatch(c,st)) return false;   // filter by consultation status (matches cards + column; L1+L2 matches both Enrolled cards)
        if(src!=="all"&&(c.source||"")!==src) return false;
        if(svc!=="all"&&!_svcCanonMatch(c.service,svc)) return false;
        if(fromT||toT){ const t=c.visitedAt?new Date(c.visitedAt).getTime():0; if(fromT&&t<fromT) return false; if(toT&&t>toT) return false; }
        if(q&&![c.name,c.phone,c.source,c.hc].some((v:any)=>String(v||"").toLowerCase().indexOf(q)>=0)) return false;
        return true;
      });
    }
    // Raw consultation status persisted in coach_profile.consStatus (live profile wins over snapshot).
    function _coachRawCons(c:any){ return (c&&((c.coachProfile&&c.coachProfile.consStatus)||c.consStatus))||"Open"; }
    // Consultation status label used across the coach dashboard, table and kanban. The CANONICAL
    // enrolled state (enrolled_at, or a paid program level) OVERRIDES the mutable consultation-status
    // disposition: an actually-enrolled client must read "Enrolled – Lx" and land in the Enrolled
    // cards, never a stale "Will Join Immediately". Mirrors the Advisor haEffStatus fix. Non-enrolled
    // clients keep their stored status.
    function _coachConsOf(c:any){
      const stored=_coachRawCons(c);
      const lvl=(c&&c.enrolledLevel)||"";
      const enrolled=!!(c&&c.enrolledAt)||/enrol/i.test(stored)||!!lvl;
      if(!enrolled) return stored;
      const L=lvl||(/l1\s*\+\s*l2/i.test(stored)?"L1 + L2":/l2/i.test(stored)?"L2":/l1/i.test(stored)?"L1":"");
      return L?("Enrolled – "+L):"Enrolled";
    }
    // Does client c belong in the given dashboard card / kanban column / status-filter value?
    // Exact match. The Enrolled cards partition by EXACT membership — L1 only / L2 only / both /
    // level unrecorded — so each enrolled client matches exactly one card and the faces sum to
    // Total Leads. (The old membership rule matched an L1 + L2 client on both cards, which is what
    // made the row overshoot the total.)
    function _coachConsMatch(c:any,label:string){
      if(label==="Instalment 2 pending") return _coachInst2Pending(c);   // payment state, not a consStatus
      const s=_coachConsOf(c);
      if(/^Enrolled/i.test(label)){
        if(!/enrol/i.test(s)) return false;
        const sl1=/l1/i.test(s), sl2=/l2/i.test(s);
        if(/level pending/i.test(label)) return !sl1&&!sl2;
        return (/l1/i.test(label))===sl1 && (/l2/i.test(label))===sl2;
      }
      return s===label;
    }
    function _coachPopulateFilters(){
      const fill=(sel:string,vals:string[],allLabel:string)=>{ const el=root.querySelector(sel)as HTMLSelectElement|null; if(!el) return; const cur=el.value; const uniq=Array.from(new Set(vals.filter(Boolean))).sort(); el.innerHTML='<option value="all">'+allLabel+'</option>'+uniq.map((v:string)=>'<option>'+(v||"").replace(/</g,"&lt;")+'</option>').join(""); if(Array.from(el.options).some(o=>o.value===cur)) el.value=cur; };
      // The coach filter must list EVERY active Health Coach from the Assignees master
      // (single source of truth), not only those who already have a visited client.
      // Union with any coach present on a client so historical assignments still show.
      const _cScope=_coachScope();
      const _cc=root.querySelector("#coCoach")as HTMLSelectElement|null;
      if(_cScope&&_cc){
        // Health Coach role: only their own name, selected + locked (can't view other coaches).
        const nm=_advisorName()||"My clients"; const lbl=nm.replace(/</g,"&lt;");
        _cc.innerHTML='<option value="'+lbl+'">'+lbl+'</option>'; _cc.value=lbl; _cc.disabled=true; _cc.title="You can only view your own clients";
        _coachApplied.coach=nm;
      } else {
        if(_cc){ _cc.disabled=false; _cc.title=""; }
        const coachNames=_assignees.filter((a:any)=>a.is_active&&a.role==="Health Coach").map((a:any)=>a.name)
          .concat(_coachClients.map((c:any)=>c.hc));
        fill("#coCoach",coachNames,"All health coaches");
      }
      // Master list ∪ whatever the clients actually carry — never only what this coach happens to
      // have (that is what limited the dropdown to 2 options).
      _fillSrcMaster("#coSource",_coachClients.map((c:any)=>c.source),"All sources");
      _fillSvcMaster("#coService","All services",COACH_SERVICES);   // counselling lines only — see COACH_SERVICES
      const stEl=root.querySelector("#coStatus")as HTMLSelectElement|null;
      if(stEl){ const cur=stEl.value; const eo=(s:string)=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;"); stEl.innerHTML='<option value="all">All statuses</option>'+_coachStatusCards.map((s:string)=>'<option value="'+eo(s)+'">'+eo(s)+'</option>').join(""); if(Array.from(stEl.options).some(o=>o.value===cur)) stEl.value=cur; }
    }
    // Apply the staged coach filters (date / coach / status / service) → refresh list + kanban.
    w._coachFilterApply=()=>{
      _coachApplied={
        from:(root.querySelector("#coFrom")as HTMLInputElement)?.value||"",
        to:(root.querySelector("#coTo")as HTMLInputElement)?.value||"",
        coach:(root.querySelector("#coCoach")as HTMLSelectElement)?.value||"all",
        status:(root.querySelector("#coStatus")as HTMLSelectElement)?.value||"all",
        source:(root.querySelector("#coSource")as HTMLSelectElement)?.value||"all",
        service:(root.querySelector("#coService")as HTMLSelectElement)?.value||"all",
      };
      renderCoachOpenList();
    };
    w._coachFilterClear=()=>{
      const set=(id:string,v:string)=>{const el=root.querySelector("#"+id)as any; if(el)el.value=v;};
      set("coFrom",""); set("coTo",""); set("coCoach","all"); set("coStatus","all"); set("coSource","all"); set("coService","all");
      _coachApplied={from:"",to:"",coach:"all",status:"all",source:"all",service:"all"};
      renderCoachOpenList();
    };
    // Search stays live (not gated by Apply).
    w._coachSearch=()=>{ if(_coachSearchT)clearTimeout(_coachSearchT); _coachSearchT=setTimeout(()=>{ _coachQuery=(root.querySelector("#coSearch")as HTMLInputElement)?.value||""; renderCoachOpenList(); },180); };
    // Visited-clients table search box (in the table header) — drives the same live query as the
    // top search, filtered by client name / phone / coach, and resets to page 1.
    w._coachCliSearch=()=>{ if(_coachSearchT)clearTimeout(_coachSearchT); _coachSearchT=setTimeout(()=>{ _coachQuery=(root.querySelector("#coCliSearch")as HTMLInputElement)?.value||""; _coachCliPage=1; const top=root.querySelector("#coSearch")as HTMLInputElement|null; if(top)top.value=_coachQuery; renderCoachOpenList(); },180); };
    w._coachToggleView=(v:string)=>{ _coachView=v; renderCoachOpenList(); };
    // ===== Health Coach dashboard cards (by consultation status) + Visited-clients table =====
    // The Enrolled cards are EXCLUSIVE: L1 = L1 only, L2 = L2 only, and a client in both programs
    // counts once on "Enrolled – L1 + L2". Membership-style counting (both cards) made the row sum
    // past Total Leads, which read as the dashboard losing count (reported). "Enrolled – Level
    // pending" catches an enrolled client whose program isn't recorded yet — without it those
    // clients appeared on NO card at all. It renders only when non-empty.
    const _coachStatusCards=["Open","Will Join Immediately","This Week","End of Month","Next Month","Enrolled – L1","Enrolled – L2","Enrolled – L1 + L2","Enrolled – Level pending","Already Paid – Before Consultation","Already Paid – After Consultation","Not Interested","Refund","Instalment 2 pending"];
    let _coachDashSel="";
    // "Instalment 2 pending" is a PAYMENT state, not a consultation status: installment 1 collected
    // for some program but installment 2 not yet. Derived from the same guarded per-lead program
    // aggregation everything else uses (_progPayByLead — BT/Physio fees never count), so this card,
    // Reception's card and the enrollment labels always agree.
    function _coachInst2Pending(c:any){
      const m=_progPayByLead[String(c.id)]||{};
      return Object.keys(m).some(k=>{ const o=m[k]; return !!(o&&o.inst1Paid&&!o.inst2Paid); });
    }
    // The pending detail shown when the card is selected: program(s) awaiting installment 2 plus
    // the outstanding balance / next due date from the shared installment aggregation (_recInst).
    function _coachInst2Detail(c:any):string{
      const m=_progPayByLead[String(c.id)]||{};
      const progs=Object.keys(m).filter(k=>{ const o=m[k]; return !!(o&&o.inst1Paid&&!o.inst2Paid); });
      const inst=(_recInst||{})[String(c.id)];
      const bal=inst&&inst.balance?("₹"+Number(inst.balance).toLocaleString("en-IN")+" due"):"Instalment 2 due";
      const when=inst&&inst.dueDate?(" by "+fmtISTDate(inst.dueDate)):"";
      return (progs.join(" + ")||"—")+" · "+bal+when;
    }
    function renderCoachDash(){
      const el=root.querySelector("#coachDash"); if(!el) return;
      const list=_coachFiltered();   // cards reflect the applied filter bar (NOT the card selection)
      const counts:Record<string,number>={}; _coachStatusCards.forEach(l=>counts[l]=0);
      // Exclusive partition: every client lands on exactly ONE status card, so the faces add up to
      // Total Leads (membership counting put an L1 + L2 client on both Enrolled cards → 120 vs 70,
      // reported). Enrolled with no recorded program goes to "Level pending" instead of vanishing.
      list.forEach((c:any)=>{ const s=_coachConsOf(c);
        if(/enrol/i.test(s)){
          const l1=/l1/i.test(s), l2=/l2/i.test(s);
          const k=l1&&l2?"Enrolled – L1 + L2":(l1?"Enrolled – L1":(l2?"Enrolled – L2":"Enrolled – Level pending"));
          counts[k]=(counts[k]||0)+1;
        }
        else counts[s]=(counts[s]||0)+1;
      });
      counts["Instalment 2 pending"]=list.filter(_coachInst2Pending).length;   // payment state, orthogonal to consStatus
      const e=(s:string)=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
      // Total Leads leads the set and doubles as "show everything" (clicking clears the selection).
      // The status cards sum to it; Instalment 2 pending sits OUTSIDE the sum — it is a payment
      // overlay whose clients are already counted on their status card (stated in its tooltip; the
      // on-card explainer text was removed on request).
      const total=list.length;
      const on0=!_coachDashSel;
      el.innerHTML='<div class="metric" title="Every client in this view — clears the card filter" style="cursor:pointer'+(on0?';outline:2px solid var(--brand);outline-offset:-1px':'')+'" onclick="window._coachDashClick(\'\')"><div class="ml">Total Leads</div><div class="mv">'+total+'</div></div>'
      +_coachStatusCards.filter(l=>l!=="Enrolled – Level pending"||(counts[l]||0)>0).map(l=>{
        const on=_coachDashSel===l;
        const tip=l==="Instalment 2 pending"?' title="Payment state — these clients are already counted on their status card"':'';
        return '<div class="metric"'+tip+' style="cursor:pointer'+(on?';outline:2px solid var(--brand);outline-offset:-1px':'')+'" onclick="window._coachDashClick(\''+e(l).replace(/'/g,"\\'")+'\')"><div class="ml">'+e(l)+'</div><div class="mv">'+(counts[l]||0)+'</div></div>';
      }).join("");
    }
    w._coachDashClick=(label:string)=>{ _coachDashSel=(_coachDashSel===label)?"":label; _coachCliPage=1; renderCoachOpenList(); };
    // Top-right "Consultation Status" dropdown — drives the same selection the dashboard cards use,
    // so it filters both the cards (highlights the match) and the Visited-clients table, persists
    // across List/Kanban, and composes with the applied filter bar (all via _coachCliBase).
    w._coachConsFilter=(v:string)=>{ _coachDashSel=v||""; _coachCliPage=1; renderCoachOpenList(); };
    const COACH_CLI_PER=12; let _coachCliPage=1;
    // The Commitment Date column appears only for the follow-up statuses that use it.
    function _showCommitCol(){ return ["This Week","End of Month","Next Month"].indexOf(_coachDashSel)>=0; }
    // The Pending Installment column appears only while the "Instalment 2 pending" card is selected.
    function _showInst2Col(){ return _coachDashSel==="Instalment 2 pending"; }
    // When installment 1 was actually COLLECTED (its paid payment row), not when the plan was made.
    function _coachInst1At(c:any):string{
      const inst=(_recInst||{})[String(c&&c.id)];
      const r1=inst&&inst.rows?inst.rows.find((r:any)=>Number(r.installment_number)===1&&r.status==="paid"):null;
      const iso=r1?(r1.paid_at||r1.created_at):"";
      return iso?fmtIST(iso):"—";
    }
    // When the balance falls due. Prefer the stored due_date on the installment-2 row (stamped when
    // the collection request was sent); otherwise derive the documented "+30 days after Inst-1 date"
    // so the column still answers the question for plans saved before due dates were persisted.
    function _coachBalDueAt(c:any):string{
      const inst=(_recInst||{})[String(c&&c.id)];
      if(!inst||!inst.rows) return "—";
      // Outstanding amount leads the cell so the column reads "₹X · when" (requested).
      const _bal=Number(inst.balance)||0;
      const _pre=_bal>0?("₹"+_bal.toLocaleString("en-IN")+" · "):"";
      const r2=inst.rows.find((r:any)=>Number(r.installment_number)===2);
      if(r2&&r2.due_date) return _pre+fmtIST(r2.due_date);
      const r1=inst.rows.find((r:any)=>Number(r.installment_number)===1&&r.status==="paid");
      const base=r1?(r1.paid_at||r1.created_at):"";
      if(!base) return "—";
      const d=new Date(base); if(isNaN(d.getTime())) return "—";
      d.setDate(d.getDate()+30);
      return _pre+fmtIST(d.toISOString())+" (auto +30d)";
    }
    function _coachCommitOf(c:any){ const d=c&&c.coachProfile&&c.coachProfile.commitDate; return d?fmtISTDate(d):"—"; }
    function _coachCliColsFn(){
      const cols:any[]=[
        {key:"name",label:"Lead Name",filter:true,text:(c:any)=>c.name||""},
        {key:"phone",label:"Phone",filter:true,text:(c:any)=>c.phone||""},
        {key:"source",label:"Source",filter:true,text:(c:any)=>c.source||""},
        {key:"service",label:"Service",filter:true,text:(c:any)=>c.service||""},
        {key:"hc",label:"Health Coach",filter:true,text:(c:any)=>c.hc||"—"},
        {key:"cons",label:"Consultation Status",filter:true,text:(c:any)=>_coachConsOf(c)},
        {key:"visited",label:"Visited Date & Time",filter:true,text:(c:any)=>fmtIST(c.visitedAt)},
        {key:"act",label:"Action",filter:false,head:"Action"},
      ];
      // Insert "Commitment Date" immediately AFTER Consultation Status for the three plan statuses.
      if(_showCommitCol()){ const i=cols.findIndex((c:any)=>c.key==="cons"); cols.splice(i+1,0,{key:"commit",label:"Commitment Date",filter:true,text:(c:any)=>_coachCommitOf(c)}); }
      // Insert "Pending Installment" (program · balance · due date) while that card is selected.
      if(_showInst2Col()){ const i=cols.findIndex((c:any)=>c.key==="cons"); cols.splice(i+1,0,{key:"inst2",label:"Pending Installment",filter:true,text:(c:any)=>_coachInst2Detail(c)}); }
      // "Instalment 2 pending" also gets the two dates that decide when to chase: when installment 1
      // was collected, and when the balance is due. Placed AFTER "Visited Date & Time" so the row
      // reads chronologically (visited → inst-1 paid → balance due). Both are filterable like every
      // other column in this grid.
      if(_showInst2Col()){
        const v=cols.findIndex((c:any)=>c.key==="visited");
        cols.splice(v+1,0,
          {key:"inst1at",label:"Inst-1 Date & Time",filter:true,text:(c:any)=>_coachInst1At(c)},
          {key:"baldue",label:"Balance Due Date & Time",filter:true,text:(c:any)=>_coachBalDueAt(c)});
      }
      return cols;
    }
    regGrid("coachClients",_coachCliColsFn,()=>renderCoachClientsTable());
    function _coachCliBase(){ let base=_coachFiltered(); if(_coachDashSel) base=base.filter((c:any)=>_coachConsMatch(c,_coachDashSel)); return base; }
    function renderCoachClientsTable(){
      const head=root.querySelector("#coachClientsHead"); if(head)head.innerHTML=gridHead("coachClients");
      const rows=gridApply("coachClients",_coachCliBase());
      const cnt=root.querySelector("#coachCliCount"); if(cnt)cnt.textContent=String(rows.length);
      const body=root.querySelector("#coachClientsBody"); if(!body) return;
      const total=rows.length; const pages=Math.max(1,Math.ceil(total/COACH_CLI_PER));
      if(_coachCliPage>pages)_coachCliPage=pages; if(_coachCliPage<1)_coachCliPage=1;
      const pageRows=rows.slice((_coachCliPage-1)*COACH_CLI_PER,(_coachCliPage-1)*COACH_CLI_PER+COACH_CLI_PER);
      const e=(s:any)=>(s==null?"":String(s)).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
      body.innerHTML=pageRows.length?pageRows.map((c:any)=>{
        const active=String(c.id)===String(_coachLeadId);
        return '<tr'+(active?' style="background:var(--brand-tint)"':'')+'>'
          +'<td style="font-weight:600;cursor:pointer;color:var(--brand)" onclick="window._coachOpen(\''+e(String(c.id))+'\')">'+e(c.name||"—")+' ↗</td>'
          +'<td class="mono">'+e(c.phone||"—")+'</td>'
          +'<td><span class="tag">'+e(c.source||"—")+'</span></td>'
          +'<td>'+e(c.service||"—")+'</td>'
          +'<td>'+e(c.hc||"—")+'</td>'
          +'<td><span class="chipb neu">'+e(_coachConsOf(c))+'</span></td>'
          +(_showCommitCol()?('<td class="mono" style="font-size:11px;white-space:nowrap">'+e(_coachCommitOf(c))+'</td>'):'')
          +(_showInst2Col()?('<td style="font-size:11.5px;white-space:nowrap"><span class="chipb warn">'+e(_coachInst2Detail(c))+'</span></td>'):'')
          +'<td class="mono" style="font-size:11px;white-space:nowrap">'+e(fmtIST(c.visitedAt))+'</td>'
          // Order must mirror _coachCliColsFn: these two sit directly after Visited Date & Time.
          +(_showInst2Col()?('<td class="mono" style="font-size:11px;white-space:nowrap">'+e(_coachInst1At(c))+'</td>'):'')
          +(_showInst2Col()?('<td class="mono" style="font-size:11px;white-space:nowrap">'+e(_coachBalDueAt(c))+'</td>'):'')
          +'<td><button class="btn bsm bp" onclick="window._coachOpen(\''+e(String(c.id))+'\')">Open</button></td></tr>';
      // colspan must track the columns actually rendered: base 8, +1 Commitment, +3 for the
      // Instalment-2 view (Pending Installment, Inst-1 date, Balance due date).
      }).join(""):'<tr><td colspan="'+(8+(_showCommitCol()?1:0)+(_showInst2Col()?3:0))+'" style="text-align:center;color:var(--faint);padding:18px">No visited clients match the filters</td></tr>';
      const info=root.querySelector("#coachCliPageInfo"); if(info)info.textContent="Page "+_coachCliPage+" of "+pages;
      _pgBtns("coachCli",_coachCliPage,pages);
    }
    w._coachCliPage=(dir:any)=>{ _coachCliPage=_pgApply(_coachCliPage,dir); renderCoachClientsTable(); };
    w._coachCliDownload=()=>{
      const rows=gridApply("coachClients",_coachCliBase());
      if(!rows.length){ toast("Nothing to download"); return; }
      const out:string[][]=[["Lead Name","Phone","Source","Service","Health Coach","Consultation Status","Visited Date & Time"]];
      rows.forEach((c:any)=>out.push([c.name||"",c.phone||"",c.source||"",c.service||"",c.hc||"",_coachConsOf(c),fmtIST(c.visitedAt)]));
      _downloadCsv("wellnessos_visited_clients.csv",out);
      toast("Downloaded "+rows.length+" visited clients");
    };
    // Master render for the Visited-clients area: dashboard cards + the List/Kanban toggle,
    // then either the table (List) or the kanban board (Kanban) — both honour the same
    // applied filters + dashboard-card selection (_coachCliBase).
    function renderCoachOpenList(){
      try{ renderCoachDash(); }catch(_){}
      const tog=root.querySelector("#coachViewToggle");
      if(tog) tog.innerHTML='<button class="pill'+(_coachView==="list"?" on":"")+'" onclick="window._coachToggleView(\'list\')">List View</button><button class="pill'+(_coachView==="kanban"?" on":"")+'" onclick="window._coachToggleView(\'kanban\')">Kanban View</button>';
      const csf=root.querySelector("#coachConsFilter")as HTMLSelectElement|null;
      if(csf){ const eo=(s:string)=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;"); csf.innerHTML='<option value="">All Status</option>'+_coachStatusCards.map((s:string)=>'<option value="'+eo(s)+'">'+eo(s)+'</option>').join(""); csf.value=_coachDashSel; }
      const kb=root.querySelector("#coachKanban")as HTMLElement|null;
      const tw=root.querySelector("#coachCliTableWrap")as HTMLElement|null;
      if(_coachView==="kanban"){
        if(tw)tw.style.display="none";
        const base=_coachCliBase();
        const cnt=root.querySelector("#coachCliCount"); if(cnt)cnt.textContent=String(base.length);
        if(kb){ kb.style.display=""; _renderCoachKanban(kb,base); }
      } else {
        if(kb)kb.style.display="none";
        if(tw)tw.style.display="";
        renderCoachClientsTable();
      }
    }
    function _renderCoachKanban(kb:HTMLElement,list:any[]){
      const e=(s:string)=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
      // Kanban columns mirror the consultation-status values (the same set the dashboard
      // cards, List view and All-Status dropdown use) so every view stays in sync.
      const stageColors=["#17A87B","#378ADD","#7B6CD9","#C07F0E","#0B6B4C","#E8A817","#0EA5A0","#D8442B","#A855F7","#EF4444","#64748B"];
      const cols=_coachStatusCards.map((label:string,ci:number)=>({label,color:stageColors[ci%stageColors.length],filter:(c:any)=>_coachConsMatch(c,label)}))
        // "Level pending" is a data-gap catch bucket — like its dashboard card it only appears when
        // it actually holds someone, so a clean book never shows an empty column for it.
        .filter(col=>col.label!=="Enrolled – Level pending"||list.some(col.filter));
      const colors=["#17A87B","#378ADD","#7B6CD9","#C07F0E","#D8442B","#5B9BD5","#A855F7","#EF4444"];
      kb.innerHTML='<div style="display:flex;gap:12px;min-width:max-content;padding-bottom:8px">'+cols.map(col=>{
        const items=list.filter(col.filter);
        return '<div style="min-width:220px;max-width:260px;flex:1;background:var(--surface);border:1px solid var(--line);border-radius:10px;overflow:hidden">'
          +'<div style="padding:10px 12px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:6px"><span style="width:9px;height:9px;border-radius:50%;background:'+col.color+';flex-shrink:0;display:inline-block"></span><span style="font-weight:700;font-size:12px">'+e(col.label)+'</span><span class="chipb neu" style="margin-left:auto;font-size:11px">'+items.length+'</span></div>'
          +'<div style="padding:8px;display:flex;flex-direction:column;gap:6px;min-height:60px">'
          +(items.length?items.map((c:any,i:number)=>{
            const active=String(c.id)===String(_coachLeadId);
            const init=(c.name||"??").split(" ").map((w:string)=>w[0]||"").join("").substring(0,2).toUpperCase();
            return '<div onclick="window._coachOpen(\''+e(String(c.id))+'\')" style="cursor:pointer;padding:10px;border-radius:8px;border:1px solid '+(active?"var(--brand)":"var(--line)")+';background:'+(active?"var(--brand-tint)":"#fff")+';transition:box-shadow .15s" onmouseover="this.style.boxShadow=\'0 2px 8px rgba(0,0,0,.08)\'" onmouseout="this.style.boxShadow=\'none\'">'
              +'<div style="display:flex;align-items:center;gap:8px"><span class="avs" style="background:'+colors[i%colors.length]+';width:28px;height:28px;font-size:10px;flex-shrink:0">'+init+'</span>'
              +'<div style="flex:1;min-width:0"><div style="font-weight:600;font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+e(c.name||c.phone||"Client")+'</div>'
              +'<div style="font-size:10.5px;color:var(--muted);margin-top:1px">'+e(c.source||"Meta")+(c.lang?" · "+e(c.lang):"")+'</div></div></div></div>';
          }).join(""):'<div style="text-align:center;color:var(--faint);font-size:11px;padding:12px 0">No clients</div>')
          +'</div></div>';
      }).join("")+'</div>';
    }
    w._coachOpen=(id:string)=>{ const c=_coachClients.find((x:any)=>String(x.id)===String(id)); if(!c){toast("Client not found");return;} fillCoachDetail(c); toast("Opened: "+(c.name||c.phone||"client"));
      // Same pattern as the Advisor page: scroll down to the opened client's detail card. Longer delay
      // than the advisor (fillCoachDetail does more async rendering) so the card is at its final position.
      setTimeout(()=>{ try{ _scrollMainTo(root.querySelector("#s-coach .chead")as HTMLElement|null); }catch(_){} },300); };
    // The /db gateway RESOLVES {error} (it never throws), so `try{ await write }catch{}` can't catch a
    // failed write and the returned error is silently dropped. This awaits a write, and on failure
    // toasts + returns false so the caller can ABORT — critically, so an insert never runs on top of
    // a delete that failed (the source of duplicate payment rows). Returns true on success.
    async function _dbOk(p:Promise<any>,what:string):Promise<boolean>{
      try{ const r:any=await p; if(r&&r.error){ toastErr(what+" failed: "+(r.error.message||"database error")); return false; } return true; }
      catch(e:any){ toastErr(what+" failed: "+(e?.message||"network error")); return false; }
    }
    // A payment reaching "paid" is ITSELF the enrolling event — stamp leads.enrolled_at via the
    // same shared writer Reception/Accounts use, right here at the actual save. Previously
    // enrollment only fired from the payment-section Status DROPDOWN's onchange (_payStSel) —
    // a secondary UI signal, not the save action itself. A dropdown's onchange never fires if its
    // value doesn't actually change (e.g. it already reads "1st Paid" and the coach just types the
    // amount and clicks Save, or the value was restored programmatically via _setPayStatus, which
    // is explicitly documented as "without firing enrollment"). The payments row still gets
    // written in that case, so Coach/Reception (which derive "enrolled" live from payment rows)
    // keep showing it correctly — only Advisor (which trusts leads.enrolled_at alone) went stale.
    // Root-caused against a real lead (Dinesh Iyer, 1073279318552471): installment-1 paid ₹15,000,
    // but enrolled_at stayed null. _enrollLeadShared is idempotent (preserves an existing
    // enrolled_at, no duplicate activity log), so calling it on every save is safe.
    async function _ensureEnrolledFromPayment(id:string,prog:string):Promise<void>{
      let level=(prog==="L1")?"L1":(prog==="L2"?"L2":"L1 + L2");
      const cur=_coachConsStatus||""; const hasL1=/\bL1\b/.test(cur), hasL2=/\bL2\b/.test(cur);
      if(level==="L2"&&hasL1) level="L1 + L2"; else if(level==="L1"&&hasL2) level="L1 + L2";
      const iso=await _enrollLeadShared(id,"Payment saved",level);
      if(iso!==null){ try{ _setPayEnrollDisplay(level,iso); _refreshPayEnrollChip(); }catch(_){} }
    }
    // Persist the coach's collected payment to the `payments` table so it shows in the
    // payment history + Accounts. Handles Full / 2× Installment / Advance (each re-written
    // so re-saving doesn't duplicate). EMI is a financier flow (money goes to the provider,
    // not collected by us) so it stays tracked in coach_profile only.
    async function _persistInstallments(id:string){
      const pm=(root.querySelector("#payMethod")as HTMLSelectElement)?.value||"";
      const total=_payNetPrice();   // the plan is worth the COUPON-NET price — ₹29,500 on a ₹30,000 L2 with a ₹500 coupon IS fully paid
      const _prog=_curProgram();   // tag payments per program (L1 / L2 / L1 + L2) — see _applyPaymentLocks
      const val=(sel:string)=>((root.querySelector(sel)as HTMLInputElement|HTMLSelectElement|null)?.value)||"";
      const iso=(d:string)=>d?new Date(d).toISOString():new Date().toISOString();
      // Proof for a row: a freshly attached file, else the proof already stored on the coach's saved
      // row for that installment. _payProofs is cleared on every client open, and this function's
      // commit() DELETES + re-inserts the coach rows from the form — without the fallback, every
      // re-save of an installment client silently dropped the stored proof_url.
      const proof=(cid:string)=>{
        const p=_payProofs[cid]; if(p) return {proof_url:p.url,proof_name:p.name};
        const n=cid==="i2Inst1Proof"?1:(cid==="i2BalProof"?2:0);
        if(n){ const r=(_coachPayRows||[]).find((x:any)=>x.payment_type==="installment"&&Number(x.installment_number)===n&&x.status==="paid"&&x.proof_url&&!/reception|pos/i.test(String(x.collected_by||"")));
          if(r) return {proof_url:r.proof_url,proof_name:r.proof_name||"proof"}; }
        return {};
      };
      const commit=async(ptype:string,rows:any[],label:string,collected:number)=>{
        // Scope the re-write to THIS program so an L2 save never wipes the L1 payment (and vice versa).
        // Abort if the delete failed — inserting on top of rows we couldn't clear duplicates them.
        if(!(await _dbOk(supabase.from("payments").delete().eq("lead_id",id).eq("payment_type",ptype).eq("program",_prog),"Payment update"))) return;
        if(!rows.length) return;
        if(!(await _dbOk(supabase.from("payments").insert(rows),"Payment save"))) return;
        logActivity(id,[{action:"Payment",field:label,new:"₹"+collected.toLocaleString("en-IN")+(total?(" of ₹"+total.toLocaleString("en-IN")+", balance ₹"+Math.max(0,total-collected).toLocaleString("en-IN")):"")}]);
        if(String(_coachLeadId)===id) _renderCoachPayHistory(id);
      };
      // ===== The payment-section Status dropdown is the gate for recording money as RECEIVED =====
      // The page states the rule itself: "Enrolled – L1/L2 is set automatically when this method's
      // status is marked done (Full → Payment Done · Installment → 1st Paid · Advance → Fully Paid)".
      // This function used to IGNORE that: any amount sitting in a received box was written as a
      // PAID payment on save — even with Status = Pending — which then (correctly, given a paid row)
      // enrolled the lead. Third report of "Save health record enrolled the client": the coach types
      // the plan amounts, leaves Status Pending, saves. Amounts now persist as received only when the
      // status explicitly says that money was collected; otherwise the save touches no payment rows.
      const _stOf=(blk:string)=>((root.querySelector('#'+blk+' select[data-nocap]')as HTMLSelectElement|null)?.value)||"";
      if(pm==="i2"){
        const _stI2=_stOf("pb-i2");
        const _okP1=/1st|both/i.test(_stI2), _okP2=/2nd|both/i.test(_stI2);
        if(!_okP1&&!_okP2){
          if(_payNum("#i2Inst1Rcvd")||_payNum("#i2BalRcvd")) toast("Amounts saved with the plan only — set Status to “1st Paid” / “Both Paid” once the money is actually collected, or send a collection request to Reception.");
          return;
        }
        const p1=_okP1?_payNum("#i2Inst1Rcvd"):0, p2=_okP2?_payNum("#i2BalRcvd"):0;
        // EVERY * field of "Part 1 — Installment 1 (collected now)" is MANDATORY the moment the
        // Status says installment 1 is paid: amount, mode, date (drives the auto +30d balance-due
        // and the ledger), txn ref (the desk-receipt number for cash — "nothing is received until
        // proof + ref are attached") and the attached proof. Highlight every missing field at once
        // and name them, mirroring the Advisor form's required-field pattern.
        // Defense-in-depth behind _coachSaveRecord's PRE-SAVE block (which is what actually stops
        // the health record — this function runs after the profile write). Same rules: skipped only
        // when Reception already collected installment 1 (that row is preserved, the form isn't the
        // source), and the proof requirement is satisfied by the stored row's proof on re-saves.
        const _prevInst1Paid=(_coachPayRows||[]).some((r:any)=>_isDiaProgRow(r)&&r.payment_type==="installment"&&Number(r.installment_number)===1&&r.status==="paid"&&/reception|pos/i.test(String(r.collected_by||"")));
        if(_okP1&&!_prevInst1Paid){
          const _req:[string,string,()=>boolean][]=[
            ["#i2Inst1Rcvd","Inst-1 received (₹)",()=>!!_payNum("#i2Inst1Rcvd")],
            ["#i2Inst1Mode","Mode",()=>!!val("#i2Inst1Mode")],
            ["#i2Inst1Date","Inst-1 date",()=>!!val("#i2Inst1Date")],
            // Txn ref and Inst-1 proof were demoted to OPTIONAL on request (labels lost their *).
          ];
          const _missing:string[]=[]; let _first:HTMLElement|null=null;
          _req.forEach(([sel])=>{ const e2=root.querySelector(sel)as HTMLElement|null; if(e2) e2.classList.remove("err"); });
          for(const [sel,label,ok] of _req){
            if(ok()) continue;
            _missing.push(label);
            const e2=root.querySelector(sel)as HTMLElement|null;
            if(e2){ e2.classList.add("err"); if(!_first) _first=e2; }
          }
          if(_missing.length){
            toastErr("Installment 1: complete the required field"+(_missing.length>1?"s":"")+" — "+_missing.join(", "));
            try{ _first&&(_first as any).focus&&(_first as any).focus(); _first&&_first.scrollIntoView({behavior:"smooth",block:"center"}); }catch(_){}
            return;
          }
        }
        const totalI2=_payNum("#i2Total")||total;
        const balance=Math.max(0,totalI2-p1-p2);
        // Don't duplicate an installment Reception has ALREADY collected — the coach save must
        // reconcile, not re-insert (the delete below preserves Reception rows, so re-inserting a coach
        // copy of a Reception-paid installment is the root cause of the "two paid Inst-1" duplicate).
        // Check per-installment (1 AND 2), scoped to THIS program.
        // The /db gateway never throws (it resolves {error}), so a bare try/catch around this
        // lookup can't detect a failed check — a failed request silently reads as "nothing paid
        // yet" and re-inserts rows on top of Reception's, doubling every total. Check `.error`
        // explicitly and ABORT (like the delete-failure guards below) rather than guess.
        let recInst1Paid=false, recInst2Paid=false, recInst2Any=false, _inst1Outstanding=0;
        const _recCheck:any=await supabase.from("payments").select("status,collected_by,installment_number,program,amount").eq("lead_id",id).eq("payment_type","installment");
        if(_recCheck&&_recCheck.error){ toastErr("Payment check failed: "+(_recCheck.error.message||"database error")+" — save aborted to avoid duplicate rows"); return; }
        { const data=_recCheck?.data;
          const recRows=(n:number)=>(data||[]).filter((r:any)=>Number(r.installment_number)===n&&/reception|pos/i.test(String(r.collected_by||""))&&(String(r.program||"")===_prog||!r.program));
          recInst1Paid=recRows(1).some((r:any)=>r.status==="paid");
          const r2=recRows(2);
          recInst2Paid=r2.some((r:any)=>r.status==="paid");
          recInst2Any=r2.length>0;   // Reception already has a row (paid OR due) for inst-2 — don't add a second placeholder
          // An installment-1 request ALREADY SENT to Reception and not yet collected is money the
          // plan has committed but not received. `balance` below is total − received, so with
          // nothing received it equalled the WHOLE plan and was written as installment 2 — sitting
          // beside Reception's own inst-1 due row. A ₹30,000 L2 then read ₹15,000 + ₹30,000 =
          // ₹45,000 with ₹0 received (reported for yusuf). Subtract what inst-1 is already carrying.
          _inst1Outstanding=(data||[]).filter((r:any)=>Number(r.installment_number)===1&&r.status==="due"&&(String(r.program||"")===_prog||!r.program))
            .reduce((s:number,r:any)=>s+(Number(r.amount)||0),0);
        }
        if(!p1&&!p2&&balance<=0) return;
        const rows:any[]=[];
        if(p1&&!recInst1Paid) rows.push({lead_id:id,amount:p1,status:"paid",method:val("#i2Inst1Mode")||null,paid_at:iso(val("#i2Inst1Date")),payment_type:"installment",installment_number:1,total_installments:2,txn_ref:val("#i2Inst1Ref")||null,service:"Diabetes",program:_prog,collected_by:"Health Coach",...proof("i2Inst1Proof")});
        if(p2&&!recInst2Paid) rows.push({lead_id:id,amount:p2,status:"paid",method:val("#i2BalMode")||null,paid_at:iso(val("#i2BalDate")),payment_type:"installment",installment_number:2,total_installments:2,txn_ref:val("#i2BalRef")||null,service:"Diabetes",program:_prog,collected_by:"Health Coach",...proof("i2BalProof")});
        // Any remaining balance → a coach-side "due" row that keeps Total/Balance correct across a
        // reopen. Tagged "Health Coach", so it is NOT a Reception request and never surfaces in the
        // Collect queue (only an explicit "Send collection request" writes a Reception-visible row).
        // This must be a SEPARATE condition, not an `else` of the paid-row push above: `balance` is
        // ALREADY computed as totalI2-p1-p2 (i.e. it already accounts for a PARTIAL p2), so if the
        // client pays only part of installment 2, the shortfall still needs its own due row. Wiring
        // this as an `else` meant any partial payment on installment 2 silently wrote off the
        // remainder — the plan's own summary would then read "Fully Paid" on less than the total.
        // due_date is deliberately NOT written here: this row is created by the coach's SAVE, with no
        // "Send collection request" click, so persisting the auto +30d balance due date would be a
        // premature commitment (it also drives the Accounts reminders). The date is stamped only when
        // the request is actually sent — see sendToReception's companion row.
        const _balRow=Math.max(0,balance-_inst1Outstanding);   // don't re-book what inst-1 is already asking for
        if(_balRow>0&&!recInst2Paid&&!recInst2Any) rows.push({lead_id:id,amount:_balRow,status:"due",payment_type:"installment",installment_number:2,total_installments:2,service:"Diabetes",program:_prog,collected_by:"Health Coach"});
        // The coach can collect an installment Reception only STAGED as "due" (never actually
        // collected) — that's legitimate, but Reception's due placeholder for that installment
        // must then be cleared, or it lingers forever and the balance double-counts it (found
        // across several leads during the Barath investigation, 2026-07-24). Only clear a placeholder
        // for an installment number the coach is paying THIS save (p1/p2 truthy), not a blanket wipe.
        if(p1&&!recInst1Paid){ if(!(await _dbOk(supabase.from("payments").delete().eq("lead_id",id).eq("payment_type","installment").eq("program",_prog).eq("installment_number",1).eq("status","due"),"Clearing stale due placeholder"))) return; }
        if(p2&&!recInst2Paid){ if(!(await _dbOk(supabase.from("payments").delete().eq("lead_id",id).eq("payment_type","installment").eq("program",_prog).eq("installment_number",2).eq("status","due"),"Clearing stale due placeholder"))) return; }
        // Re-write only the coach-owned installment rows for THIS program (preserve Reception collections + the other program), then insert.
        // Abort the insert if the delete failed — otherwise the new rows pile on top of the old ones (duplicate installments).
        if(!(await _dbOk(supabase.from("payments").delete().eq("lead_id",id).eq("payment_type","installment").eq("program",_prog).neq("collected_by","Reception desk"),"Payment update"))) return;
        if(rows.length){ if(!(await _dbOk(supabase.from("payments").insert(rows),"Payment save"))) return; logActivity(id,[{action:"Payment",field:"Installment",new:"₹"+(p1+p2).toLocaleString("en-IN")+(totalI2?(" of ₹"+totalI2.toLocaleString("en-IN")+", balance ₹"+balance.toLocaleString("en-IN")):"")}]); if(String(_coachLeadId)===id) _renderCoachPayHistory(id); }
        if(p1||p2) await _ensureEnrolledFromPayment(id,_prog);   // installment-1 alone already enrolls
      } else if(pm==="full"){
        // Same Status gate: "Payment Done" is the declaration that the money was collected.
        if(!/done/i.test(_stOf("pb-full"))){
          if(_payNum("#payFullRcvd")) toast("Amount saved with the plan only — set Status to “Payment Done” once the money is actually collected, or send a collection request to Reception.");
          return;
        }
        const amt=_payNum("#payFullRcvd"); if(!amt) return;
        await commit("full",[{lead_id:id,amount:amt,status:"paid",method:val("#payFullMode")||null,paid_at:iso(val("#payFullDate")),payment_type:"full",txn_ref:val("#payFullRef")||null,service:"Diabetes",program:_prog,...proof("payFullProof")}],"Full payment",amt);
        await _ensureEnrolledFromPayment(id,_prog);
      } else if(pm==="adv"){
        // Status gate: "Advance Paid" records the advance; "Fully Paid" records both halves.
        const _stA=_stOf("pb-adv");
        const _okA1=/advance paid|fully/i.test(_stA), _okA2=/fully/i.test(_stA);
        if(!_okA1&&!_okA2){
          if(_payNum("#advAmt")||_payNum("#advBalRcvd")) toast("Amounts saved with the plan only — set Status to “Advance Paid” / “Fully Paid” once the money is actually collected, or send a collection request to Reception.");
          return;
        }
        const a1=_okA1?_payNum("#advAmt"):0, a2=_okA2?_payNum("#advBalRcvd"):0;
        if(!a1&&!a2) return;
        // Advance date is mandatory whenever the advance itself is being recorded — it anchors the
        // +30d balance due date and is the paid_at instant of the advance row.
        if(a1&&!val("#advDate")){
          const de=root.querySelector("#advDate")as HTMLInputElement|null;
          if(de){ de.classList.add("err"); de.focus(); }
          toastErr("Select the Advance date — required to record the advance"); return;
        }
        const rows:any[]=[];
        if(a1) rows.push({lead_id:id,amount:a1,status:"paid",method:val("#advMode")||null,paid_at:iso(val("#advDate")),payment_type:"advance",installment_number:1,total_installments:2,txn_ref:val("#advRef")||null,service:"Diabetes",program:_prog,...proof("advProof")});
        if(a2) rows.push({lead_id:id,amount:a2,status:"paid",method:val("#advBalMode")||null,paid_at:iso(val("#advBalDate")),payment_type:"advance",installment_number:2,total_installments:2,txn_ref:val("#advBalRef")||null,service:"Diabetes",program:_prog,...proof("advBalProof")});
        await commit("advance",rows,"Advance booking",a1+a2);
        // Advance booking enrolls only once FULLY paid (both halves) — matches the original
        // Status-dropdown trigger ("Fully Paid"), unlike installment which enrolls on the 1st payment.
        if(a1&&a2) await _ensureEnrolledFromPayment(id,_prog);
      }
    }
    // Lock a set of input fields (paid stages can't be edited/re-collected).
    function _lockFields(ids:string[],locked:boolean){ ids.forEach(s=>{ const el=root.querySelector(s)as HTMLInputElement|HTMLSelectElement|null; if(el){ el.disabled=locked; (el as HTMLElement).style.opacity=locked?"0.6":""; (el as HTMLElement).title=locked?"Paid — locked":""; } }); }
    // Set a payment-section Status dropdown (+ its hidden pill) without firing enrollment.
    function _setPayStatus(blkId:string,value:string){ const sel=root.querySelector('#'+blkId+' select[data-nocap]')as HTMLSelectElement|null; if(!sel)return; sel.value=value; const grp=sel.parentElement&&sel.parentElement.querySelector(".pills"); if(grp) grp.querySelectorAll(".pill").forEach((b:any)=>b.classList.toggle("on",(b.textContent||"").trim()===value)); }
    let _coachPayRows:any[]=[];
    // Apply payment locks from the lead's payment rows: mark paid stages Done, disable their inputs,
    // lock the fully-collected method, and block re-collection (prevents duplicate payment/enrollment).
    function _applyPaymentLocks(id:string,rows:any[]){
      if(String(_coachLeadId)!==String(id)) return;
      // Locks are PER PROGRAM (L1 / L2 / L1 + L2): only payments for the currently-selected program
      // count, so an L1-enrolled client can still collect for L2. Legacy rows (no program) = L1.
      const prog=_curProgram();
      const paid=(rows||[]).filter((r:any)=>_isDiaProgRow(r)&&r.status==="paid"&&(String(r.program||"L1")===prog));
      const fullPaid=paid.some((r:any)=>(r.payment_type||"full")==="full");
      const inst1Paid=paid.some((r:any)=>r.payment_type==="installment"&&Number(r.installment_number)===1);
      const inst2Paid=paid.some((r:any)=>r.payment_type==="installment"&&Number(r.installment_number)===2);
      const adv1Paid=paid.some((r:any)=>r.payment_type==="advance"&&Number(r.installment_number)===1);
      const adv2Paid=paid.some((r:any)=>r.payment_type==="advance"&&Number(r.installment_number)===2);
      // Lock the PAYMENT METHOD once any payment exists for this program — the method chosen for the
      // first payment (e.g. Installment 2×) must stay fixed for the 2nd collection; only the balance
      // is then entered. No payment yet → method stays freely selectable.
      const _mFor=(t:string)=>t==="installment"?"i2":t==="advance"?"adv":t==="emi"?"emi":"full";
      // Method lock is PER PROGRAM: L2 is handled independently of L1. Only lock the method once a
      // payment exists FOR THE CURRENTLY-SELECTED program (`paid` is already program-scoped). So an
      // L1-paid client selecting a fresh L2 can still choose Full / Installment; once L2's
      // installment 1 is paid, L2's method locks and only the balance is collected.
      const _lockedMethod=paid.length?_mFor(String(paid[0].payment_type||"full")):"";
      const _pmSel=root.querySelector("#payMethod")as HTMLSelectElement|null;
      if(_pmSel){
        if(_lockedMethod){ const _mName:any={i2:"Installment (2×)",full:"Full Payment",adv:"Advance Booking",emi:"EMI"}; if(_pmSel.value!==_lockedMethod){ _pmSel.value=_lockedMethod; try{ if(w.payBlk) w.payBlk(_lockedMethod); }catch(_){} } _pmSel.disabled=true; (_pmSel as HTMLElement).style.opacity="0.75"; _pmSel.title="Method locked — "+(_mName[_lockedMethod]||_lockedMethod)+" already in progress"; }
        else { _pmSel.disabled=false; (_pmSel as HTMLElement).style.opacity=""; _pmSel.title=""; }
      }
      // FULL — one shot: lock the whole section once paid.
      _lockFields(["#payFullRcvd","#payFullMode","#payFullRef","#payFullDate"],fullPaid);
      const fsel=root.querySelector('#pb-full select[data-nocap]')as HTMLSelectElement|null; if(fsel) fsel.disabled=fullPaid;
      // Reflect the CURRENT program's state (reset a stale "done" carried from the other program).
      if(fullPaid) _setPayStatus("pb-full","Payment Done"); else if(fsel&&fsel.value==="Payment Done") _setPayStatus("pb-full","In Process");
      // INSTALLMENT — lock inst-1 once paid (inst-2 stays open); lock inst-2 once paid.
      _lockFields(["#i2Inst1Rcvd","#i2Inst1Mode","#i2Inst1Ref","#i2Inst1Date"],inst1Paid);
      _lockFields(["#i2BalRcvd","#i2BalMode","#i2BalRef","#i2BalDate"],inst2Paid);
      // Reconstruct the installment form from stored rows so a reopened client shows Total, the paid
      // Installment 1, the auto Balance Due, and the pending Balance-Received default (none of which
      // are persisted on the form itself).
      { const i2r=(rows||[]).filter((r:any)=>String(r.program||"L1")===prog&&r.payment_type==="installment");
        if(i2r.length){
          // Identify installments by their NUMBER, not row order — rows arrive newest-first, so
          // find(paid) could pick installment 2 and mislabel it as installment 1. Total is the SUM of
          // both installments (each counted once) so a FULLY-paid plan shows the full amount, not one.
          const byNum=(n:number)=>i2r.find((r:any)=>Number(r.installment_number)===n);
          const r1=byNum(1)||i2r.find((r:any)=>r.status==="paid");   // legacy rows w/o a number → any paid
          const r2=byNum(2)||i2r.find((r:any)=>r.status==="due");    // legacy → the outstanding due
          const p1amt=r1?Number(r1.amount)||0:0;
          const p2amt=r2?Number(r2.amount)||0:0;
          const bal=(r2&&r2.status!=="paid")?p2amt:0;                 // balance = the unpaid installment 2
          const tot=p1amt+p2amt;
          // "Inst-1 received" may ONLY be pre-filled from an installment-1 row that is actually PAID.
          // byNum(1) also matches the `due` row that "Send collection request to Reception" creates,
          // so a merely REQUESTED amount was being written into a *received* field. _persistInstallments
          // then read it back on the next save, wrote a paid row for money Reception had not collected,
          // and called _ensureEnrolledFromPayment — which is why clicking "Save health record" silently
          // flipped the Enrolled status (reported for Sampath Kumar). Same rule the Txn Ref below uses.
          // DETERMINISTIC: the field shows the paid amount, or nothing. The earlier version only
          // cleared when a non-paid row existed, which left the no-row case untouched — so the value
          // from the PREVIOUSLY OPEN lead stayed in the box, and saving wrote it against the new
          // client. That is how a paid installment appeared for a lead who had only ever had a
          // collection request sent (krishnan c, row #331 — created after the first fix).
          const i1e=root.querySelector("#i2Inst1Rcvd")as HTMLInputElement|null;
          if(i1e) i1e.value=(r1&&r1.status==="paid"&&p1amt)?String(p1amt):"";
          // The plan's Total is the CONFIGURED programme price. The installment rows describe how that
          // price is SPLIT — they don't define what the plan is worth. Reconstructing Total as
          // paid + due re-inflated the plan whenever the installment-2 placeholder was wrong: a
          // ₹15,000 paid installment beside a stale ₹30,000 placeholder read as a ₹45,000 Total on a
          // ₹30,000 L2 (reported for yusuf, then again for Soosai Viagappa Sahayaraj). Gating that on
          // "nothing paid yet" was not enough — the moment installment 1 is collected the sum takes
          // over again. Fall back to the row sum ONLY when no programme price is configured at all.
          const _cfgPrice=_payNetPrice();
          const _anyInstPaid=r1?.status==="paid"||r2?.status==="paid";
          const te=root.querySelector("#i2Total")as HTMLInputElement|null;
          if(te){ if(_cfgPrice>0) te.value=String(_cfgPrice); else if(tot&&_anyInstPaid) te.value=String(tot); }
          const bde=root.querySelector("#i2BalDue")as HTMLInputElement|null; if(bde) bde.value=bal>0?("₹"+bal.toLocaleString("en-IN")):(bde.value||"");   // #i2BalDue is otherwise the live-computed Total−Inst1 (installment-2 amount); don't clobber it
          // Never default "Balance received" to the OUTSTANDING balance — same hazard as inst-1 above:
          // _persistInstallments reads this field as money collected, so pre-filling it meant the next
          // save recorded installment 2 as paid. An amount only appears here once it is actually paid.
          const bre=root.querySelector("#i2BalRcvd")as HTMLInputElement|null;
          if(bre) bre.value=(r2&&r2.status==="paid"&&p2amt)?String(p2amt):"";
          // Each installment's Txn Ref / UTR comes from ITS OWN payment row — never copy installment-1's
          // ref into installment-2. Runs AFTER the profile restore, so it overrides the positional copy:
          // inst-1 field = inst-1's paid ref; inst-2 field = inst-2's paid ref, or CLEARED while pending
          // (so a stale/copied inst-1 ref never lingers in the balance section).
          const i1ref=root.querySelector("#i2Inst1Ref")as HTMLInputElement|null; if(i1ref&&r1&&r1.status==="paid") i1ref.value=String(r1.txn_ref||"");
          const i2ref=root.querySelector("#i2BalRef")as HTMLInputElement|null; if(i2ref) i2ref.value=(r2&&r2.status==="paid")?String(r2.txn_ref||""):"";
        } else {
          // NO installment rows for this program → nothing has been received, so the amount boxes must
          // be empty. Without this the whole restore was skipped and the values from the PREVIOUSLY
          // OPEN client stayed in the form; the next "Save health record" then wrote them as a paid
          // installment against THIS lead and enrolled them. Clearing the refs too, for the same reason.
          ["#i2Inst1Rcvd","#i2BalRcvd","#i2Inst1Ref","#i2BalRef"].forEach((sel)=>{ const el=root.querySelector(sel)as HTMLInputElement|null; if(el) el.value=""; });
        }
      }
      if(inst1Paid&&inst2Paid) _setPayStatus("pb-i2","Both Paid"); else if(inst1Paid) _setPayStatus("pb-i2","1st Paid"); else { const s=root.querySelector('#pb-i2 select[data-nocap]')as HTMLSelectElement|null; if(s&&/Paid/.test(s.value)) _setPayStatus("pb-i2","Pending"); }
      const isel=root.querySelector('#pb-i2 select[data-nocap]')as HTMLSelectElement|null; if(isel) isel.disabled=(inst1Paid&&inst2Paid);
      // ADVANCE
      _lockFields(["#advAmt","#advMode","#advRef","#advDate"],adv1Paid);
      _lockFields(["#advBalRcvd","#advBalMode","#advBalRef","#advBalDate"],adv2Paid);
      // Status follows the money automatically, same as the installment block above: once Reception
      // records the advance, the coach's Status reads "Advance Paid" without anyone touching it.
      if(adv1Paid&&adv2Paid) _setPayStatus("pb-adv","Fully Paid");
      else if(adv1Paid) _setPayStatus("pb-adv","Advance Paid");
      else { const s=root.querySelector('#pb-adv select[data-nocap]')as HTMLSelectElement|null; if(s&&/Paid/.test(s.value)) _setPayStatus("pb-adv","Balance Pending"); }
      const asel=root.querySelector('#pb-adv select[data-nocap]')as HTMLSelectElement|null; if(asel) asel.disabled=(adv1Paid&&adv2Paid);
      // Block re-collection: disable "Send collection request to Reception" when the ACTIVE method is fully collected.
      const method=(root.querySelector("#payMethod")as HTMLSelectElement|null)?.value||"";
      const done=(method==="full"&&fullPaid)||(method==="i2"&&inst1Paid&&inst2Paid)||(method==="adv"&&adv1Paid&&adv2Paid);
      const sb=root.querySelector("#sendCollectBtn")as HTMLButtonElement|null;
      if(sb){ sb.disabled=done; sb.style.opacity=done?"0.55":""; sb.style.pointerEvents=done?"none":""; sb.title=done?"Payment already collected for this method":""; }
      // A small "collected" note next to the button.
      let note=root.querySelector("#payCollectedNote")as HTMLElement|null;
      if(done&&sb){ if(!note){ note=document.createElement("span"); note.id="payCollectedNote"; note.style.cssText="margin-left:8px;font-size:11.5px;font-weight:600;color:var(--ok-ink)"; sb.parentElement?.insertBefore(note,sb.nextSibling); } note.textContent="✓ Payment collected — locked"; }
      else if(note){ note.remove(); }
    }
    // Consolidated Payment Summary card (near the Payment collection flow): program, method,
    // total / received / balance, installment statuses, next due, % complete + a pending banner.
    function _renderPaymentSummary(id:string,rows:any[]){
      const el=root.querySelector("#coachPaySummary"); if(!el) return;
      if(String(_coachLeadId)!==String(id)){ el.innerHTML=""; return; }
      const e=(s:any)=>(s==null?"":String(s)).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
      const prog=_curProgram();
      const mine=(rows||[]).filter((r:any)=>_isDiaProgRow(r)&&String(r.program||"L1")===prog);
      const paid=mine.filter((r:any)=>r.status==="paid"); const due=mine.filter((r:any)=>r.status==="due");
      if(!paid.length&&!due.length){ el.innerHTML=""; return; }   // nothing collected for this program yet
      const money=(n:any)=>"₹"+(Number(n)||0).toLocaleString("en-IN");
      const received=paid.reduce((s:number,r:any)=>s+(Number(r.amount)||0),0);
      const rowBalance=due.reduce((s:number,r:any)=>s+(Number(r.amount)||0),0);
      const type=(mine[0]&&mine[0].payment_type)||"full";
      const methodLbl=({full:"Full Payment",installment:"Installment (2×)",advance:"Advance Booking",emi:"EMI"}as any)[type]||type;
      const isInst=type==="installment"||type==="advance";
      // A part-payment plan is worth its CONFIGURED programme price (or the coach's manual Total) —
      // not "received + whatever due rows exist". Summing the placeholder rows meant one oversized
      // installment-2 row was added straight onto what had been received, showing ₹45,000 on a
      // ₹30,000 L2 after a ₹15,000 collection (reported for yusuf). Deriving the balance from the
      // plan value also makes the card self-correct against a stale placeholder.
      // Non-installment methods keep the row-derived figures untouched.
      let total=received+rowBalance, balance=rowBalance;
      if(isInst){
        // CONFIGURED price first. Reading #i2Total first was the hole in the previous fix: that field
        // is itself rebuilt from the rows, so once installment 1 was paid it carried the inflated
        // paid+due figure straight back into the card.
        const planTotal=_payNetPrice()||_payNum("#i2Total")||0;
        if(planTotal>0){ total=Math.max(planTotal,received); balance=Math.max(0,total-received); }
      }
      const pct=total>0?Math.round(100*received/total):(received>0?100:0);
      const inst1=mine.find((r:any)=>Number(r.installment_number)===1); const inst2=mine.find((r:any)=>Number(r.installment_number)===2);
      const st=(x:any)=>x?(x.status==="paid"?'<span class="chipb ok">✅ Paid</span>':'<span class="chipb warn">⏳ Pending</span>'):'<span class="chipb neu">—</span>';
      const nextDue=(due[0]||{}).due_date||""; const fullyPaid=balance<=0&&received>0;
      const banner=(isInst&&balance>0)
        ? '<div class="banner plan" style="margin:0 0 10px"><svg class="icon" style="width:15px;height:15px"><use href="#i-coin"/></svg> <span><b>Installment 2 pending</b> — Received '+money(received)+' · Balance '+money(balance)+(nextDue?(' · Next installment due '+fmtISTDate(nextDue)):'')+'</span></div>'
        : '';
      const cell=(l:string,v:string)=>'<div><div style="font-size:10px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.03em">'+l+'</div><div style="font-weight:700;font-size:13px;margin-top:2px">'+v+'</div></div>';
      el.innerHTML=banner
        +'<div class="sec" style="margin:0 0 12px;border:1px solid var(--brand-line);background:linear-gradient(180deg,#F7FCFA,#fff)"><div class="sec-bd" style="padding:12px 14px">'
        +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap"><b style="font-size:13px">Payment summary</b>'+(fullyPaid?'<span class="chipb ok">Fully Paid</span>':'<span class="chipb warn">'+pct+'% paid</span>')+'<span class="chipb neu" style="margin-left:auto">'+e(prog)+'</span></div>'
        +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:12px 16px">'
        +cell("Method",e(methodLbl))+cell("Total",money(total))
        +cell("Received",'<span style="color:var(--ok-ink)">'+money(received)+'</span>')
        +cell("Balance",'<span style="color:'+(balance>0?"var(--warn-ink)":"var(--ok-ink)")+'">'+money(balance)+'</span>')
        +(isInst?cell("Installment 1",st(inst1)):"")
        +(isInst?cell("Installment 2",st(inst2)):"")
        +(isInst&&nextDue&&balance>0?cell("Next due",fmtISTDate(nextDue)):"")
        +'</div>'
        +'<div style="margin-top:12px"><div style="height:8px;border-radius:6px;background:var(--surface-2);overflow:hidden"><div style="height:100%;width:'+pct+'%;background:linear-gradient(90deg,#17A87B,#0EA5A0);border-radius:6px;transition:width .3s"></div></div><div style="font-size:11px;color:var(--muted);margin-top:4px">'+pct+'% complete · '+money(received)+' of '+money(total)+'</div></div>'
        +'</div></div>';
    }
    w._coachApplyPayLocks=()=>{ _applyPaymentLocks(String(_coachLeadId),_coachPayRows); try{ _renderPaymentSummary(String(_coachLeadId),_coachPayRows); }catch(_){} };   // re-apply on method/program change
    async function _renderCoachPayHistory(id:string){
      const el=root.querySelector("#coachPayHist"); if(!el) return;
      let rows:any[]=[];
      try{ const {data}=await supabase.from("payments").select("*").eq("lead_id",id).order("created_at",{ascending:false}).limit(100); rows=data||[]; }catch(_){ rows=[]; }
      if(String(_coachLeadId)!==String(id)) return;
      _coachPayRows=rows;   // set BEFORE the auto-select so _refreshPayEnrollChip's detailed label sees fresh rows
      // Auto-select the program the coach should collect for, from the client's payment records, so
      // the pay-locks, method-lock and pricing reflect it (the dropdown otherwise defaults to L1).
      // Priority: a program still needing collection (an outstanding due, or installment 1 paid but
      // not installment 2) — that's the ACTIVE one — then a single paid program, then the combined
      // view. This lands the coach on e.g. L2 (inst-1 paid) so its method locks and only the balance
      // is collectable, instead of a combined "L1 + L2" view where the L2 payment wouldn't match.
      try{
        const norm=(v:any)=>{ const s=String(v||"L1"); if(/l1\s*\+\s*l2/i.test(s))return "L1 + L2"; const l1=/l1/i.test(s),l2=/l2/i.test(s); return (l1&&l2)?"L1 + L2":l2?"L2":"L1"; };
        const stat:Record<string,{paid:number;due:number;i1:boolean;i2:boolean}>={};
        (rows||[]).filter(_isDiaProgRow).forEach((r:any)=>{ const p=norm(r.program); const o=(stat[p]=stat[p]||{paid:0,due:0,i1:false,i2:false}); if(r.status==="paid"){o.paid++; if(r.payment_type==="installment"){ if(Number(r.installment_number)===1)o.i1=true; if(Number(r.installment_number)===2)o.i2=true; }} else if(r.status==="due")o.due++; });
        const progs=Object.keys(stat);
        let cliProg=progs.find(p=>stat[p].due>0||(stat[p].i1&&!stat[p].i2))||"";   // 1) still needs collection
        if(!cliProg){ const hasL1=progs.some(p=>/L1/.test(p)), hasL2=progs.some(p=>/L2/.test(p)); cliProg=(hasL1&&hasL2)?"L1 + L2":hasL2?"L2":hasL1?"L1":""; }
        if(cliProg){ const ps=root.querySelector("#haProgram")as HTMLSelectElement|null; if(ps&&ps.value!==cliProg){ ps.value=cliProg; try{ if(w._syncProgramPricing) w._syncProgramPricing(); }catch(_){} } }
      }catch(_){}
      _coachPayRows=rows; try{ _applyPaymentLocks(id,rows); }catch(_){} try{ _renderPaymentSummary(id,rows); }catch(_){}
      // Now that the REAL payment rows are loaded, recompute the enrolled-status chip so it shows the
      // detailed stage ("L2 – Installment 1 Completed"). The earlier _refreshPayEnrollChip() in
      // _coachOpen ran before this async load resolved, so with no rows it fell back to the generic
      // consStatus label ("Enrolled – L2"). This unconditional refresh fixes that regardless of whether
      // the program dropdown changed (the sync-on-program-change refresh only fires when it does).
      try{ _refreshPayEnrollChip(); }catch(_){}
      const e=(s:any)=>(s==null?"":String(s)).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
      const money=(n:any)=>"₹"+(parseInt(n)||0).toLocaleString("en-IN");
      if(!rows.length){ el.innerHTML='<div class="stub">No payment records for this client yet.</div>'; return; }
      const paid=rows.reduce((s:number,r:any)=>s+(parseInt(r.amount)||0),0);
      el.innerHTML='<div style="margin-bottom:8px;font-size:12px;color:var(--muted)">Total collected: <b style="color:var(--ink)">'+money(paid)+'</b> · '+rows.length+' payment'+(rows.length===1?"":"s")+'</div>'
        +'<div class="tscroll"><table class="tbl" style="min-width:560px"><thead><tr><th>Date</th><th>Type</th><th>Amount</th><th>Mode</th><th>Ref</th><th>Status</th></tr></thead><tbody>'
        +rows.map((r:any)=>{ const typ=r.payment_type==="installment"?("Installment "+(r.installment_number||"")+"/"+(r.total_installments||2)):(r.payment_type||"full"); return '<tr>'
          +'<td class="mono" style="font-size:11px">'+e(fmtIST(r.paid_at||r.created_at))+'</td>'
          +'<td>'+e(typ)+'</td>'
          +'<td class="mono" style="font-weight:700">'+money(r.amount)+'</td>'
          +'<td>'+e(r.method||"—")+'</td>'
          +'<td class="mono" style="font-size:11px">'+e(r.txn_ref||"—")+'</td>'
          +'<td><span class="chipb '+(r.status==="paid"?"ok":"neu")+'">'+e(r.status||"—")+'</span></td></tr>'; }).join("")
        +'</tbody></table></div>';
    }
    // Persist the coach's Zoom/online recording link into zoom_recordings so it shows
    // in the Recordings screen's Zoom table. Idempotent: skips a link already stored.
    async function _persistZoomRecording(id:string){
      const url=((root.querySelector("#coachRecUrl")as HTMLInputElement)?.value||"").trim();
      if(!url) return;
      try{
        const {data}=await supabase.from("zoom_recordings").select("id,meeting_url").eq("lead_id",id).limit(200);
        if((data||[]).some((r:any)=>String(r.meeting_url||"")===url)) return;   // already stored
        const name=((root.querySelector("#coachName")?.textContent)||"").trim();
        const cd=((root.querySelector("#haConsultDate")as HTMLInputElement)?.value||"");
        await supabase.from("zoom_recordings").insert({lead_id:id,customer_name:name,meeting_url:url,status:"Ready",recorded_by:_recBy(),meeting_at:cd?new Date(cd).toISOString():new Date().toISOString(),created_at:new Date().toISOString()});
      }catch(_){}
    }
    // Dedicated "Save Link" action next to the recording-URL field: validate, store in
    // zoom_recordings against this customer, confirm, and refresh the Zoom Recordings table.
    w._coachSaveZoomLink=async()=>{
      if(!_coachLeadId){ toast("Open a visited client first"); return; }
      const fld=root.querySelector("#coachRecUrl")as HTMLInputElement|null;
      const url=(fld?.value||"").trim();
      if(!url){ toastErr("Paste a Zoom meeting link first"); return; }
      if(!/^https?:\/\/\S+$/i.test(url)){ toastErr("Enter a valid link — it must start with http:// or https://"); return; }
      const id=String(_coachLeadId);
      try{
        const {data}=await supabase.from("zoom_recordings").select("id,meeting_url").eq("lead_id",id).limit(200);
        if((data||[]).some((r:any)=>String(r.meeting_url||"")===url)){ toast("This link is already saved for this client"); return; }
        const name=((root.querySelector("#coachName")?.textContent)||"").trim();
        const cd=((root.querySelector("#haConsultDate")as HTMLInputElement)?.value||"");
        const {error}=await supabase.from("zoom_recordings").insert({lead_id:id,customer_name:name,meeting_url:url,status:"Ready",recorded_by:_asnActor(),meeting_at:cd?new Date(cd).toISOString():new Date().toISOString(),created_at:new Date().toISOString()});
        if(error){ toastErr("Save failed: "+(error.message||"db error")); return; }
        toast("✓ Zoom link saved to "+(name||"customer profile"));
        logActivity(id,[{action:"Zoom Recording",field:"Link saved",new:url}]);
        try{ await loadRecordings(); }catch(_){}   // reflect in the Zoom Recordings table
      }catch(e:any){ toastErr("Save failed: "+(e.message||"network error")); }
    };
    let _coachSaveBusy=false;   // guards against a double-click duplicating payments via _persistInstallments
    w._coachSaveRecord=async()=>{
      if(_coachSaveBusy) return;
      if(!_coachLeadId){ toast("Open a visited client first"); return; }
      const id=String(_coachLeadId);
      const obj=collectCoachProfile();
      // Review Date must be today-or-future for the join / this-week / month plans. Only these
      // four consultation statuses are validated; every other status is left untouched. An empty
      // review date is still allowed (unchanged) — we only block a PAST date being saved.
      const _revStatuses=["Will Join Immediately","This Week","End of Month","Next Month"];
      if(_revStatuses.indexOf((obj&&obj.consStatus)||"")>=0){
        const rd=root.querySelector("#haReviewDate")as HTMLInputElement|null;
        if(rd) rd.classList.remove("err");
        // MANDATORY: "Will Join Immediately" cannot proceed without a review date (spec).
        if(((obj&&obj.consStatus)||"")==="Will Join Immediately" && !((rd&&rd.value)||"").trim()){
          if(rd) rd.classList.add("err");
          toastErr('Review date is required when "Will Join Immediately" is selected');
          try{ if(rd){ _setFutureMin(rd); rd.focus(); } }catch(_){}
          return;
        }
        if(rd && rd.value && rd.value<_todayLocal()){ toastErr("Review date can't be in the past — choose today or a future date"); try{_setFutureMin(rd);rd.focus();}catch(_){} return; }
      }
      // Highlight-clearing helper for the coach form (mirrors the missing-field style used elsewhere).
      const _clr=(sel:string)=>{ const e=root.querySelector(sel)as HTMLElement|null; if(e) e.classList.remove("err"); };
      // Mandatory: Duration of diabetes (Health Assessment · Basic health info).
      { const durEl=root.querySelector("#haDuration")as HTMLSelectElement|null; _clr("#haDuration");
        if(!((durEl&&durEl.value)||"").trim()){ durEl&&durEl.classList.add("err"); toastErr("Please complete the required field: Duration of diabetes"); try{durEl&&durEl.focus();}catch(_){} return; } }
      // Payment section: mandatory Amount received + Mode + Status BEFORE a payment can be submitted.
      // A payment is considered "being submitted" when the coach has entered an amount for the active
      // method OR marked its status as collected/paid. Assessment-only saves (no amount, default status)
      // stay allowed, so existing functionality is unaffected.
      { const pm=(root.querySelector("#payMethod")as HTMLSelectElement)?.value||"";
        const pmap:Record<string,{blk:string;amt:string;mode:string}>={full:{blk:"pb-full",amt:"#payFullRcvd",mode:"#payFullMode"},i2:{blk:"pb-i2",amt:"#i2Inst1Rcvd",mode:"#i2Inst1Mode"},adv:{blk:"pb-adv",amt:"#advAmt",mode:"#advMode"},emi:{blk:"pb-emi",amt:"#emiDown",mode:""}};
        const pcfg=pmap[pm];
        if(pcfg){
          const stEl=root.querySelector("#"+pcfg.blk+" select[data-nocap]")as HTMLSelectElement|null;
          const status=((stEl&&stEl.value)||"").trim();
          const collected=/done|paid|received|fully/i.test(status)&&!/pending|in\s*process|open/i.test(status);
          const amtEl=root.querySelector(pcfg.amt)as HTMLInputElement|null;
          const amt=parseInt((((amtEl&&amtEl.value)||"")).replace(/[^\d]/g,""))||0;
          _clr(pcfg.amt); if(pcfg.mode)_clr(pcfg.mode);
          // Submitting a payment = an amount was entered, or the status says money was collected.
          if(amt>0||collected){
            const _missP:string[]=[]; let _firstP:HTMLElement|null=null;
            if(amt<=0){ _missP.push("Amount received"); if(amtEl){ amtEl.classList.add("err"); _firstP=_firstP||amtEl; } }
            if(pcfg.mode){ const modeEl=root.querySelector(pcfg.mode)as HTMLSelectElement|null;
              if(!((modeEl&&modeEl.value)||"").trim()){ _missP.push("Mode"); if(modeEl){ modeEl.classList.add("err"); _firstP=_firstP||modeEl; } } }
            if(!status){ _missP.push("Status"); if(stEl){ stEl.classList.add("err"); _firstP=_firstP||stEl; } }
            // Installment (2×) Part 1: the * fields (received / mode / date) are mandatory BEFORE
            // the health record may save (this block runs pre-save, so a failure blocks the whole
            // record — the deeper check inside _persistInstallments runs after the profile write and
            // can't). Date drives the auto +30d balance-due + ledger paid_at. Txn ref and proof were
            // demoted to OPTIONAL on request. Skipped when Reception already collected installment 1
            // — that row is preserved as-is and these form fields aren't what gets written.
            if(pm==="i2"){
              const _recInst1=(_coachPayRows||[]).some((r:any)=>_isDiaProgRow(r)&&r.payment_type==="installment"&&Number(r.installment_number)===1&&r.status==="paid"&&/reception|pos/i.test(String(r.collected_by||"")));
              if(!_recInst1){
                _clr("#i2Inst1Date"); const _dEl=root.querySelector("#i2Inst1Date")as HTMLInputElement|null;
                if(!((_dEl&&_dEl.value)||"").trim()){ _missP.push("Inst-1 date"); if(_dEl){ _dEl.classList.add("err"); _firstP=_firstP||_dEl; } }
              }
            }
            if(_missP.length){ toastErr("Payment — please complete: "+_missP.join(", ")); try{_firstP&&(_firstP as any).focus&&(_firstP as any).focus(); _firstP&&_firstP.scrollIntoView({behavior:"smooth",block:"center"}); }catch(_){} return; }
          }
        }
      }
      saveCoachLocal(id,obj);
      const c=_coachClients.find((x:any)=>String(x.id)===id); if(c)c.coachProfile=obj;
      _coachSaveBusy=true;
      try{
        const {error}=await supabase.from("leads").update({coach_profile:obj}).eq("meta_lead_id",id);
        if(error){
          if(/coach_profile|column|schema|exist/i.test(error.message||"")) toast("Saved locally — run supabase-migration-coach-screening.sql for DB sync");
          else toastErr("Save failed: "+(error.message||"DB error"));
          return;
        }
        await _persistInstallments(id);   // store installment payments (if the 2× method is active)
        try{ loadReceptionData(); }catch(_){}   // reflect the coach's payment (amount + revenue + queue) on Reception
        await _persistZoomRecording(id);  // store the Zoom/online recording link (if entered)
        // Propagate an ENROLLED consultation status to the lead's call_status so the
        // Advisor dashboard "Enrolled" card + Enrolled-clients table stay in sync and it
        // survives a refresh (persisted in the DB, read back via leads.call_status).
        if(/enrol/i.test((obj&&obj.consStatus)||"")){
          // Enrolled date/time is STABLE — read the DB's current enrolled_at (source of truth) and
          // preserve it if already set; only stamp 'now' the first time. Prevents re-stamping on
          // re-save and keeps Coach + Advisor identical regardless of in-memory state.
          // The gateway resolves {error} rather than throwing, so a bare try/catch can't tell "this
          // lead has never been enrolled" apart from "the read failed" — treating a failed read as
          // the former re-stamps enrolled_at to right now, permanently overwriting the client's real
          // (possibly weeks-old) enrollment date. Skip the re-stamp entirely on a failed check
          // instead of guessing; the rest of the save still proceeds normally.
          const _enrRes:any=await supabase.from("leads").select("enrolled_at").eq("meta_lead_id",id).limit(1);
          if(_enrRes&&_enrRes.error){ toastErr("Could not verify existing enrollment date — enrollment timestamp left unchanged this save"); }
          else{
          const existingEnr:string|null=(_enrRes?.data&&_enrRes.data[0]&&_enrRes.data[0].enrolled_at)||null;
          const already=!!existingEnr;
          const enrIso=existingEnr||new Date().toISOString();
          try{ await supabase.from("leads").update({call_status:"Enrolled",enrolled_at:enrIso}).eq("meta_lead_id",id); }catch(_){}
          // Coach → Reception sync: stamp this lead's appointment(s) as enrolled so Reception
          // reflects it in the same DB record, then refresh Reception live (no manual reload).
          try{ await supabase.from("appointments").update({stage:"enrolled"}).eq("lead_id",id).neq("status","cancelled"); }catch(_){}
          const setEnrolled=(arr:any[])=>arr.forEach((l:any)=>{ if(String(l.id)===id){ l.callStatus="Enrolled"; l.enrolledAt=enrIso; } });
          setEnrolled(_metaLeads); setEnrolled(_assignedExtras);
          if(!already){ logActivity(id,[{action:"Enrolled",field:"Enrolled at",new:fmtIST(enrIso)}]); }
          try{ renderHealthDashboard(); renderAssignedLeads(); renderAsnHist(); }catch(_){}
          try{ await loadReceptionData(); }catch(_){}   // Reception's Enrolled card/table update immediately
          try{ if(String(_advLeadId)===id) _advApplyEnrolled("Enrolled",enrIso,(obj&&obj.consStatus)||""); }catch(_){}
          _broadcastLeadSync({leadId:id,callStatus:"Enrolled",enrolledAt:enrIso,consStatus:(obj&&obj.consStatus)||"Enrolled"});   // push to other open tabs
          }
        }
        try{ renderCoachOpenList(); }catch(_){}   // reflect new consultation status in dashboard/table
        toast("Health record saved");
        logActivity(id,[{action:"Updated",field:"Health Coach record",new:"saved"}]);
      }catch(e:any){ toastErr("Save failed: "+(e.message||"network error")); }
      finally{ _coachSaveBusy=false; }
    };
    w._coachPrint=()=>{
      if(!_coachLeadId){ toast("Open a visited client first"); return; }
      const p=_coachPanelEl(); if(!p) return;
      const name=(root.querySelector("#coachName")?.textContent)||"Client";
      const rows:string[]=[];
      p.querySelectorAll(".fld").forEach((fld:any)=>{
        const lab=fld.querySelector(".lbl"); const ctrl=fld.querySelector("input,select,textarea");
        if(!lab||!ctrl) return; const v=(ctrl as any).value; if(!v) return;
        rows.push('<tr><td style="color:#666;padding:4px 14px 4px 0;vertical-align:top">'+(lab.textContent||"").replace(/\s+/g," ").trim()+'</td><td style="font-weight:600;padding:4px 0">'+String(v).replace(/</g,"&lt;")+'</td></tr>');
      });
      const win=window.open("","_blank","width=760,height=1000"); if(!win){ toast("Allow pop-ups to print the prescription"); return; }
      win.document.write('<html><head><title>Consultation — '+name+'</title></head><body style="font-family:system-ui,Arial,sans-serif;padding:28px;color:#111"><h2 style="margin:0">WellnessOS — Consultation Record</h2><div style="color:#666;margin:2px 0 18px">'+name+' &middot; Lead #'+_coachLeadId+' &middot; '+new Date().toLocaleString("en-IN")+'</div><table style="border-collapse:collapse;font-size:13px">'+(rows.join("")||'<tr><td>No details entered yet.</td></tr>')+'</table></body></html>');
      win.document.close(); win.focus(); setTimeout(()=>{ try{ win.print(); }catch(_){} },300);
    };
    // Coach Call button — same Call/End toggle + timer as the Advisor page.
    const _ccb=root.querySelector("#coachCallBtn")as HTMLElement|null;
    let _cOnCall=0,_cCt=0,_cCti:ReturnType<typeof setInterval>|null=null;
    if(_ccb) _ccb.onclick=async()=>{
      const sp=_ccb.querySelector("span");
      if(!_cOnCall){
        if(!_coachLeadId){ toast("Open a visited client first"); return; }
        const id=String(_coachLeadId); const nm=(root.querySelector("#coachName")?.textContent)||"client";
        _cOnCall=1; _ccb.style.background="linear-gradient(135deg,#E2553B,#A8351F)"; if(sp)sp.textContent="Calling…";
        const r=await _callInitiate(id,"coach");
        if(!r||!r.ok){ _cOnCall=0; _ccb.style.background=""; if(sp)sp.textContent="Call"; toastErr((r&&r.error)||"Call could not be placed"); return; }
        toast("📞 Calling "+nm+" — your phone rings first, then the customer");
        logActivity(id,[{action:"Status Changed",field:"Call",new:"Outbound call initiated"}]);
        _cCt=0; if(_cCti)clearInterval(_cCti); _cCti=setInterval(()=>{_cCt++;const s2=_ccb.querySelector("span");if(s2)s2.textContent="End · "+(_cCt/60|0)+":"+String(_cCt%60).padStart(2,"0");},1000);
        _pollRecordings(id,"coach"); setTimeout(()=>_coachRenderRecordings(id),50000);
      } else {
        _cOnCall=0; if(_cCti)clearInterval(_cCti); _ccb.style.background=""; if(sp)sp.textContent="Call";
        const id=String(_coachLeadId);
        if(id) logActivity(id,[{action:"Updated",field:"Call ended",new:(_cCt/60|0)+":"+String(_cCt%60).padStart(2,"0")}]);
        toast("Call ended");
        // Pull final status + recording from the CDR and refresh the Call History tab.
        const c=_coachClients.find((x:any)=>String(x.id)===id); if(c) renderCallLogs(c,"#coachCallLog",()=>String(_coachLeadId));
      }
    };
    // Make the consultation pill groups single-select toggles (Recording / Consultation / Welcome-kit status).
    {
      const cp=_coachPanelEl();
      if(cp) cp.querySelectorAll(".pills").forEach((grp:any)=>{
        grp.querySelectorAll(".pill").forEach((b:any)=>{
          b.addEventListener("click",()=>{ grp.querySelectorAll(".pill").forEach((x:any)=>x.classList.remove("on")); b.classList.add("on"); });
        });
      });
    }
    // Clear the static demo values on load so nothing shows until a real client is opened.
    {
      const p=_coachPanelEl();
      if(p){
        p.querySelectorAll("input").forEach((i:any)=>{ if(i.type==="checkbox"||i.type==="radio")i.checked=false; else i.value=""; });
        p.querySelectorAll("textarea").forEach((t:any)=>t.value="");
        p.querySelectorAll("select").forEach((s:any)=>s.selectedIndex=0);
        p.querySelectorAll(".pill.on").forEach((b:any)=>b.classList.remove("on"));
      }
      _coachAttachments=[]; renderCoachAtts();
    }
    // Refresh the coach's visited-client list when the Health Coach screen is opened.
    {
      const coachNav=root.querySelector('#nav button[data-s="coach"]')as HTMLButtonElement|null;
      if(coachNav) coachNav.addEventListener("click",()=>{ loadCoachClients(); loadZoomCheckins(); });
      // Load the cross-client recordings tables when the Recordings screen is opened.
      const recNav=root.querySelector('#nav button[data-s="recordings"]')as HTMLButtonElement|null;
      if(recNav) recNav.addEventListener("click",()=>{ loadRecordings(); });
    }
    loadCoachClients();

    // ===== Deviation pages (Call Deviation / Leads Deviation) =====
    const _recordedLeadIds=new Set<string>();
    async function loadRecordedLeadIds(){
      try{ const {data}=await supabase.from("call_recordings").select("contact_id"); (data||[]).forEach((r:any)=>{ if(r.contact_id) _recordedLeadIds.add(String(r.contact_id)); }); }catch(_){/* telephony table may not exist */}
    }
    function _devDur(ms:number){ if(ms<0)ms=0; const h=Math.floor(ms/3600000); const m=Math.floor((ms%3600000)/60000); return h>=24?(Math.floor(h/24)+"d "+(h%24)+"h"):(h+"h "+m+"m"); }
    const DEV_MS=4*3600000;
    let _callDevRows:any[]=[], _leadDevRows:any[]=[];
    // Multi-select state for the deviation tables (by lead id, per table).
    const _devSel:{call:Set<string>,lead:Set<string>}={call:new Set(),lead:new Set()};
    function _devSyncSel(){
      (["call","lead"] as const).forEach(wk=>{
        const set=_devSel[wk]; set.clear();
        root.querySelectorAll('.devChk[data-w="'+wk+'"]:checked').forEach((c:any)=>set.add(c.getAttribute("data-id")));
        const all=root.querySelectorAll('.devChk[data-w="'+wk+'"]');
        const sa=root.querySelector("#"+wk+"DevSelAll")as HTMLInputElement|null;
        if(sa){ sa.checked=all.length>0&&set.size===all.length; sa.indeterminate=set.size>0&&set.size<all.length; }
        const cnt=root.querySelector("#"+wk+"DevSelCount"); if(cnt) cnt.textContent=set.size?(set.size+" selected"):"";
      });
    }
    w._devChkToggle=()=>_devSyncSel();
    w._devSelAll=(wk:string,on:boolean)=>{ root.querySelectorAll('.devChk[data-w="'+wk+'"]').forEach((c:any)=>{c.checked=on;}); _devSyncSel(); };

    // ---- Deviation "Assign to" controls (same behavior as the Unassigned Pool) ----
    // Service-gated like the pool: each panel's Assign-to button stays disabled until its Service
    // dropdown is set, then lists only that service's advisors (_advisorInService).
    function _populateDevAssignMenus(){
      const esc=(s:string)=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
      (["call","lead"] as const).forEach(wk=>{
        const menu=root.querySelector("#"+wk+"DevAssignMenu")as HTMLElement|null; if(!menu) return;
        _fillAssignSvcSel(wk+"DevAssignSvc");
        const svc=_assignSvcVal(wk+"DevAssignSvc");
        _gateAssignBtn(wk+"DevAssignBtn",svc);
        if(!svc){
          menu.style.display="none";
          menu.innerHTML='<div style="font-size:11.5px;color:var(--faint);padding:8px">Select a service first</div>';
          try{ w._devAssignSelChange(wk); }catch(_){}
          return;
        }
        const names=_assignTargets(svc);
        const prev=new Set(Array.from(menu.querySelectorAll(".devAdvChk:checked")).map((c:any)=>c.getAttribute("data-adv")));
        menu.innerHTML=names.length?names.map((n:string)=>'<label style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:7px;cursor:pointer;font-size:12.5px" onmouseover="this.style.background=\'var(--surface-2)\'" onmouseout="this.style.background=\'\'"><input type="checkbox" class="devAdvChk" data-w="'+wk+'" data-adv="'+esc(n)+'" style="accent-color:var(--brand)" onchange="window._devAssignSelChange(\''+wk+'\')"'+(prev.has(n)?" checked":"")+'>'+esc(n)+'</label>').join(""):_assignEmptyMsg(svc);
        try{ w._devAssignSelChange(wk); }catch(_){}
      });
    }
    w._devAssignSvcChange=(_wk:string)=>_populateDevAssignMenus();
    function _devSelectedAdvisors(wk:string):string[]{
      return Array.from(root.querySelectorAll("#"+wk+"DevAssignMenu .devAdvChk:checked")).map((c:any)=>String(c.getAttribute("data-adv"))).filter(Boolean);
    }
    w._devAssignToggle=(wk:string,e:any)=>{ if(e&&e.stopPropagation)e.stopPropagation(); const m=root.querySelector("#"+wk+"DevAssignMenu")as HTMLElement|null; if(m) m.style.display=(m.style.display==="block")?"none":"block"; };
    w._devAssignSelChange=(wk:string)=>{
      const advs=_devSelectedAdvisors(wk);
      const lab=root.querySelector("#"+wk+"DevAssignLabel")as HTMLElement|null;
      if(lab){ if(!advs.length){ lab.textContent="Assign to…"; lab.style.color="var(--muted)"; } else if(advs.length<=2){ lab.textContent=advs.join(", "); lab.style.color="var(--ink)"; } else { lab.textContent=advs.length+" advisors"; lab.style.color="var(--ink)"; } }
      const rr=root.querySelector("#"+wk+"DevRRBtn")as HTMLButtonElement|null;
      if(rr){ rr.disabled=advs.length<2; rr.style.opacity=advs.length<2?"0.5":"1"; rr.style.cursor=advs.length<2?"not-allowed":"pointer"; }
    };
    w._devAssignSelected=async(wk:string)=>{
      if(!_assignSvcVal(wk+"DevAssignSvc")){ toast("Select a service first — its advisors will load in 'Assign to'"); return; }
      const advs=_devSelectedAdvisors(wk);
      if(!advs.length){ toast("Select an advisor in 'Assign to' first"); return; }
      _devSyncSel(); const ids=Array.from(_devSel[wk as "call"|"lead"]);
      if(!ids.length){ toast("Tick one or more leads first"); return; }
      await _assignManyTo(ids,advs[0]);
      try{ wk==="call"?w._renderCallDeviation():w._renderLeadsDeviation(); }catch(_){}
    };
    w._devAssignRR=async(wk:string)=>{
      if(!_assignSvcVal(wk+"DevAssignSvc")){ toast("Select a service first — its advisors will load in 'Assign to'"); return; }
      const advs=_devSelectedAdvisors(wk);
      if(advs.length<2){ toast("Select 2 or more advisors for round-robin"); return; }
      _devSyncSel(); const ids=Array.from(_devSel[wk as "call"|"lead"]);
      if(!ids.length){ toast("Tick one or more leads first"); return; }
      const nowIso=new Date().toISOString();
      try{
        for(let i=0;i<ids.length;i++){
          const name=advs[i%advs.length];
          const {error}=await supabase.from("leads").update({assigned_to:name,is_assigned:true,in_pool:false}).eq("meta_lead_id",ids[i]);
          if(error) throw error;
          try{ await supabase.from("leads").update({assigned_at:nowIso}).eq("meta_lead_id",ids[i]); }catch(_){}
          const ld=_metaLeads.find((x:any)=>String(x.id)===ids[i]); if(ld){ld.inPool=false;ld.isAssigned=true;ld.assignedTo=name;}
          logActivity(ids[i],[{action:"Assigned",field:"Assigned to",new:name+" (round-robin)"}]);
          logAssignment(ids[i],name,"assigned");
        }
      }catch(e:any){ toast(/in_pool|column|schema|exist/i.test(e.message||"")?"Run the assignment migrations first":"Distribute failed: "+(e.message||"db error")); return; }
      await _afterAssign();
      try{ wk==="call"?w._renderCallDeviation():w._renderLeadsDeviation(); }catch(_){}
      toast(ids.length+" lead"+(ids.length===1?"":"s")+" distributed across "+advs.length+" selected advisors");
    };
    // Close a deviation assign-menu on outside click.
    document.addEventListener("click",(e:any)=>{ (["call","lead"] as const).forEach(wk=>{ const wrap=root.querySelector("#"+wk+"DevAssignWrap"); const m=root.querySelector("#"+wk+"DevAssignMenu")as HTMLElement|null; if(m&&m.style.display==="block"&&wrap&&!wrap.contains(e.target)) m.style.display="none"; }); });
    const _devEsc=(s:string)=>(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
    const _devSrcLang=(r:any)=>(r.source==="Meta Ads"?"Meta":(r.source||"Meta"))+" · "+(r.language||"Tamil");
    const _callDevCols=[
      {key:"sel",label:"",filter:false,head:'<th style="width:34px"><input type="checkbox" id="callDevSelAll" style="accent-color:var(--brand)" onchange="window._devSelAll(\'call\',this.checked)"></th>'},
      {key:"lead",label:"Lead",filter:true,text:(r:any)=>r.name||"—"},
      {key:"num",label:"Lead Number",filter:true,text:(r:any)=>r.phone||"—"},
      {key:"src",label:"Source · Lang",filter:true,text:(r:any)=>_devSrcLang(r)},
      {key:"stage",label:"Stage",filter:true,text:(r:any)=>r.is_assigned?"Assigned":"Unassigned"},
      {key:"status",label:"Status",filter:true,text:(_r:any)=>"No call activity"},
      {key:"recv",label:"Received Date & Time",filter:true,text:(r:any)=>fmtIST(r.created_at)},
      {key:"dev",label:"Deviation Time",filter:false,head:'<th>Deviation Time</th>'},
    ];
    regGrid("callDev",()=>_callDevCols,()=>{try{(w as any)._renderCallDeviation();}catch(_){}});
    const _leadDevCols=[
      {key:"sel",label:"",filter:false,head:'<th style="width:34px"><input type="checkbox" id="leadDevSelAll" style="accent-color:var(--brand)" onchange="window._devSelAll(\'lead\',this.checked)"></th>'},
      {key:"lead",label:"Lead",filter:true,text:(r:any)=>r.name||"—"},
      {key:"num",label:"Lead Number",filter:true,text:(r:any)=>r.phone||"—"},
      {key:"src",label:"Source · Lang",filter:true,text:(r:any)=>_devSrcLang(r)},
      {key:"asg",label:"Assigned To",filter:true,text:(r:any)=>r.assigned_to||"—"},
      {key:"stage",label:"Stage",filter:true,text:(_r:any)=>"Assigned"},
      {key:"status",label:"Status",filter:true,text:(_r:any)=>"Not called"},
      {key:"asgd",label:"Assigned Date & Time",filter:true,text:(r:any)=>fmtIST(r.assigned_at||r.created_at)},
      {key:"dev",label:"Deviation Time",filter:false,head:'<th>Deviation Time</th>'},
    ];
    regGrid("leadDev",()=>_leadDevCols,()=>{try{(w as any)._renderLeadsDeviation();}catch(_){}});
    function _setDevBadges(){
      const cc=root.querySelector("#callDevCount"); if(cc)cc.textContent=String(_callDevRows.length);
      const lc=root.querySelector("#leadDevCount"); if(lc)lc.textContent=String(_leadDevRows.length);
      const c1=root.querySelector("#devCardCall"); if(c1)c1.textContent=String(_callDevRows.length);
      const c2=root.querySelector("#devCardLead"); if(c2)c2.textContent=String(_leadDevRows.length);
      const dt=root.querySelector("#devTabCount"); if(dt)dt.textContent=String(_callDevRows.length+_leadDevRows.length);
    }
    // Switch between the Call / Leads deviation sub-tabs and (re)load that table.
    w._devSubTab=(v:string)=>{
      root.querySelectorAll("#devSubTabs button").forEach((b:any)=>b.classList.toggle("on",b.getAttribute("data-dt")===v));
      root.querySelectorAll(".dev-sub").forEach((d:any)=>{d.style.display=d.getAttribute("data-dtp")===v?"block":"none";});
      if(v==="call") w._renderCallDeviation(); else w._renderLeadsDeviation();
    };
    w._renderCallDeviation=async()=>{
      await loadRecordedLeadIds();
      const cutoff=new Date(Date.now()-DEV_MS).toISOString();
      const body=root.querySelector("#callDevBody"); const now0=Date.now();
      let rows:any[]=[];
      try{
        const {data}=await supabase.from("leads").select("meta_lead_id,name,phone,source,language,call_status,created_at,is_assigned")
          .lt("created_at",cutoff).or("call_status.is.null,call_status.eq.New,call_status.eq.Open").order("created_at",{ascending:true}).limit(1000);
        rows=(data||[]).filter((r:any)=>!_recordedLeadIds.has(String(r.meta_lead_id))&&inAbmRange(r.created_at));
      }catch(_){ rows=[]; }
      _callDevRows=rows; const now=now0; _setDevBadges(); const _cdh=root.querySelector("#callDevHead"); if(_cdh)_cdh.innerHTML=gridHead("callDev"); const _cdDisp=gridApply("callDev",rows);
      if(body) body.innerHTML=_cdDisp.length?_cdDisp.map((r:any)=>'<tr>'
        +'<td><input type="checkbox" class="devChk" data-w="call" data-id="'+_devEsc(String(r.meta_lead_id))+'" style="accent-color:var(--brand)" onchange="window._devChkToggle()"></td>'
        +'<td style="font-weight:600">'+_devEsc(r.name||"—")+'</td>'
        +'<td class="mono" style="font-weight:600">'+_devEsc(r.phone||"—")+'</td>'
        +'<td><span class="tag">'+_devEsc(_devSrcLang(r))+'</span></td>'
        +'<td>'+(r.is_assigned?"Assigned":"Unassigned")+'</td>'
        +'<td><span class="chipb al">No call activity</span></td>'
        +'<td class="mono" style="font-size:11.5px">'+_devEsc(fmtIST(r.created_at))+'</td>'
        +'<td class="mono" style="font-weight:700;color:var(--alert-ink)">'+_devDur(now-new Date(r.created_at).getTime())+'</td></tr>').join("")
        :'<tr><td colspan="8" style="text-align:center;color:var(--faint);padding:20px">No call deviations — every lead has activity within 4h 🎉</td></tr>';
      _devSyncSel();
      try{ _populateDevAssignMenus(); }catch(_){}
    };
    w._renderLeadsDeviation=async()=>{
      await loadRecordedLeadIds();
      const cutoffMs=Date.now()-DEV_MS;
      const body=root.querySelector("#leadDevBody");
      let rows:any[]=[];
      try{
        // Prefer assigned_at; fall back to created_at if the deviation migration isn't run yet.
        let res:any=await supabase.from("leads").select("meta_lead_id,name,phone,source,language,assigned_to,assigned_at,call_status,created_at,is_assigned")
          .eq("is_assigned",true).or("call_status.is.null,call_status.eq.New,call_status.eq.Open").limit(1000);
        if(res.error&&/assigned_at|column/i.test(res.error.message||"")){
          res=await supabase.from("leads").select("meta_lead_id,name,phone,source,language,assigned_to,call_status,created_at,is_assigned")
            .eq("is_assigned",true).or("call_status.is.null,call_status.eq.New,call_status.eq.Open").limit(1000);
        }
        if(res.error) throw res.error;
        rows=(res.data||[]).filter((r:any)=>{ if(_recordedLeadIds.has(String(r.meta_lead_id))) return false; const at=r.assigned_at||r.created_at; const t=new Date(at).getTime(); return t<cutoffMs && inAbmRange(at); });
      }catch(_){ rows=[]; }
      _leadDevRows=rows; const now=Date.now(); _setDevBadges(); const _ldh=root.querySelector("#leadDevHead"); if(_ldh)_ldh.innerHTML=gridHead("leadDev"); const _ldDisp=gridApply("leadDev",rows);
      if(body) body.innerHTML=_ldDisp.length?_ldDisp.map((r:any)=>{ const at=r.assigned_at||r.created_at; return '<tr>'
        +'<td><input type="checkbox" class="devChk" data-w="lead" data-id="'+_devEsc(String(r.meta_lead_id))+'" style="accent-color:var(--brand)" onchange="window._devChkToggle()"></td>'
        +'<td style="font-weight:600">'+_devEsc(r.name||"—")+'</td>'
        +'<td class="mono" style="font-weight:600">'+_devEsc(r.phone||"—")+'</td>'
        +'<td><span class="tag">'+_devEsc(_devSrcLang(r))+'</span></td>'
        +'<td style="font-weight:600">'+_devEsc(r.assigned_to||"—")+'</td><td>Assigned</td>'
        +'<td><span class="chipb al">Not called</span></td>'
        +'<td class="mono" style="font-size:11.5px">'+_devEsc(fmtIST(at))+'</td>'
        +'<td class="mono" style="font-weight:700;color:var(--alert-ink)">'+_devDur(now-new Date(at).getTime())+'</td></tr>';
      }).join(""):'<tr><td colspan="9" style="text-align:center;color:var(--faint);padding:20px">No lead deviations — all assigned leads called within 4h 🎉</td></tr>';
      _devSyncSel();
      try{ _populateDevAssignMenus(); }catch(_){}
    };
    w._downloadDeviation=(which:string)=>{
      if(which==="call"){ const sel=_devSel.call; let rows=_callDevRows; if(sel.size) rows=rows.filter((r:any)=>sel.has(String(r.meta_lead_id))); if(!rows.length){toast("Nothing to download");return;}
        const out:string[][]=[["Lead","Lead Number","Source","Language","Stage","Status","Received","Deviation"]];
        rows.forEach((r:any)=>out.push([r.name||"",r.phone||"",r.source||"",r.language||"",r.is_assigned?"Assigned":"Unassigned","No call activity",fmtIST(r.created_at),_devDur(Date.now()-new Date(r.created_at).getTime())]));
        _downloadCsv("call_deviation_"+rows.length+".csv",out); toast(rows.length+(sel.size?" selected":"")+" rows downloaded");
      } else { const sel=_devSel.lead; let rows=_leadDevRows; if(sel.size) rows=rows.filter((r:any)=>sel.has(String(r.meta_lead_id))); if(!rows.length){toast("Nothing to download");return;}
        const out:string[][]=[["Lead","Lead Number","Source","Language","Assigned To","Stage","Status","Assigned","Deviation"]];
        rows.forEach((r:any)=>{const at=r.assigned_at||r.created_at; out.push([r.name||"",r.phone||"",r.source||"",r.language||"",r.assigned_to||"","Assigned","Not called",fmtIST(at),_devDur(Date.now()-new Date(at).getTime())]);});
        _downloadCsv("leads_deviation_"+rows.length+".csv",out); toast(rows.length+(sel.size?" selected":"")+" rows downloaded");
      }
    };

    // ========== BLOOD TEST MODULE (live data) ==========
    let _btAll:any[]=[], _btFiltered:any[]=[], _btDate="today", _btOpenAppt:any=null, _btReportAtt:any=null;
    // Spec-fixed tests / panels catalogue used by the record detail multi-select.
    // Canonical panel CODES + names are stable (existing records store these codes in
    // blood_test_data.panels). PRICES here are just the display seed — they are refreshed live from
    // the Blood Test Pricing Master (bt_tests) by _btSyncPanelPrices(), matched by name.
    const BT_PANELS:{code:string;name:string;price:number}[]=[
      {code:"CBC",name:"Complete Blood Count (CBC)",price:400},
      {code:"FBS",name:"Fasting Blood Sugar (FBS)",price:150},
      {code:"FBHP",name:"Full Body Health Panel",price:2500},
      {code:"HBA1C",name:"HbA1c",price:600},
      {code:"KFT",name:"Kidney Function Test (KFT)",price:800},
      {code:"LIPID",name:"Lipid Profile",price:900},
      {code:"LFT",name:"Liver Function Test (LFT)",price:800},
      {code:"PPBS",name:"Postprandial Sugar (PPBS)",price:150},
      {code:"THYROID",name:"Thyroid Profile (T3/T4/TSH)",price:800},
      {code:"B12",name:"Vitamin B12",price:1200},
      {code:"VITD",name:"Vitamin D",price:1500},
    ];
    const _btPanelName=(code:string)=>{ const p=BT_PANELS.find(x=>x.code===code); return p?p.name:code; };
    // ===== Blood Test & Pricing Master (bt_tests) — Settings CRUD + the single pricing source =======
    let _btmList:any[]=[]; let _btmEditId:any=null;
    // Sync BT_PANELS display prices from the master by NAME (codes stay stable so stored panel codes
    // keep resolving). Only prices move — never the code/name identity.
    function _btSyncPanelPrices(){
      BT_PANELS.forEach(p=>{ const m=_btmList.find((t:any)=>String(t.name||"").trim().toLowerCase()===p.name.toLowerCase()); if(m&&m.price!=null) p.price=Number(m.price)||p.price; });
    }
    // Collect Payment test checkboxes — rendered LIVE from the master (active panels only), carrying
    // both the selling price (data-price) and the Thyrocare/lab cost (data-thyro) → drives the margin.
    function _cpRenderTests(){
      const box=root.querySelector("#cpTestsWrap"); if(!box) return;
      const src=(_btmList.length?_btmList:_btTests)||[];
      const active=src.filter((t:any)=>t.active!==false);
      const money=(n:any)=>"₹"+(Number(n)||0).toLocaleString("en-IN");
      box.innerHTML=active.length?active.map((t:any)=>'<label class="nwChk"><input type="checkbox" data-test="'+_attr(String(t.name||""))+'" data-price="'+(Number(t.price)||0)+'" data-thyro="'+(Number(t.lab_cost)||0)+'" onchange="window._cpTestTick()"> '+_attr(String(t.name||""))+' — '+money(t.price)+'</label>').join("")
        :'<div style="font-size:12px;color:var(--faint)">No active blood-test panels — add them in Settings → Blood Test pricing.</div>';
    }
    async function loadBtMaster(){
      try{ const r:any=await supabase.from("bt_tests").select("*").order("name"); _btmList=(r&&r.error)?[]:((r&&r.data)||[]); }catch(_){ _btmList=[]; }
      _renderBtMaster();
      // Keep every downstream reader in sync from this one load.
      _btTests=_btmList.filter((t:any)=>t.active!==false); _btMastersLoaded=true;
      _btSyncPanelPrices();
      try{ _cpRenderTests(); }catch(_){}
      try{ _btRenderTests(); }catch(_){}   // Reception intake chips, if the intake is open
    }
    function _renderBtMaster(){
      const body=root.querySelector("#btmBody"); if(!body) return;
      const money=(n:any)=>"₹"+(Number(n)||0).toLocaleString("en-IN");
      if(!_btmList.length){ body.innerHTML='<tr><td colspan="6" style="text-align:center;color:var(--faint);padding:16px;font-size:12px">No panels yet — add one above, or run db/migration-bloodtest-module.sql to seed the defaults.</td></tr>'; return; }
      body.innerHTML=_btmList.map((t:any)=>{
        const margin=(Number(t.price)||0)-(Number(t.lab_cost)||0); const on=t.active!==false;
        return '<tr><td style="font-weight:600">'+_attr(String(t.name||"—"))+'</td>'
          +'<td class="mono">'+money(t.price)+'</td>'
          +'<td class="mono">'+money(t.lab_cost)+'</td>'
          +'<td class="mono" style="font-weight:700;color:'+(margin>=0?"var(--ok-ink)":"var(--alert-ink)")+'">'+money(margin)+'</td>'
          +'<td>'+(on?'<span class="chipb ok">Active</span>':'<span class="chipb neu">Inactive</span>')+'</td>'
          +'<td><div style="display:flex;gap:5px;flex-wrap:wrap">'
            +'<button class="btn bsm" onclick="window._btmEdit(\''+_attr(String(t.id))+'\')">Edit</button>'
            +'<button class="btn bsm" onclick="window._btmToggle(\''+_attr(String(t.id))+'\','+(!on)+')">'+(on?"Deactivate":"Activate")+'</button>'
            +'<button class="btn bsm" style="color:var(--alert-ink)" onclick="window._btmDelete(\''+_attr(String(t.id))+'\')">Delete</button>'
          +'</div></td></tr>';
      }).join("");
    }
    const _btmV=(id:string)=>((root.querySelector("#"+id)as HTMLInputElement|null)?.value||"").trim();
    const _btmSetV=(id:string,val:string)=>{ const e=root.querySelector("#"+id)as HTMLInputElement|null; if(e) e.value=val; };
    w._btmMargin=()=>{ const p=Number(_btmV("btmPrice"))||0; const c=Number(_btmV("btmCost"))||0; const el=root.querySelector("#btmMargin"); if(el) el.textContent="₹"+(p-c).toLocaleString("en-IN"); };
    w._btmSave=async()=>{
      const name=_btmV("btmName"); if(!name){ toast("Enter a test / panel name"); return; }
      const price=Math.round(Number(_btmV("btmPrice"))||0);
      const cost=Math.round(Number(_btmV("btmCost"))||0);
      const rt=_btmV("btmRetest"); const retest=rt?Math.round(Number(rt)):null;
      try{
        if(_btmEditId){
          const {error}=await supabase.from("bt_tests").update({name,price,lab_cost:cost,retest_months:retest}).eq("id",_btmEditId);
          if(error) throw error; toast("Panel updated");
        }else{
          const code=(name.replace(/[^A-Za-z0-9]/g,"").toUpperCase().slice(0,16)||"PANEL")+"-"+String(Date.now()).slice(-5);
          const {error}=await supabase.from("bt_tests").insert({code,name,price,lab_cost:cost,retest_months:retest,active:true});
          if(error) throw error; toast("Panel added");
        }
        w._btmCancel(); await loadBtMaster();
      }catch(e:any){ toast(/exist|relation|schema|column/i.test(e.message||"")?"Run db/migration-bloodtest-module.sql first":"Save failed: "+(e.message||"db error")); }
    };
    w._btmEdit=(id:any)=>{
      const t=_btmList.find((x:any)=>String(x.id)===String(id)); if(!t) return;
      _btmSetV("btmName",String(t.name||"")); _btmSetV("btmPrice",t.price!=null?String(t.price):""); _btmSetV("btmCost",t.lab_cost!=null?String(t.lab_cost):""); _btmSetV("btmRetest",t.retest_months!=null?String(t.retest_months):"");
      _btmEditId=id; w._btmMargin();
      const b=root.querySelector("#btmAddBtn"); if(b)b.textContent="Update panel";
      const c=root.querySelector("#btmCancelBtn")as HTMLElement|null; if(c)c.style.display="";
    };
    w._btmCancel=()=>{ _btmEditId=null; ["btmName","btmPrice","btmCost","btmRetest"].forEach(id=>_btmSetV(id,"")); w._btmMargin();
      const b=root.querySelector("#btmAddBtn"); if(b)b.textContent="+ Add test"; const c=root.querySelector("#btmCancelBtn")as HTMLElement|null; if(c)c.style.display="none"; };
    w._btmToggle=async(id:any,active:boolean)=>{
      try{ const {error}=await supabase.from("bt_tests").update({active}).eq("id",id); if(error) throw error; await loadBtMaster(); toast(active?"Panel activated":"Panel deactivated"); }
      catch(e:any){ toast("Update failed: "+(e.message||"db error")); }
    };
    w._btmDelete=(id:any)=>{
      const t=_btmList.find((x:any)=>String(x.id)===String(id)); if(!t) return;
      if(!window.confirm('Delete "'+(t.name||"this panel")+'" from the pricing master? Past records keep their stored prices.')) return;
      supabase.from("bt_tests").delete().eq("id",id).then(async()=>{ toast("Panel deleted"); await loadBtMaster(); }).catch((e:any)=>toast("Delete failed: "+(e?.message||"db error")));
    };

    // ===== COUPON CODES MASTER (Settings → Coupon codes) =====
    // Auto-generated codes on bt_coupons — the store every Apply-coupon field already validates
    // against, so a generated code works everywhere with zero extra wiring. Format MHS + YY + MM +
    // 4-digit serial (MHS26080001); the serial is derived from the codes already saved for the
    // CURRENT month, so it restarts at 0001 on the 1st of each month with no counter to maintain.
    let _cpnList:any[]=[];
    function _cpnParts(){
      const p=new Intl.DateTimeFormat("en-GB",{timeZone:"Asia/Kolkata",year:"2-digit",month:"2-digit"}).formatToParts(new Date());
      const g=(t:string)=>p.find(x=>x.type===t)?.value||"";
      return {yy:g("year"),mm:g("month")};
    }
    const _cpnPrefix=()=>{ const d=_cpnParts(); return "MHS"+d.yy+d.mm; };
    function _cpnNextCode(){
      const pre=_cpnPrefix(); let max=0;
      _cpnList.forEach((c:any)=>{ const m=String(c.code||"").match(new RegExp("^"+pre+"(\\d{4})$")); if(m) max=Math.max(max,Number(m[1])); });
      return pre+String(max+1).padStart(4,"0");
    }
    async function _cpnLoad(){
      try{ const r:any=await supabase.from("bt_coupons").select("*").order("created_at",{ascending:false}).limit(500);
        _cpnList=(r&&!r.error&&r.data)||[];
      }catch(_){ _cpnList=[]; }
      _cpnRender();
    }
    // One status per coupon, priority: disabled → expired → exhausted → active.
    function _cpnStatus(c:any):{l:string;cls:string}{
      const today=new Date().toISOString().slice(0,10);
      if(c.active===false) return {l:"Disabled",cls:"neu"};
      if(c.valid_to&&String(c.valid_to).slice(0,10)<today) return {l:"Expired",cls:"warn"};
      if(c.max_uses!=null&&Number(c.used_count||0)>=Number(c.max_uses)) return {l:"Exhausted",cls:"warn"};
      return {l:"Active",cls:"ok"};
    }
    function _cpnRender(){
      const d=_cpnParts();
      const nx=root.querySelector("#cpnNext"); if(nx) nx.textContent=_cpnNextCode();
      const fy=root.querySelector("#cpnFmtY"); if(fy) fy.textContent=d.yy+" — year";
      const fm=root.querySelector("#cpnFmtM"); if(fm) fm.textContent=d.mm+" — month";
      const body=root.querySelector("#cpnBody"); if(!body) return;
      if(!_cpnList.length){ body.innerHTML='<tr><td colspan="6" style="text-align:center;color:var(--faint);padding:16px;font-size:12px">No coupons yet — generate the first one above.</td></tr>'; return; }
      const dt=(v:any)=>v?fmtISTDate(String(v)):"";
      body.innerHTML=_cpnList.map((c:any)=>{
        const st=_cpnStatus(c); const on=c.active!==false;
        const disc=c.discount_type==="percent"?(Number(c.discount_value)||0)+"% off":"₹"+(Number(c.discount_value)||0).toLocaleString("en-IN")+" off";
        const val=(c.valid_from||c.valid_to)?((dt(c.valid_from)||"—")+" → "+(dt(c.valid_to)||"no expiry")):"No expiry";
        const use=String(Number(c.used_count||0))+" / "+(c.max_uses!=null?String(c.max_uses):"∞");
        return '<tr><td class="mono" style="font-weight:700">'+_attr(String(c.code||"—"))
          +' <button class="btn bsm" style="height:22px;font-size:10.5px;padding:0 7px" title="Copy code" onclick="window._cpnCopy(\''+_attr(String(c.code||""))+'\')">Copy</button></td>'
          +'<td style="font-weight:600">'+disc+'</td>'
          +'<td style="font-size:12px">'+val+'</td>'
          +'<td class="mono">'+use+'</td>'
          +'<td><span class="chipb '+st.cls+'">'+st.l+'</span></td>'
          +'<td><div style="display:flex;gap:5px;flex-wrap:wrap">'
            +'<button class="btn bsm" onclick="window._cpnToggle(\''+_attr(String(c.id))+'\','+(on?"false":"true")+')">'+(on?"Disable":"Enable")+'</button>'
            +'<button class="btn bsm" style="color:var(--alert-ink)" onclick="window._cpnDel(\''+_attr(String(c.id))+'\')">Delete</button>'
          +'</div></td></tr>';
      }).join("");
    }
    w._cpnGen=async()=>{
      const type=((root.querySelector("#cpnType")as HTMLSelectElement)?.value)==="percent"?"percent":"flat";
      const value=Math.round(Number((root.querySelector("#cpnValue")as HTMLInputElement)?.value||0));
      const validTo=((root.querySelector("#cpnValidTo")as HTMLInputElement)?.value||"").trim();
      const maxRaw=((root.querySelector("#cpnMaxUses")as HTMLInputElement)?.value||"").trim();
      const maxUses=maxRaw?Math.max(1,Math.round(Number(maxRaw))):null;
      if(!(value>0)){ toastErr("Enter the discount value"); return; }
      if(type==="percent"&&value>100){ toastErr("Percent discount cannot exceed 100"); return; }
      // Refresh before numbering so two admins generating in the same minute don't collide.
      try{ const r:any=await supabase.from("bt_coupons").select("code").limit(1000); if(r&&!r.error&&r.data) _cpnList=r.data; }catch(_){/* fall back to the loaded list */}
      const code=_cpnNextCode();
      const today=new Date().toISOString().slice(0,10);
      if(!(await _dbOk(supabase.from("bt_coupons").insert({code,discount_type:type,discount_value:value,valid_from:today,valid_to:validTo||null,max_uses:maxUses,active:true}),"Generate coupon"))) return;
      try{ await navigator.clipboard.writeText(code); }catch(_){/* clipboard needs a secure context; the Copy button still works */}
      toast("Coupon "+code+" created & copied");
      const v=root.querySelector("#cpnValue")as HTMLInputElement|null; if(v) v.value="";
      await _cpnLoad();
    };
    w._cpnCopy=async(code:string)=>{ try{ await navigator.clipboard.writeText(code); toast(code+" copied"); }catch(_){ toastErr("Copy failed — select the code manually"); } };
    w._cpnCopyNext=async()=>{ const nx=root.querySelector("#cpnNext"); const code=(nx?.textContent||"").trim(); if(!/^MHS\d{8}$/.test(code)){ toastErr("Generate the coupon first"); return; } try{ await navigator.clipboard.writeText(code); toast(code+" copied — remember to Generate it"); }catch(_){ toastErr("Copy failed"); } };
    w._cpnToggle=async(id:string,on:boolean)=>{ if(await _dbOk(supabase.from("bt_coupons").update({active:on}).eq("id",id),"Update coupon")){ toast(on?"Coupon enabled":"Coupon disabled"); await _cpnLoad(); } };
    w._cpnDel=(id:string)=>{
      const c=_cpnList.find((x:any)=>String(x.id)===String(id)); if(!c) return;
      if(!window.confirm('Delete coupon "'+(c.code||"")+'"? Anywhere it was already applied keeps its discount; it just cannot be used again.')) return;
      supabase.from("bt_coupons").delete().eq("id",id).then(async()=>{ toast("Coupon deleted"); await _cpnLoad(); }).catch((e:any)=>toastErr("Delete failed: "+(e?.message||"db error")));
    };
    let _btdPanels=new Set<string>();          // selected panel codes for the open record
    let _btRowSel=new Set<string>();           // selected appointment ids for bulk actions
    let _btSearch="";                          // name/phone search term
    let _btFilt={sample:"",lab:"",labReport:"",clientReport:""};
    // Clickable summary cards: each narrows the table to its own predicate. "" = no card active.
    let _btCard="";
    const _btCardPreds:Record<string,(r:any)=>boolean>={
      total:()=>true,
      visited:(r:any)=>r.status==="visited",
      sample:(r:any)=>r.sampleStatus==="collected",
      lab:(r:any)=>r.labStatus==="sent",
      pay:(r:any)=>r.payStatus==="paid",
      notpaid:(r:any)=>r.payStatus!=="paid"&&r.payStatus!=="free",
      report:(r:any)=>r.labReportStatus==="received",
      shared:(r:any)=>r.clientReportStatus==="shared",
    };
    const _btCardDefs:{k:string;l:string;c:string}[]=[
      {k:"total",l:"Total",c:""},{k:"visited",l:"Visited",c:"g"},{k:"sample",l:"Sample collected",c:"g"},
      {k:"lab",l:"Sent to lab",c:"g"},{k:"pay",l:"Payment collected",c:"g"},{k:"notpaid",l:"Not paid",c:"r"},
      {k:"report",l:"Report received",c:"g"},{k:"shared",l:"Shared",c:"g"},
    ];
    // Simplified two-state labels (spec §4).
    const _btSampleL:any={collected:{l:"Collected",c:"ok"},yet_to_collect:{l:"Yet to Collect",c:"warn"}};
    const _btLabL:any={sent:{l:"Sent",c:"ok"},yet_to_send:{l:"Yet to Send",c:"warn"}};
    const _btLabRepL:any={received:{l:"Received",c:"ok"},yet_to_receive:{l:"Yet to Receive",c:"warn"}};
    const _btCliRepL:any={shared:{l:"Shared",c:"ok"},yet_to_share:{l:"Yet to Share",c:"warn"}};
    const _btE=(s:any)=>String(s??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
    function _btDateRange():[Date|null,Date|null]{
      const now=new Date(); const sod=(d:Date)=>{const x=new Date(d);x.setHours(0,0,0,0);return x;}; const eod=(d:Date)=>{const x=new Date(d);x.setHours(23,59,59,999);return x;};
      if(_btDate==="today") return [sod(now),eod(now)];
      if(_btDate==="tmrw"){ const t=new Date(now);t.setDate(t.getDate()+1); return [sod(t),eod(t)]; }
      if(_btDate==="yest"){ const y=new Date(now);y.setDate(y.getDate()-1); return [sod(y),eod(y)]; }
      if(_btDate==="wk"){ const s=new Date(now);s.setDate(s.getDate()-s.getDay()); return [sod(s),eod(now)]; }
      if(_btDate==="cust"){ const f=(root.querySelector("#btFrom")as HTMLInputElement)?.value; const t=(root.querySelector("#btTo")as HTMLInputElement)?.value; return [f?sod(new Date(f)):null,t?eod(new Date(t)):null]; }
      return [null,null];
    }
    // ===== Blood Test — Stage 1 (Reception intake → payment → order → sample) =================
    // Spec: WellnessOS Blood Test Service, FROZEN v2.0. Writes bt_orders; the legacy
    // appointments.blood_test_data path is left untouched so the existing screen still works.
    let _btTests:any[]=[], _btPartners:any[]=[], _btMastersLoaded=false;
    let _btSel=new Set<string>();                 // selected test ids
    let _btCoupon:any=null;                       // validated coupon row
    let _btMatch:any=null;                        // matched lead from the phone lookup
    const _btMoney=(n:any)=>"₹"+(Number(n)||0).toLocaleString("en-IN");
    // NFR-1: phones masked in list views; the full number shows on the opened record only.
    const _btMask=(p:any)=>{ const s=String(p||"").replace(/\D/g,""); return s.length<4?(p||"—"):("******"+s.slice(-4)); };
    async function _btLoadMasters(){
      if(_btMastersLoaded) return;
      try{
        const [t,p]:any[]=await Promise.all([
          supabase.from("bt_tests").select("*").eq("active",true).order("name"),
          supabase.from("bt_lab_partners").select("*").eq("active",true).order("name"),
        ]);
        // The /db gateway RESOLVES {error} instead of throwing, so a failed read looks like an
        // empty result to a bare try/catch. Caching that would leave the intake permanently
        // testless with no error shown — check .error explicitly and stay un-cached so the next
        // open retries (this is exactly how the first run silently rendered zero test chips).
        if((t&&t.error)||(p&&p.error)){
          toastErr("Couldn't load the blood-test masters — "+(((t&&t.error)||(p&&p.error)).message||"try again"));
          return;
        }
        _btTests=t.data||[]; _btPartners=p.data||[]; _btMastersLoaded=true;
      }catch(_){ /* transient — leave un-cached so the next open retries */ }
    }
    function _btRenderTests(){
      const box=root.querySelector("#btiTests"); if(!box) return;
      box.innerHTML=_btTests.length?_btTests.map((t:any)=>{
        const on=_btSel.has(String(t.id));
        return '<span class="chip-o'+(on?" on":"")+'" onclick="window._btToggleTest(\''+_btE(String(t.id))+'\')" style="cursor:pointer">'+_btE(t.name)+' · '+_btMoney(t.price)+'</span>';
      }).join(""):'<span style="font-size:12px;color:var(--faint)">No tests configured — run db/migration-bloodtest-module.sql</span>';
      const sel=root.querySelector("#btiPartner")as HTMLSelectElement|null;
      if(sel&&!sel.options.length) sel.innerHTML=_btPartners.map((p:any)=>'<option'+(p.is_default?" selected":"")+'>'+_btE(p.name)+'</option>').join("");
      _btRecalc();
    }
    // FR-1.5: price is always derived from the master, never typed.
    function _btRecalc(){
      const gross=_btTests.filter((t:any)=>_btSel.has(String(t.id))).reduce((s:number,t:any)=>s+(Number(t.price)||0),0);
      let disc=0;
      if(_btCoupon) disc=_btCoupon.discount_type==="percent"?Math.round(gross*(Number(_btCoupon.discount_value)||0)/100):(Number(_btCoupon.discount_value)||0);
      disc=Math.min(disc,gross);
      const net=Math.max(0,gross-disc);
      const c=root.querySelector("#btiCalc")as HTMLInputElement|null;
      if(c) c.value=_btMoney(net)+(disc?("  (−"+_btMoney(disc)+")"):"");
      const amt=root.querySelector("#btiAmount")as HTMLInputElement|null;
      if(amt&&!amt.dataset.touched) amt.value=String(net);   // prefill; reception can override (FR-1.8)
      return {gross,disc,net};
    }
    w._btToggleTest=(id:string)=>{ if(_btSel.has(id))_btSel.delete(id); else _btSel.add(id); _btRenderTests(); };
    w._btIntakeOpen=async()=>{
      await _btLoadMasters();
      _btSel=new Set(); _btCoupon=null; _btMatch=null;
      ["btiPhone","btiName","btiWa","btiEmail","btiCoupon","btiAmount"].forEach(id=>{const e=root.querySelector("#"+id)as HTMLInputElement|null; if(e){e.value=""; delete e.dataset.touched;}});
      const m=root.querySelector("#btiMatch"); if(m) m.innerHTML="";
      const cm=root.querySelector("#btiCouponMsg"); if(cm) cm.innerHTML="";
      const f=root.querySelector("#btiForm")as HTMLElement|null; if(f) f.style.display="none";
      const s=root.querySelector("#btIntakeSec")as HTMLElement|null; if(s){ s.style.display=""; _scrollMainTo(s); }
      _btRenderTests();
      const amt=root.querySelector("#btiAmount")as HTMLInputElement|null; if(amt) amt.addEventListener("input",()=>{amt.dataset.touched="1";},{once:true});
    };
    w._btIntakeClose=()=>{ const s=root.querySelector("#btIntakeSec")as HTMLElement|null; if(s) s.style.display="none"; };
    // FR-1.1 / FR-1.2 / FR-1.3 — existing-record check by phone.
    w._btLookup=async()=>{
      const ph=((root.querySelector("#btiPhone")as HTMLInputElement|null)?.value||"").replace(/\D/g,"");
      const box=root.querySelector("#btiMatch");
      if(ph.length<10){ if(box) box.innerHTML='<span style="color:var(--alert-ink)">Enter a 10-digit number</span>'; return; }
      const last10=ph.slice(-10);
      let hit:any=null;
      try{ const r:any=await supabase.from("leads").select("meta_lead_id,name,phone,email,call_status,enrolled_at").ilike("phone","%"+last10).limit(1);
        if(r&&r.error) throw new Error(r.error.message); hit=r?.data&&r.data[0];
      }catch(e:any){ if(box) box.innerHTML='<span style="color:var(--alert-ink)">Lookup failed — '+_btE(e.message||"try again")+'</span>'; return; }
      const f=root.querySelector("#btiForm")as HTMLElement|null; if(f) f.style.display="";
      const setv=(id:string,v:string)=>{const e=root.querySelector("#"+id)as HTMLInputElement|null; if(e) e.value=v||"";};
      if(hit){
        _btMatch=hit;
        // FR-1.2: known person → prefill and go straight on; no re-entry of personal details.
        setv("btiName",hit.name||""); setv("btiEmail",hit.email||""); setv("btiWa",last10);
        if(box) box.innerHTML='<span class="chipb ok">Existing record found</span> <b>'+_btE(hit.name||"Client")+'</b>'+(hit.enrolled_at?' <span class="chipb info">Member</span>':'');
        const ct=root.querySelector("#btiClientType")as HTMLSelectElement|null; if(ct&&hit.enrolled_at) ct.value="membership";
      }else{
        _btMatch=null; setv("btiWa",last10);
        if(box) box.innerHTML='<span class="chipb warn">New client</span> <span style="color:var(--muted)">enter name to create a record</span>';
      }
    };
    // FR-1.6 — optional coupon; invalid/expired/exhausted each get their own reason.
    w._btApplyCoupon=async()=>{
      const el=root.querySelector("#btiCoupon")as HTMLInputElement|null;
      const msg=root.querySelector("#btiCouponMsg");
      const code=((el?.value)||"").trim().toUpperCase();
      _btCoupon=null;
      if(!code){ if(msg) msg.innerHTML=""; _btRecalc(); return; }
      try{
        const r:any=await supabase.from("bt_coupons").select("*").eq("code",code).limit(1);
        if(r&&r.error) throw new Error(r.error.message);
        const c=r?.data&&r.data[0];
        const today=_todayLocal();
        let bad="";
        if(!c) bad="Invalid code";
        else if(!c.active) bad="This code is no longer active";
        else if(c.valid_from&&today<String(c.valid_from).slice(0,10)) bad="This code isn't valid yet";
        else if(c.valid_to&&today>String(c.valid_to).slice(0,10)) bad="This code has expired";
        else if(c.max_uses!=null&&Number(c.used_count||0)>=Number(c.max_uses)) bad="This code has reached its usage limit";
        if(bad){ if(msg) msg.innerHTML='<span style="color:var(--alert-ink)">'+_btE(bad)+'</span>'; _btRecalc(); return; }
        _btCoupon=c;
        const {disc}=_btRecalc();
        if(msg) msg.innerHTML='<span style="color:var(--ok-ink)">Applied — '+_btMoney(disc)+' off</span>';
      }catch(e:any){ if(msg) msg.innerHTML='<span style="color:var(--alert-ink)">Could not check the code</span>'; _btRecalc(); }
    };
    // FR-1.7 → FR-1.11 — contact gate, then order generation.
    w._btCreateOrder=async()=>{
      const val=(id:string)=>((root.querySelector("#"+id)as HTMLInputElement|HTMLSelectElement|null)?.value||"").trim();
      const phone=val("btiPhone").replace(/\D/g,""), name=val("btiName"), wa=val("btiWa").replace(/\D/g,""), email=val("btiEmail");
      if(phone.length<10){ toastErr("Enter a valid phone number"); return; }
      if(!name){ toastErr("Name is required"); return; }
      if(!_btSel.size){ toastErr("Select at least one test"); return; }
      // FR-1.7: WhatsApp is mandatory (it drives report delivery + all reminders); email optional.
      if(wa.length<10){ toastErr("WhatsApp number is required — it's what report delivery and reminders use"); return; }
      const mode=val("btiMode"); if(!mode){ toastErr("Select a payment mode"); return; }
      const amount=Math.round(Number(val("btiAmount"))||0);
      if(amount<=0){ toastErr("Enter the amount collected"); return; }
      const {gross,disc}=_btRecalc();
      const tests=_btTests.filter((t:any)=>_btSel.has(String(t.id))).map((t:any)=>({id:t.id,code:t.code,name:t.name,price:t.price}));
      // FR-1.16 / Section 4 "Visit number" — count prior visits for this phone, never overwrite.
      let visitNo=1;
      try{ const pr:any=await supabase.from("bt_orders").select("id").eq("phone",phone);
        if(!(pr&&pr.error)) visitNo=((pr?.data)||[]).length+1; }catch(_){}
      const clientType=val("btiClientType")||"one-time";
      // FR-5A.1: next re-test date uses the PANEL-specific cadence — shortest among the selected
      // panels wins, and panels with no cadence contribute nothing (no auto reminder at all).
      const cadences=_btTests.filter((t:any)=>_btSel.has(String(t.id))).map((t:any)=>Number(t.retest_months)||0).filter((n:number)=>n>0);
      let nextDue:string|null=null;
      if(cadences.length){ const d=new Date(); d.setMonth(d.getMonth()+Math.min(...cadences)); nextDue=d.toISOString().slice(0,10); }
      const row:any={ lead_id:_btMatch?String(_btMatch.meta_lead_id):null, client_name:name, phone, email:email||null, whatsapp:wa,
        visit_no:visitNo, tests, lab_partner:val("btiPartner")||null, calc_price:gross, coupon_code:_btCoupon?_btCoupon.code:null,
        discount:disc, amount_collected:amount, payment_mode:mode, payment_verified:false,
        client_type:clientType, next_due_date:nextDue, created_by:(_currentUser&&(_currentUser.name||_currentUser.email))||"Reception" };
      if(!(await _dbOk(supabase.from("bt_orders").insert(row),"Order"))) return;
      // Bump coupon usage so max_uses actually caps (best-effort; the order already stands).
      if(_btCoupon) try{ await supabase.from("bt_coupons").update({used_count:Number(_btCoupon.used_count||0)+1}).eq("id",_btCoupon.id); }catch(_){}
      // FR-1.3: a brand-new walk-in also becomes a master client record, so downstream modules
      // (Reception, Advisor, Reports) see the person like any other lead.
      if(!_btMatch){
        const newId="bt-"+Date.now()+"-"+Math.floor(Math.random()*1e6);
        try{ await supabase.from("leads").insert({meta_lead_id:newId,name,phone:"+91"+phone.slice(-10),email:email||null,source:"Walk-in / Referral / Telecalling",service:"Blood Test",language:"Tamil",is_valid:true,created_at:new Date().toISOString()}); }catch(_){}
      }
      // NFR-2: immutable, timestamped entry on the client's activity timeline.
      if(_btMatch) logActivity(String(_btMatch.meta_lead_id),[{action:"Payment",field:"Blood test order (visit "+visitNo+")",new:_btMoney(amount)+" · "+mode}]);
      toast("Order generated — "+_btMoney(amount)+" · Pending Accounts Verification");
      w._btIntakeClose();
      await loadBloodTestData();
      // FR-1.11 / FR-1.12: two distinct printables off the same payment record.
      _btLastOrder={...row,visit_no:visitNo};
      _btPrint("order");
    };
    let _btLastOrder:any=null;
    // FR-1.11 Order slip (internal) and FR-1.12 Receipt (client-facing, carried to the phlebotomist).
    function _btPrint(kind:"order"|"receipt",o?:any){
      const d=o||_btLastOrder; if(!d){ toast("Nothing to print"); return; }
      const rows=(d.tests||[]).map((t:any)=>'<tr><td>'+_btE(t.name)+'</td><td style="text-align:right">'+_btMoney(t.price)+'</td></tr>').join("");
      const title=kind==="order"?"BLOOD TEST — ORDER SLIP":"PAYMENT RECEIPT";
      const html='<html><head><title>'+title+'</title><style>body{font-family:system-ui,Arial;padding:26px;color:#111}'
        +'h2{margin:0 0 2px;font-size:17px}.mut{color:#666;font-size:12px}table{width:100%;border-collapse:collapse;margin-top:14px;font-size:13px}'
        +'td,th{padding:6px 4px;border-bottom:1px solid #ddd;text-align:left}.tot td{font-weight:700;border-top:2px solid #333;border-bottom:none}'
        +'.box{border:1px solid #ddd;border-radius:8px;padding:12px;margin-top:14px;font-size:12.5px}</style></head><body>'
        +'<h2>My Health School — Wellness Center</h2><div class="mut">Chennai · HQ</div>'
        +'<h3 style="margin:16px 0 0;font-size:14px">'+title+'</h3>'
        +'<div class="mut">'+new Date().toLocaleString("en-IN")+' · Visit #'+_btE(String(d.visit_no||1))+'</div>'
        +'<div class="box"><b>'+_btE(d.client_name||"")+'</b><br>'+_btE(d.phone||"")+(d.lab_partner?('<br>Lab: '+_btE(d.lab_partner)):'')+'</div>'
        +'<table><thead><tr><th>Test / panel</th><th style="text-align:right">Price</th></tr></thead><tbody>'+rows
        +'<tr><td>Calculated total</td><td style="text-align:right">'+_btMoney(d.calc_price)+'</td></tr>'
        +(d.discount?('<tr><td>Discount'+(d.coupon_code?(" ("+_btE(d.coupon_code)+")"):"")+'</td><td style="text-align:right">−'+_btMoney(d.discount)+'</td></tr>'):'')
        +'<tr class="tot"><td>Amount '+(kind==="receipt"?"received":"collected")+'</td><td style="text-align:right">'+_btMoney(d.amount_collected)+'</td></tr>'
        +'</tbody></table>'
        +'<div class="box">Payment mode: <b>'+_btE(d.payment_mode||"—")+'</b><br>Status: Pending Accounts Verification</div>'
        +(kind==="receipt"?'<div class="box">Please present this receipt to the phlebotomist before your blood draw.</div>':'')
        +'</body></html>';
      try{ const win=window.open("","_blank","width=560,height=760"); if(!win){ toastErr("Allow pop-ups to print"); return; }
        win.document.write(html); win.document.close(); win.focus(); setTimeout(()=>{ try{win.print();}catch(_){} },250);
      }catch(_){ toastErr("Could not open the print view"); }
    }
    w._btPrintOrder=(id:any)=>{ const o=_btOrders.find((x:any)=>String(x.id)===String(id)); _btPrint("order",o); };
    w._btPrintReceipt=(id:any)=>{ const o=_btOrders.find((x:any)=>String(x.id)===String(id)); _btPrint("receipt",o); };
    // FR-1.13 / FR-1.14 — sample collection ID captured at the draw, then used to chase the lab.
    w._btSetSample=async(id:any)=>{
      const o=_btOrders.find((x:any)=>String(x.id)===String(id)); if(!o) return;
      const sid=window.prompt("Sample Collection ID / barcode for "+(o.client_name||"client")+":",o.sample_id||"");
      if(sid==null) return;
      const v=String(sid).trim(); if(!v){ toastErr("Sample ID can't be empty"); return; }
      if(!(await _dbOk(supabase.from("bt_orders").update({sample_id:v,sample_status:"collected"}).eq("id",o.id),"Sample collection"))) return;
      if(o.lead_id) logActivity(String(o.lead_id),[{action:"Updated",field:"Blood test sample collected",new:v}]);
      toast("Sample marked collected · "+v);
      await loadBloodTestData();
    };
    let _btOrders:any[]=[];
    async function _btLoadOrders(){
      try{ const r:any=await supabase.from("bt_orders").select("*").order("created_at",{ascending:false}).limit(500);
        _btOrders=(r&&r.error)?[]:((r?.data)||[]);
      }catch(_){ _btOrders=[]; }
    }
    // FR-1.15 — one worklist row carrying every status the desk needs at a glance.
    function _btRenderOrders(){
      const el=root.querySelector("#btOrdersWrap"); if(!el) return;
      const [from,to]=_btDateRange();
      const rows=_btOrders.filter((o:any)=>{ if(!o.created_at) return true; const d=new Date(o.created_at); if(from&&d<from)return false; if(to&&d>to)return false; return true; });
      const pay=(o:any)=>o.payment_verified?'<span class="chipb ok">'+_btMoney(o.amount_collected)+' ✓</span>':'<span class="chipb warn">'+_btMoney(o.amount_collected)+' · pending</span>';
      const smap:any={pending:{l:"Pending",c:"warn"},collected:{l:"Collected",c:"info"},done:{l:"Done",c:"ok"}};
      let h='<table class="tbl" style="min-width:1080px"><thead><tr><th>Date</th><th>Client</th><th>Phone</th><th>Visit</th><th>Panel(s)</th><th>Lab</th><th>Sample ID</th><th>Sample</th><th>Payment</th><th>Report</th><th>Shared</th><th>Actions</th></tr></thead><tbody>';
      if(!rows.length) h+='<tr><td colspan="12" style="text-align:center;color:var(--faint);padding:20px">No blood-test orders for this period. Use “+ New walk-in” to start one.</td></tr>';
      else rows.forEach((o:any)=>{
        const ss=smap[o.sample_status]||{l:o.sample_status,c:"neu"};
        h+='<tr><td class="mono" style="font-size:11.5px;white-space:nowrap">'+_btE(fmtIST(o.created_at))+'</td>'
          +'<td style="font-weight:600">'+_btE(o.client_name||"—")+'</td>'
          +'<td class="mono">'+_btE(_btMask(o.phone))+'</td>'
          +'<td class="mono">#'+_btE(String(o.visit_no||1))+'</td>'
          +'<td style="max-width:210px;white-space:normal">'+_btE(((o.tests||[]).map((t:any)=>t.name).join(", "))||"—")+'</td>'
          +'<td>'+_btE(o.lab_partner||"—")+'</td>'
          +'<td class="mono">'+_btE(o.sample_id||"—")+'</td>'
          +'<td><span class="chipb '+ss.c+'">'+_btE(ss.l)+'</span></td>'
          +'<td>'+pay(o)+'</td>'
          +'<td><span class="chipb '+(o.report_status==="ready"?"ok":"warn")+'">'+(o.report_status==="ready"?"Ready":"Pending")+'</span></td>'
          +'<td>'+(o.shared_status?'<span class="chipb ok">'+_btE(String(o.shared_status).toUpperCase())+' ✓</span>':"—")+'</td>'
          +'<td><div style="display:flex;gap:4px;flex-wrap:wrap">'
            +'<button class="btn bsm" title="Print internal order slip" onclick="window._btPrintOrder(\''+_btE(String(o.id))+'\')">Order</button>'
            +'<button class="btn bsm" title="Print client receipt" onclick="window._btPrintReceipt(\''+_btE(String(o.id))+'\')">Receipt</button>'
            +(o.sample_status==="pending"?'<button class="btn bsm bp" onclick="window._btSetSample(\''+_btE(String(o.id))+'\')">Sample ID</button>':'')
          +'</div></td></tr>';
      });
      h+='</tbody></table>';
      el.innerHTML=h;
    }
    async function loadBloodTestData(){
      await _btLoadMasters();
      await _btLoadOrders();
      _btRenderOrders();
      return _btLoadLegacy();
    }
    async function _btLoadLegacy(){
      try{
        const [ar,pr]=await Promise.all([
          supabase.from("appointments").select("*").ilike("service","%blood%").order("appt_date",{ascending:false}).limit(500),
          supabase.from("payments").select("*").order("created_at",{ascending:false})
        ]);
        const pays:Record<string,any>={}; (pr.data||[]).forEach((p:any)=>{ if(p.appointment_id&&!pays[p.appointment_id]) pays[p.appointment_id]=p; });
        // The client's email is captured at REGISTRATION and lives on the LEAD (leads.email);
        // blood_test_data.client_email only exists once someone types into this table's cell. Reading
        // just the latter left the column blank for every client who registered with an email
        // (reported: testingleads@gmail.com registered, cell empty). Resolve both — see `email` below.
        const _leadIds=Array.from(new Set((ar.data||[]).map((a:any)=>a.lead_id).filter(Boolean)));
        const _emailByLead:Record<string,string>={};
        if(_leadIds.length){
          try{
            const {data:le}=await supabase.from("leads").select("meta_lead_id,email").in("meta_lead_id",_leadIds);
            (le||[]).forEach((l:any)=>{ const e=String(l.email||"").trim(); if(e) _emailByLead[String(l.meta_lead_id)]=e; });
          }catch(_){ /* email is a convenience here — never block the worklist on it */ }
        }
        _btAll=(ar.data||[]).map((a:any)=>{
          const pay=pays[a.id]; const bt=a.blood_test_data||{};
          // Normalize legacy sample_status (pending/collected/sent_to_lab/done) onto the new
          // two-state model; only an explicit "collected" counts as collected.
          const sampleStatus=(bt.sample_status==="collected"||bt.sample_status==="done")?"collected":(bt.sample_status==="yet_to_collect"?"yet_to_collect":"yet_to_collect");
          const labStatus=(bt.lab_status==="sent"||bt.sample_status==="sent_to_lab"||bt.sample_status==="done")?"sent":"yet_to_send";
          const labReportStatus=(bt.lab_report_status==="received"||bt.report_status==="ready"||bt.report_status==="shared")?"received":"yet_to_receive";
          const clientReportStatus=(bt.client_report_status==="shared"||bt.shared||bt.report_status==="shared")?"shared":"yet_to_share";
          // panels: prefer the new array; fall back to the legacy free-text panel string.
          const panels:string[]=Array.isArray(bt.panels)?bt.panels:[];
          // Dates on this page are the VISIT (check-in), not the booked/lead date — see _visitStamp.
          const vs=_visitStamp(a);
          return { id:a.id, lead_id:a.lead_id, name:a.client_name||"Client", ph:a.phone||"", _date:vs.key, date:vs.date, time:vs.time,
            status:a.status||"expected", stage:a.stage||"", session:a.session||"",
            panels, panelText:panels.length?panels.map(_btPanelName).join(", "):(bt.panel||""),
            sampleStatus, labStatus, labReportStatus, clientReportStatus, reportUrl:bt.report_url||"",
            shared:clientReportStatus==="shared", thyroCost:bt.thyrocare_cost||0, ourPrice:bt.our_price||0,
            payStatus:pay?pay.status:"due", payAmt:pay?pay.amount:0, payMethod:pay?pay.method:"", payVerified:pay?pay.verified:false,
            // leadEmail = what the client registered with; email = what this page acts on, with a
            // typed-in client_email overriding it (clearing that cell falls back to the registered one).
            leadEmail:_emailByLead[String(a.lead_id)]||"",
            email:String(bt.client_email||"").trim()||_emailByLead[String(a.lead_id)]||"",
            btData:bt, raw:a };
        });
      }catch(e:any){ _btAll=[]; if(/blood_test_data|column/i.test(e.message||"")) toast("Run supabase-migration-module-columns.sql to enable blood test data"); }
      _btApplyDateFilter();
    }
    function _btApplyDateFilter(){
      const [from,to]=_btDateRange();
      // Backstop for a row whose booked date is unusable too: an unplaceable record must not land in
      // every period. It stays visible only when no range is set, instead of padding each day's count
      // and TOTAL BILLED (4 Aug read 13 records / ₹9,350 against the 10 / ₹9,000 actually on that day).
      _btFiltered=_btAll.filter((r:any)=>{
        const raw=String(r._date||"");
        const d=raw?new Date(/T/.test(raw)?raw:(raw+"T12:00:00")):null;
        if(!d||isNaN(d.getTime())) return !from&&!to;
        if(from&&d<from)return false; if(to&&d>to)return false; return true;
      });
      _btRenderAll();
      try{ _btRenderOrders(); }catch(_){}   // the new bt_orders worklist shares this date filter
    }
    w._btDateF=(d:string)=>{ _btDate=d; const show=d==="cust"; ["btFrom","btTo"].forEach(id=>{const el=root.querySelector("#"+id)as HTMLElement;if(el)el.style.display=show?"inline":"none";}); const ab=root.querySelector("#btApplyBtn")as HTMLElement|null; if(ab) ab.style.display=show?"inline-flex":"none"; root.querySelectorAll("#btDateFilt .pill").forEach((b:any)=>b.classList.remove("on")); const idx={today:0,tmrw:1,yest:2,wk:3,cust:4}[d]??0; root.querySelectorAll("#btDateFilt .pill")[idx]?.classList.add("on"); if(d!=="cust") _btApplyDateFilter(); };   // presets apply at once; Custom waits for the Apply button
    w._btApplyDate=()=>{ if(_btDate==="cust") _btApplyDateFilter(); };   // triggered by the Custom-range Apply button
    // Rows visible after the search + status filters are applied on top of the date filter.
    function _btVisibleRows(){
      const q=_btSearch.trim().toLowerCase();
      const cardPred=(_btCard&&_btCardPreds[_btCard])||null;   // active summary-card filter
      return _btFiltered.filter((r:any)=>{
        if(cardPred&&!cardPred(r)) return false;
        if(q&&!((r.name||"").toLowerCase().includes(q)||String(r.ph||"").toLowerCase().includes(q))) return false;
        if(_btFilt.sample&&r.sampleStatus!==_btFilt.sample) return false;
        if(_btFilt.lab&&r.labStatus!==_btFilt.lab) return false;
        if(_btFilt.labReport&&r.labReportStatus!==_btFilt.labReport) return false;
        if(_btFilt.clientReport&&r.clientReportStatus!==_btFilt.clientReport) return false;
        return true;
      });
    }
    // ===== Worklist inline fields: client email, the three stage timestamps, the report file =====
    // All six live on appointments.blood_test_data (JSONB), so no migration is needed — the same
    // blob the detail panel already owns. Every write merges into the CURRENT blob so a field saved
    // from the row can never drop a key the detail panel wrote, and goes through _dbOk, because the
    // gateway resolves {error} rather than throwing (a bare try/catch here would swallow failures).
    // ---- Milestone timestamps: stamped AUTOMATICALLY, never typed ----
    // [status field, the value that means "done", timestamp field]. Each of the four workflow
    // statuses owns one date column; the column is filled the moment the status reaches its done
    // value and cleared if it is moved back, so the dates are a record of what actually happened
    // rather than free text staff can back-date.
    const BT_STATUS_STAMPS:[string,string,string][]=[
      ["sample_status","collected","sample_sent_at"],
      ["lab_status","sent","lab_sent_at"],
      ["lab_report_status","received","lab_report_received_at"],
      ["client_report_status","shared","client_shared_at"],
    ];
    // Apply the stamp rule for ONE status write. Only a status that actually CHANGED touches its
    // timestamp — a record whose status was already "done" keeps its original stamp, and a legacy
    // record with a missing stamp is never back-filled with a false "now".
    function _btStampStatus(bt:any,prev:any,field:string,value:string){
      const m=BT_STATUS_STAMPS.find((x)=>x[0]===field); if(!m) return;
      const done=m[1], ts=m[2];
      const before=String((prev||{})[field]||"");
      const next=String(value||"");
      if(next===before) return;                                   // unchanged → leave the stamp alone
      if(next===done) bt[ts]=new Date().toISOString(); else bt[ts]="";
    }
    // Patch ONE key on a row's blood_test_data. Returns false (and toasts) if the write failed, so
    // the in-memory row is only updated once the database actually took it.
    async function _btPatchRow(id:any,patch:Record<string,any>):Promise<boolean>{
      const r=_btAll.find((x:any)=>String(x.id)===String(id));
      if(!r){ toastErr("Blood test record not found"); return false; }
      const bt={...(r.btData||{}),...patch};
      const ok=await _dbOk(supabase.from("appointments").update({blood_test_data:bt}).eq("id",r.id),"Blood test record");
      if(!ok) return false;
      r.btData=bt;                       // keep the row in step without a full re-render
      return true;
    }
    w._btRowEmail=async(id:string,val:string)=>{
      const email=String(val||"").trim();
      // Same shape check the browser applies to type="email"; empty is allowed (clearing the field).
      if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){ toastErr("Enter a valid email address"); return; }
      if(!await _btPatchRow(id,{client_email:email})) return;
      // Clearing the cell drops the override, so the row falls back to the registered lead email.
      const r=_btAll.find((x:any)=>String(x.id)===String(id));
      const eff=email||(r?String(r.leadEmail||""):"");
      if(r) r.email=eff;
      // Flip the row's Email Send button live rather than repainting the table.
      const btn=root.querySelector('#btMail-'+CSS.escape(String(id)))as HTMLButtonElement|null;
      if(btn){ btn.disabled=!eff; btn.title=eff?("Email the report to "+eff):"Add a client email first"; }
    };
    // No mail transport exists in this codebase (server deps are cors/dotenv/express/pg only), so
    // this opens the staff member's own mail client with the message prefilled — real and working
    // today — rather than faking a "sent" toast the way _btShareWA does.
    w._btRowMail=(id:string)=>{
      const r=_btAll.find((x:any)=>String(x.id)===String(id)); if(!r) return;
      const to=String(r.email||(r.btData||{}).client_email||"").trim();
      if(!to){ toastErr("Add a client email first"); return; }
      const url=String((r.btData||{}).report_url||"");
      const subject=`Your blood test report — ${r.name||"MHS Wellness"}`;
      const body=`Dear ${r.name||"Client"},\n\nYour blood test report is ready.\n`
        +(url?`\nDownload: ${url}\n`:`\n(The report file is attached.)\n`)
        +`\nRegards,\nMHS Wellness Centre`;
      window.location.href=`mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    };
    // WhatsApp twin of _btRowMail — same message, sent via wa.me so it opens WhatsApp Web/app with
    // the report text prefilled. Indian numbers: a bare 10-digit phone gets the 91 country code
    // (wa.me refuses numbers without one); anything already carrying a code is passed through.
    w._btRowWa=(id:string)=>{
      const r=_btAll.find((x:any)=>String(x.id)===String(id)); if(!r) return;
      let d=String(r.ph||"").replace(/\D/g,"");
      if(d.length===11&&d.startsWith("0")) d=d.slice(1);
      if(d.length===10) d="91"+d;
      if(d.length<11){ toastErr("No usable phone number on this record"); return; }
      const url=String((r.btData||{}).report_url||"");
      const body=`Dear ${r.name||"Client"},\n\nYour blood test report is ready.\n`
        +(url?`\nDownload: ${url}\n`:``)
        +`\nRegards,\nMHS Wellness Centre`;
      window.open("https://wa.me/"+d+"?text="+encodeURIComponent(body),"_blank","noopener");
    };
    // Per-row report upload. Mirrors _btAddReport (same bucket, same path shape, same 15 MB cap and
    // the same "buckets not created yet" hint) but writes straight to the row instead of the panel,
    // and reuses report_url so the row and the detail panel stay one field, not two.
    w._btRowUpload=(id:string)=>{
      const r=_btAll.find((x:any)=>String(x.id)===String(id)); if(!r) return;
      const inp=document.createElement("input"); inp.type="file"; inp.accept=".pdf,.jpg,.jpeg,.png,.webp";
      inp.onchange=async()=>{
        const file=inp.files&&inp.files[0]; if(!file) return;
        if(file.size>15*1024*1024){ toastErr("Max 15 MB"); return; }
        toast("Uploading…");
        const safe=(s:any)=>String(s).replace(/[^a-zA-Z0-9._-]/g,"_");
        const path="bloodtest/"+safe(r.lead_id||r.id)+"/"+Date.now()+"_"+safe(file.name);
        try{
          const up=await supabase.storage.from("lead-files").upload(path,file,{upsert:false});
          if(up.error) throw up.error;
          const {data}=supabase.storage.from("lead-files").getPublicUrl(path);
          if(!await _btPatchRow(id,{report_url:(data&&data.publicUrl)||"",report_name:file.name})) return;
          _btRenderAll();                 // filename cell + Email Send link both change
          toast("Report attached");
        }catch(e:any){
          toastErr(/bucket|not found|policy/i.test(e?.message||"")
            ? "Storage buckets aren't created yet — run supabase-migration-storage-buckets.sql"
            : "Upload failed: "+(e?.message||"error"));
        }
      };
      inp.click();
    };
    function _btRenderAll(){
      const f=_btFiltered;
      // Total billed / Thyrocare cost / our margin / paid-to-Thyrocare used to be rendered here as a
      // running total for the date filter — moved to Accounts & finance → "Blood test — Thyrocare",
      // which shows the same money broken down per day (renderAccThyro / _accThyroRows) instead of
      // one lump figure, from the SAME definitions so the two screens can never disagree.
      const el=(id:string)=>root.querySelector("#"+id);
      // Clickable summary cards — counts are period totals (from the date-filtered set); clicking a
      // card filters the table below to that card's records. The active card is highlighted.
      const me=el("btMetrics"); if(me)(me as HTMLElement).innerHTML=_btCardDefs.map(m=>{
        const active=_btCard===m.k;
        const v=f.filter(_btCardPreds[m.k]).length;
        return '<div class="metric '+m.c+'" role="button" tabindex="0" title="Filter to '+_btE(m.l)+'" onclick="window._btCardFilter(\''+m.k+'\')" style="cursor:pointer'+(active?';box-shadow:0 0 0 2px var(--brand-600) inset':'')+'"><div class="ml">'+_btE(m.l)+'</div><div class="mv">'+v+'</div></div>';
      }).join("");
      // Drop selections that are no longer visible so the bulk bar stays honest.
      const vis=_btVisibleRows(); const visIds=new Set(vis.map((r:any)=>String(r.id)));
      _btRowSel.forEach(id=>{ if(!visIds.has(id)) _btRowSel.delete(id); });
      const chip=(m:any,v:string)=>{ const o=m[v]||{l:v||"—",c:"neu"}; return '<span class="chipb '+o.c+'">'+_btE(o.l)+'</span>'; };
      const allOn=vis.length>0&&vis.every((r:any)=>_btRowSel.has(String(r.id)));
      let wl='<table class="tbl" style="min-width:2100px"><thead><tr>'
        +'<th scope="col" style="width:28px"><input type="checkbox" '+(allOn?"checked":"")+' onclick="window._btToggleAll(this.checked)" aria-label="Select all rows" title="Select all"></th>'
        +'<th scope="col">Visit date &amp; time</th><th scope="col">Client</th><th scope="col">Client email</th>'
        +'<th scope="col">Phone</th><th scope="col">Panel(s)</th>'
        +'<th scope="col">Sample</th><th scope="col">Sample sent date &amp; time</th>'
        +'<th scope="col">Lab</th><th scope="col">Lab report sent date &amp; time</th>'
        +'<th scope="col">Lab report</th><th scope="col">Lab report received date &amp; time</th>'
        +'<th scope="col">Client report</th><th scope="col">Client share date &amp; time</th>'
        +'<th scope="col">Actions</th><th scope="col">Email send</th><th scope="col">WhatsApp send</th><th scope="col">Add report</th></tr></thead><tbody>';
      if(!vis.length) wl+='<tr><td colspan="18" style="text-align:center;color:var(--faint);padding:20px">No blood test records match.</td></tr>';
      else vis.forEach((r:any)=>{
        const on=_btRowSel.has(String(r.id));
        const bt=r.btData||{};
        const rid=_btE(String(r.id));
        const email=String(r.email||"");   // typed-in override, else the email captured at registration
        // Shared styling for the five inline editors so they match the table's existing controls.
        const inStyle='height:30px;font-size:11.5px;padding:0 7px';
        // Read-only: these four dates are stamped automatically when their status changes (see
        // BT_STATUS_STAMPS), so the cell reports the milestone instead of inviting a typed date.
        const dtCell=(key:string,label:string)=>{
          const iso=String(bt[key]||"");
          return '<td class="mono" style="font-size:11.5px;white-space:nowrap'+(iso?'':';color:var(--faint)')+'"'
            +' title="'+_btE(label+" — set automatically when the status changes")+'">'+_btE(iso?fmtIST(iso):"—")+'</td>';
        };
        const fileName=String(bt.report_name||"")||(bt.report_url?"Report":"");
        wl+='<tr'+(on?' style="background:var(--brand-tint)"':'')+'>'
          +'<td><input type="checkbox" '+(on?"checked":"")+' onclick="window._btToggleRow(\''+rid+'\',this.checked)" aria-label="Select '+_btE(r.name||"record")+'"></td>'
          +'<td class="mono" style="font-size:11.5px;white-space:nowrap">'+_btE(r.date)+(r.time?' · '+_btE(r.time):'')+'</td>'
          +'<td style="font-weight:600">'+_btE(r.name)+'</td>'
          +'<td><input class="input" type="email" inputmode="email" placeholder="name@example.com" style="'+inStyle+';width:190px"'
            +' value="'+_btE(email)+'" aria-label="Client email for '+_btE(r.name||"this record")+'"'
            +' onchange="window._btRowEmail(\''+rid+'\',this.value)"></td>'
          +'<td class="mono">'+_btE(r.ph)+'</td>'
          +'<td style="max-width:220px;white-space:normal">'+_btE(r.panelText||"—")+'</td>'
          +'<td>'+chip(_btSampleL,r.sampleStatus)+'</td>'
          +dtCell("sample_sent_at","Sample sent date and time")
          +'<td>'+chip(_btLabL,r.labStatus)+'</td>'
          +dtCell("lab_sent_at","Lab report sent date and time")
          +'<td>'+chip(_btLabRepL,r.labReportStatus)+'</td>'
          +dtCell("lab_report_received_at","Lab report received date and time")
          +'<td>'+chip(_btCliRepL,r.clientReportStatus)+'</td>'
          +dtCell("client_shared_at","Client share date and time")
          +'<td><div style="display:flex;gap:4px"><button class="btn bsm bp" onclick="window._btOpenDetail(\''+rid+'\')">Open</button>'+(r.payStatus!=="paid"?'<button class="btn bsm" title="Collect blood-test payment" onclick="event.stopPropagation();window._btCollectQueue(\''+rid+'\')">₹ Collect</button>':'<span class="chipb ok" style="font-size:10px;align-self:center">Paid</span>')+'</div></td>'
          // Disabled until the row has an email, per spec. The title says WHY it is disabled —
          // a disabled control with no explanation is the usual reason people think it is broken.
          +'<td><button class="btn bsm" id="btMail-'+rid+'" '+(email?"":"disabled ")
            +'title="'+(email?_btE("Email the report to "+email):"Add a client email first")+'"'
            +' onclick="window._btRowMail(\''+rid+'\')">✉ Email send</button></td>'
          // WhatsApp mirrors Email send: same message, delivered via wa.me to the row's phone.
          +'<td><button class="btn bsm" '+(String(r.ph||"").replace(/\D/g,"").length>=10?"":"disabled ")
            +'title="'+(String(r.ph||"").replace(/\D/g,"").length>=10?_btE("WhatsApp the report to "+r.ph):"No phone number on this record")+'"'
            +' onclick="window._btRowWa(\''+rid+'\')">🟢 WhatsApp send</button></td>'
          +'<td><div style="display:flex;gap:6px;align-items:center">'
            +'<button class="btn bsm" onclick="window._btRowUpload(\''+rid+'\')">'+(fileName?"Replace":"⬆ Add report")+'</button>'
            +(fileName?'<a href="'+_btE(_safeHref(bt.report_url))+'" target="_blank" rel="noopener noreferrer" class="mono" style="font-size:11px;max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="'+_btE(fileName)+'">'+_btE(fileName)+'</a>':'<span style="font-size:11px;color:var(--faint)">No file</span>')
            +'</div></td></tr>';
      });
      wl+='</tbody></table>';
      const ww=el("btWorklistWrap"); if(ww)(ww as HTMLElement).innerHTML=wl;
      _btRenderBulkBar();
    }
    // Bulk-action toolbar: one-click set of any status across every selected record (spec §6).
    function _btRenderBulkBar(){
      const bar=root.querySelector("#btBulkBar") as HTMLElement|null; if(!bar) return;
      const n=_btRowSel.size;
      if(!n){ bar.style.display="none"; bar.innerHTML=""; return; }
      const grp=(label:string,field:string,opts:[string,string][])=>'<span style="display:inline-flex;align-items:center;gap:4px"><b style="font-weight:600;color:var(--muted)">'+label+':</b>'
        +opts.map(([v,l])=>'<button class="btn bsm" onclick="window._btBulkConfirm(\''+field+'\',\''+v+'\')">'+l+'</button>').join("")+'</span>';
      bar.style.display="flex";
      bar.innerHTML='<b>'+n+' selected</b>'
        +grp("Sample","sample_status",[["collected","Collected"],["yet_to_collect","Yet to Collect"]])
        +grp("Lab","lab_status",[["sent","Sent"],["yet_to_send","Yet to Send"]])
        +grp("Lab report","lab_report_status",[["received","Received"],["yet_to_receive","Yet to Receive"]])
        +grp("Client report","client_report_status",[["shared","Shared"],["yet_to_share","Yet to Share"]])
        +'<button class="btn bsm" style="margin-left:auto" onclick="window._btClearSel()">Clear selection</button>';
    }
    w._btToggleRow=(id:string,on:boolean)=>{ if(on)_btRowSel.add(String(id)); else _btRowSel.delete(String(id)); _btRenderAll(); };
    w._btToggleAll=(on:boolean)=>{ const vis=_btVisibleRows(); if(on) vis.forEach((r:any)=>_btRowSel.add(String(r.id))); else vis.forEach((r:any)=>_btRowSel.delete(String(r.id))); _btRenderAll(); };
    w._btClearSel=()=>{ _btRowSel.clear(); _btRenderAll(); };
    w._btSearchRows=(v:string)=>{ _btSearch=v||""; _btRenderAll(); };
    // Click a summary card → filter the table to it; click the active card again to clear.
    w._btCardFilter=(k:string)=>{ _btCard=(_btCard===k)?"":k; _btRowSel.clear(); _btRenderAll(); const wrap=root.querySelector("#btWorklistWrap")as HTMLElement|null; if(_btCard&&wrap){ try{ wrap.scrollIntoView({behavior:"smooth",block:"nearest"}); }catch(_){} } };
    w._btFilterChange=()=>{
      const g=(id:string)=>((root.querySelector("#"+id)as HTMLSelectElement|null)?.value)||"";
      _btFilt={sample:g("btFiltSample"),lab:g("btFiltLab"),labReport:g("btFiltLabRep"),clientReport:g("btFiltCliRep")};
      _btRenderAll();
    };
    w._btClearFilters=()=>{
      _btFilt={sample:"",lab:"",labReport:"",clientReport:""}; _btSearch=""; _btCard="";
      ["btFiltSample","btFiltLab","btFiltLabRep","btFiltCliRep"].forEach(id=>{const e=root.querySelector("#"+id)as HTMLSelectElement|null; if(e)e.value="";});
      const s=root.querySelector("#btSearch")as HTMLInputElement|null; if(s)s.value="";
      _btRenderAll();
    };
    // The four bulk-updatable statuses share ONE confirmation modal (same UI/UX for all).
    const BT_STATUS_FIELDS:Record<string,{label:string;opts:[string,string][]}>={
      sample_status:{label:"Sample status",opts:[["collected","Collected"],["yet_to_collect","Yet to Collect"]]},
      lab_status:{label:"Lab status",opts:[["sent","Sent"],["yet_to_send","Yet to Send"]]},
      lab_report_status:{label:"Lab report status",opts:[["received","Received"],["yet_to_receive","Yet to Receive"]]},
      client_report_status:{label:"Client report status",opts:[["shared","Shared"],["yet_to_share","Yet to Share"]]},
    };
    // FR §6 — apply one status to the given records, persisting to blood_test_data (unchanged API).
    async function _btApplyBulk(ids:string[],field:string,value:string){
      if(!ids.length){ toast("Select at least one record"); return; }
      const ups=ids.map(async id=>{
        const r=_btAll.find((x:any)=>String(x.id)===String(id)); if(!r) return;
        const bt={...(r.btData||{})}; bt[field]=value;
        _btStampStatus(bt,r.btData,field,value);   // stamp/clear this status's date column
        if(field==="client_report_status") bt.shared=(value==="shared");
        return supabase.from("appointments").update({blood_test_data:bt}).eq("id",r.id);
      });
      await Promise.all(ups);
      toast(ids.length+" record"+(ids.length===1?"":"s")+" updated");
      _btRowSel.clear();
      await loadBloodTestData();
    }
    w._btBulk=(field:string,value:string)=>_btApplyBulk([..._btRowSel],field,value);   // kept for compatibility
    // Confirmation popup: review + adjust the selected leads, pick the status, then confirm.
    w._btBulkConfirm=(field:string,value:string)=>{
      const meta=BT_STATUS_FIELDS[field]; if(!meta) return;
      const ids=[..._btRowSel]; if(!ids.length){ toast("Select at least one record first"); return; }
      let chosen=value;                              // the status value to apply (switchable in the popup)
      const sel=new Set(ids.map(String));            // popup-local selection, seeded from the table
      const ov=document.createElement("div");
      ov.style.cssText="position:fixed;inset:0;background:rgba(0,0,0,0.45);z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px";
      const box=document.createElement("div");
      box.style.cssText="background:var(--surface,#fff);border-radius:14px;padding:20px;max-width:720px;width:100%;max-height:88vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,0.3)";
      ov.appendChild(box); document.body.appendChild(ov);
      const close=()=>{ if(ov.parentNode) document.body.removeChild(ov); };
      ov.onclick=(ev:any)=>{ if(ev.target===ov) close(); };
      const rowsFor=()=>ids.map(id=>_btAll.find((x:any)=>String(x.id)===String(id))).filter(Boolean);
      function render(){
        const rows=rowsFor();
        const optBtns=meta.opts.map(([v,l])=>'<button class="btn bsm'+(v===chosen?" bp":"")+'" onclick="window._btBulkPick(\''+_btE(v)+'\')">'+_btE(l)+'</button>').join("");
        const body=rows.map((r:any)=>{
          const on=sel.has(String(r.id));
          return '<tr'+(on?' style="background:var(--brand-tint)"':'')+'>'
            +'<td><input type="checkbox" '+(on?"checked":"")+' onclick="window._btBulkTog(\''+_btE(String(r.id))+'\',this.checked)"></td>'
            +'<td style="font-weight:600">'+_btE(r.name||"—")+'</td>'
            +'<td class="mono">'+_btE(r.ph||"—")+'</td>'
            +'<td>'+_btE(r.panelText||(r.raw&&r.raw.service)||"—")+'</td>'
            +'<td class="mono" style="font-size:11.5px;white-space:nowrap">'+_btE(r.date)+(r.time?' · '+_btE(r.time):'')+'</td></tr>';
        }).join("");
        const nSel=sel.size;
        box.innerHTML='<div style="font-weight:700;font-size:16px;margin-bottom:2px;color:var(--ink)">Confirm bulk update — '+_btE(meta.label)+'</div>'
          +'<div style="font-size:12px;color:var(--faint);margin-bottom:14px">Review the records, adjust the selection, choose the status, then confirm. Only the ticked records are updated.</div>'
          +'<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px"><b style="font-size:12.5px;color:var(--muted)">Set '+_btE(meta.label)+' to:</b>'+optBtns+'</div>'
          +'<div class="tscroll" style="max-height:46vh;overflow:auto;border:1px solid var(--line);border-radius:10px"><table class="tbl"><thead><tr><th style="width:28px"></th><th>Name</th><th>Phone</th><th>Service / panel</th><th>Visit date &amp; time</th></tr></thead><tbody>'+(body||'<tr><td colspan="5" style="text-align:center;color:var(--faint);padding:16px">No records.</td></tr>')+'</tbody></table></div>'
          +'<div style="display:flex;align-items:center;gap:10px;justify-content:space-between;margin-top:14px">'
          +'<span style="font-size:12px;color:var(--muted)"><b>'+nSel+'</b> of '+rows.length+' selected</span>'
          +'<div style="display:flex;gap:10px"><button class="btn bsm" id="btBulkCancel">Cancel</button><button class="btn bsm bp" id="btBulkGo"'+(nSel?"":" disabled")+'>Update Selected Records</button></div></div>';
        (box.querySelector("#btBulkCancel")as HTMLElement).onclick=close;
        const go=box.querySelector("#btBulkGo")as HTMLButtonElement;
        go.onclick=async()=>{
          const applyIds=[...sel]; if(!applyIds.length){ toast("Select at least one record"); return; }
          go.disabled=true; go.textContent="Updating…";
          await _btApplyBulk(applyIds,field,chosen);
          close();
        };
      }
      w._btBulkPick=(v:string)=>{ chosen=v; render(); };
      w._btBulkTog=(id:string,on:boolean)=>{ if(on)sel.add(String(id)); else sel.delete(String(id)); render(); };
      render();
    };
    w._btOpenDetail=(id:any)=>{
      const r=_btAll.find((x:any)=>String(x.id)===String(id)); if(!r){toast("Not found");return;}   // id is BIGSERIAL → gateway returns a string
      _btOpenAppt=r; _btReportAtt=r.btData.report_url?{name:"Report",url:r.btData.report_url}:null;
      const el=(s:string)=>root.querySelector("#"+s) as HTMLInputElement|HTMLSelectElement|null;
      if(el("btDetailName"))(el("btDetailName") as HTMLElement).textContent=r.name+" · "+r.date;
      _btdPanels=new Set<string>((r.panels||[]).filter((c:string)=>BT_PANELS.some(p=>p.code===c)));
      _btdClosePanelDD(); _btdRenderPanelBtn();
      if(el("btdSample")) (el("btdSample") as HTMLSelectElement).value=r.sampleStatus;
      if(el("btdLab")) (el("btdLab") as HTMLSelectElement).value=r.labStatus;
      if(el("btdLabReport")) (el("btdLabReport") as HTMLSelectElement).value=r.labReportStatus;
      if(el("btdClientReport")) (el("btdClientReport") as HTMLSelectElement).value=r.clientReportStatus;
      if(el("btdThyroCost")) (el("btdThyroCost") as HTMLInputElement).value=String(r.thyroCost||"");
      if(el("btdOurPrice")) (el("btdOurPrice") as HTMLInputElement).value=String(r.ourPrice||"");
      _btRenderAtts();
      const dp=root.querySelector("#btDetailPanel") as HTMLElement; if(dp) dp.style.display="block";
      dp?.scrollIntoView({behavior:"smooth"});
    };
    // Tests / panels multi-select dropdown (spec §3).
    function _btdRenderPanelBtn(){
      const btn=root.querySelector("#btdPanelBtn"); if(!btn) return;
      if(!_btdPanels.size){ btn.innerHTML='<span style="color:var(--faint)">Select tests / panels…</span>'; return; }
      btn.innerHTML=BT_PANELS.filter(p=>_btdPanels.has(p.code)).map(p=>
        '<span class="chipb info" style="display:inline-flex;align-items:center;gap:4px">'+_btE(p.name)
        +' <span onclick="event.stopPropagation();window._btdTogglePanel(\''+p.code+'\')" style="cursor:pointer;font-weight:700">×</span></span>'
      ).join("");
    }
    function _btdRenderPanelDD(){
      const dd=root.querySelector("#btdPanelDD"); if(!dd) return;
      const list=BT_PANELS.map(p=>{ const on=_btdPanels.has(p.code);
        return '<div onclick="window._btdTogglePanel(\''+p.code+'\')" style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:6px;cursor:pointer;font-size:12.5px"'
          +' onmouseover="this.style.background=\'var(--brand-tint)\'" onmouseout="this.style.background=\'transparent\'">'
          +'<input type="checkbox" '+(on?"checked":"")+' style="pointer-events:none">'
          +'<span style="flex:1">'+_btE(p.name)+'</span><span class="mono" style="color:var(--muted)">'+_btMoney(p.price)+'</span></div>';
      }).join("");
      // Sticky Done bar. This dropdown had NO dismiss path at all — no outside-click handler (the
      // app's three other multi-selects each have one) and _btdClosePanelDD was only ever called when
      // the record first opened. Once opened it covered the Sample / Lab / Client status fields below
      // it and the user could not get past this step. Ticks already apply immediately, so Done only
      // closes the list; the running count makes that obvious.
      const n=_btdPanels.size;
      const foot='<div style="position:sticky;bottom:0;background:var(--surface);border-top:1px solid var(--line);padding:6px 4px 2px;display:flex;align-items:center;gap:8px;margin-top:4px">'
        +'<span style="font-size:11.5px;color:var(--muted)">'+(n?(n+" selected"):"None selected")+'</span>'
        +'<button type="button" class="btn bsm bp" style="margin-left:auto" onclick="event.stopPropagation();window._btdDonePanelDD()">Done</button></div>';
      dd.innerHTML=list+foot;
    }
    function _btdClosePanelDD(){ const dd=root.querySelector("#btdPanelDD") as HTMLElement|null; if(dd) dd.style.display="none"; }
    w._btdTogglePanelDD=()=>{ const dd=root.querySelector("#btdPanelDD") as HTMLElement|null; if(!dd) return; const show=dd.style.display==="none"||!dd.style.display; if(show){ _btdRenderPanelDD(); dd.style.display="block"; } else dd.style.display="none"; };
    w._btdTogglePanel=(code:string)=>{ if(_btdPanels.has(code))_btdPanels.delete(code); else _btdPanels.add(code); _btdRenderPanelBtn(); _btdRenderPanelDD(); };
    w._btdDonePanelDD=()=>_btdClosePanelDD();
    // The two escape hatches every other multi-select in this app already has: click anywhere outside
    // the control, or press Escape. Selections are applied as they are ticked, so closing never
    // discards anything.
    // CAPTURE phase deliberately: ticking a panel re-renders the list (_btdTogglePanel rebuilds
    // dd.innerHTML), so on the bubble phase the clicked row is already detached and
    // box.contains(target) reports false — which closed the dropdown on every tick. In the capture
    // phase the row is still in the tree, so containment is accurate.
    document.addEventListener("click",(e:any)=>{
      const box=root.querySelector("#btdPanelBox"); const dd=root.querySelector("#btdPanelDD")as HTMLElement|null;
      if(dd&&dd.style.display==="block"&&box&&!box.contains(e.target)) _btdClosePanelDD();
    },true);
    document.addEventListener("keydown",(e:any)=>{
      if(e&&e.key==="Escape"){ const dd=root.querySelector("#btdPanelDD")as HTMLElement|null; if(dd&&dd.style.display==="block") _btdClosePanelDD(); }
    });
    function _btRenderAtts(){ const el=root.querySelector("#btdAtts"); if(!el)return; if(_btReportAtt&&_btReportAtt.url){ el.innerHTML='<a href="'+_btE(_btReportAtt.url)+'" target="_blank" class="att"><svg class="icon"><use href="#i-clip"/></svg> '+_btE(_btReportAtt.name||"Report")+'</a> <button class="btn bsm" onclick="window._btAddReport()">Replace</button>'; } else { el.innerHTML='<span class="att add" onclick="window._btAddReport()"><svg class="icon"><use href="#i-clip"/></svg> Upload report</span>'; } }
    w._btCloseDetail=()=>{ const dp=root.querySelector("#btDetailPanel") as HTMLElement; if(dp) dp.style.display="none"; _btOpenAppt=null; };
    w._btAddReport=()=>{
      const inp=document.createElement("input"); inp.type="file"; inp.accept=".pdf,.jpg,.jpeg,.png,.webp";
      inp.onchange=async()=>{ const file=inp.files&&inp.files[0]; if(!file)return; if(file.size>15*1024*1024){toast("Max 15 MB");return;}
        toast("Uploading…"); const id=_btOpenAppt?.lead_id||"bt"; const path="bloodtest/"+String(id).replace(/[^a-zA-Z0-9._-]/g,"_")+"/"+Date.now()+"_"+file.name.replace(/[^a-zA-Z0-9._-]/g,"_");
        try{ const up=await supabase.storage.from("lead-files").upload(path,file,{upsert:false}); if(up.error)throw up.error;
          const {data}=supabase.storage.from("lead-files").getPublicUrl(path); _btReportAtt={name:file.name,url:(data&&data.publicUrl)||""}; _btRenderAtts(); toast("Report uploaded");
        }catch(e:any){ toast(/bucket|not found|policy/i.test(e.message||"")?"Run supabase-migration-storage-buckets.sql":"Upload failed"); }
      }; inp.click();
    };
    w._btSaveDetail=async()=>{
      if(!_btOpenAppt){toast("Open a record first");return;}
      const v=(id:string)=>(root.querySelector("#"+id)as HTMLInputElement|HTMLSelectElement)?.value||"";
      const panels=[..._btdPanels]; const clientReport=v("btdClientReport");
      // Preserve any unrelated keys already on the record; overwrite the fields we own.
      const btData={...(_btOpenAppt.btData||{}),
        panels, panel:panels.map(_btPanelName).join(", "),
        sample_status:v("btdSample"), lab_status:v("btdLab"), lab_report_status:v("btdLabReport"), client_report_status:clientReport,
        thyrocare_cost:Number(v("btdThyroCost"))||0, our_price:Number(v("btdOurPrice"))||0,
        report_url:_btReportAtt?.url||"", shared:clientReport==="shared",
        sample_at:v("btdSample")==="collected"?new Date().toISOString():""};
      // Same auto-stamp rule as the worklist's bulk actions: only statuses this save CHANGED move
      // their date column, so re-saving an unrelated field never rewrites an existing milestone.
      BT_STATUS_STAMPS.forEach(([f])=>_btStampStatus(btData,_btOpenAppt.btData,f,String(btData[f]||"")));
      try{ const {error}=await supabase.from("appointments").update({blood_test_data:btData}).eq("id",_btOpenAppt.id);
        if(error&&/blood_test_data|column|schema|exist/i.test(error.message||"")){ toastErr("Can't save yet — the blood-test column is missing. Run supabase-migration-module-columns.sql in Supabase, then Save again."); return; }
        if(error)throw error; toast("Blood test record saved"); await loadBloodTestData();
      }catch(e:any){ toastErr("Save failed: "+(e.message||"error")); }
    };
    w._btShareWA=()=>{ if(!_btOpenAppt){toast("Open a record first");return;} toast("WhatsApp share — report link sent to "+(_btOpenAppt.name||"client")); };
    w._btCollectPay=()=>{ if(!_btOpenAppt)return; const price=Number((root.querySelector("#btdOurPrice")as HTMLInputElement)?.value)||800; recOpen(_btOpenAppt.id,_btOpenAppt.name,price,_btOpenAppt.lead_id,"bt"); };
    // Blood Test → Collect Payment queue: open the dedicated Collect Payment page (client info +
    // tests/panels + total) for an unpaid blood-test appointment straight from the worklist row.
    w._btCollectQueue=(id:any)=>{ const r=_btAll.find((x:any)=>String(x.id)===String(id)); if(!r){ toastErr("Blood test record not found"); return; } _cpOpen({apptId:r.id,leadId:r.lead_id||"",name:r.name||"",phone:r.ph||"",email:"",addr:"",service:"Blood test"}); };
    w._btExport=()=>{ const rows=_btVisibleRows(); if(!rows.length){toast("Nothing to export");return;}
      const lbl=(m:any,v:string)=>(m[v]&&m[v].l)||v||"";
      const out:string[][]=[["Visit date","Time","Client","Phone","Panel(s)","Sample","Lab","Lab report","Client report","Payment","Our Price","Thyro Cost"]];
      rows.forEach((r:any)=>out.push([r.date,r.time,r.name,r.ph,r.panelText,lbl(_btSampleL,r.sampleStatus),lbl(_btLabL,r.labStatus),lbl(_btLabRepL,r.labReportStatus),lbl(_btCliRepL,r.clientReportStatus),r.payStatus,String(r.ourPrice),String(r.thyroCost)]));
      _downloadCsv("blood_test_export.csv",out); toast("Exported "+rows.length+" rows"); };

    // ========== PHYSIOTHERAPY MODULE (live data) ==========
    // Flow: Health Advisor (physio panel on the lead) → Reception check-in (stage "physio") → this
    // page (assessment + session tracking) → Reception → Collect payment → status syncs back here.
    // Everything rides on the EXISTING appointments/payments/leads rows — no new tables or APIs.
    let _phAll:any[]=[], _phFiltered:any[]=[], _phDate="today", _phOpenAppt:any=null;
    let _phSearchQ="", _phStatus="all";
    // Advisor-side physio info per lead_id (leads.advisor_profile.physio + the lead's own contact
    // fields), so the assessment form opens pre-filled with what the advisor already captured.
    let _phLeadInfo:Record<string,any>={};
    // Consultation status for a physio appointment, derived from the SAME fields every other screen
    // uses (appointment status/stage + physio_data) — nothing new is stored to drive it.
    //   cancelled → the appointment was cancelled
    //   completed → the physiotherapist finished the consultation (or Reception has since billed it)
    //   in_session → started, not finished
    //   waiting  → checked in / expected, waiting for the physiotherapist
    function _phConsult(a:any,pd:any):string{
      if(String(a.status||"")==="cancelled") return "cancelled";
      const stage=String(a.stage||"");
      if(pd.consult_status==="completed"||stage==="done"||/complet/i.test(stage)||stage==="payment") return "completed";
      if(pd.started||Number(pd.sessions_completed||0)>0) return "in_session";
      return "waiting";
    }
    const _PH_CONSULT:Record<string,{l:string;c:string}>={waiting:{l:"Waiting",c:"warn"},in_session:{l:"In session",c:"info"},completed:{l:"Completed",c:"ok"},cancelled:{l:"Cancelled",c:"al"}};
    // The patient-assessment form: [input id, physio_data.assessment key, printed label]. ONE list
    // drives the form fill, the save and the printout — adding a field means adding it here and in
    // the markup, nowhere else. Pain intensity / health condition / next session are handled
    // separately because they also live at the top level of physio_data (the sessions table and the
    // visit history read them there).
    const PH_ASSESS_FIELDS:[string,string,string][]=[
      ["phaActivity","physical_activity","Physical activity"],
      ["phaNutrition","nutrition","Nutrition"],
      ["phaSmoking","smoking","Smoking"],
      ["phaAlcohol","alcohol","Alcohol"],
      ["phaHistory","history","Past medical & surgical history"],
      ["phaComplaint","complaint","Chief complaint(s)"],
      ["phaDuration","duration","Duration of symptoms"],
      ["phaPainLoc","pain_location","Pain location"],
      ["phaTests","special_tests","Special test results"],
      ["phaDiagnosis","diagnosis","Diagnosis"],
      ["phaTreatment","treatment_plan","Treatment plan"],
    ];
    function _phDateRange():[Date|null,Date|null]{
      const now=new Date(); const sod=(d:Date)=>{const x=new Date(d);x.setHours(0,0,0,0);return x;}; const eod=(d:Date)=>{const x=new Date(d);x.setHours(23,59,59,999);return x;};
      if(_phDate==="today") return [sod(now),eod(now)];
      if(_phDate==="tmrw"){ const t=new Date(now);t.setDate(t.getDate()+1); return [sod(t),eod(t)]; }
      if(_phDate==="wk"){ const s=new Date(now);s.setDate(s.getDate()-s.getDay()); return [sod(s),eod(now)]; }
      if(_phDate==="cust"){ const f=(root.querySelector("#phFrom")as HTMLInputElement)?.value; const t=(root.querySelector("#phTo")as HTMLInputElement)?.value; return [f?sod(new Date(f)):null,t?eod(new Date(t)):null]; }
      return [null,null];
    }
    // ===== Physiotherapy pricing master (physio_pricing) =====
    // Managed centrally in Settings & masters → Physiotherapy pricing (its own tab, after Blood
    // Test pricing — same pattern as the Blood Test master bt_tests). The Physio page carries no
    // pricing card any more; its per-visit default and pack-price prefill read THIS list live.
    let _phpList:any[]=[];
    let _phpEditId:any=null;
    async function loadPhysioPricing(){
      try{ const {data,error}=await supabase.from("physio_pricing").select("*").order("sort"); if(error) throw error; _phpList=data||[]; }
      catch(_){ _phpList=[]; }
      _phpRenderSettings();
      // The Physiotherapy page's plan dropdown is generated from this master, so a Settings edit
      // (and the realtime physio_pricing refresh that calls this) reaches it immediately.
      try{ _phRenderPlanSel(); }catch(_){}
    }
    function _phpActive(){ return _phpList.filter((p:any)=>p.is_active); }
    // The live per-visit rate = the pricing master's sessions=1 row. Returns 0 when the org has NOT
    // configured one, because a chargeable amount must come from the pricing master — never from a
    // constant in the code.
    // This used to fall back to PHYSIO_DEFAULT_PRICE (₹800), and since the master carries no
    // sessions=1 row at all (only Consultation/6/8/12-session rows), EVERY "Per Visit" physio amount
    // was that hardcoded 800: pre-filled into the therapist's Amount field AND into Reception's
    // Collect Payment dialog, as a price nobody had ever set. That also contradicted the rule stated
    // at physioDue below — "never an auto-charge".
    function _phpPerSession():number{ const p=_phpActive().find((x:any)=>Number(x.sessions)===1); return p?(Number(p.price)||0):0; }
    function _phpPackFor(n:number){ return n>1?(_phpActive().find((x:any)=>Number(x.sessions)===n)||null):null; }
    function _phpRenderSettings(){
      const body=root.querySelector("#phpBody"); if(!body) return;
      body.innerHTML=_phpList.length?_phpList.map((p:any)=>'<tr'+(p.is_active?'':' style="opacity:.55"')+'><td style="font-weight:600">'+_orgEsc(p.label)+'</td><td class="mono">'+(Number(p.sessions)||0)+'</td><td class="mono" style="font-weight:700">₹'+(Number(p.price)||0).toLocaleString("en-IN")+'</td><td><span class="chipb '+(p.is_active?'ok':'neu')+'">'+(p.is_active?'Active':'Off')+'</span></td><td><div style="display:flex;gap:4px"><button class="btn bsm" onclick="window._phpEdit(\''+_orgEsc(p.id)+'\')">Edit</button><button class="btn bsm" onclick="window._phpToggle(\''+_orgEsc(p.id)+'\')">'+(p.is_active?'Disable':'Enable')+'</button><button class="btn bsm" onclick="window._phpDelete(\''+_orgEsc(p.id)+'\')">🗑</button></div></td></tr>').join(""):'<tr><td colspan="5" style="text-align:center;color:var(--faint);padding:14px">No items yet — add the first one above.</td></tr>';
    }
    w._phpSave=async()=>{
      const name=((root.querySelector("#phpName")as HTMLInputElement)?.value||"").trim();
      const sess=Math.max(0,Math.round(Number((root.querySelector("#phpSessions")as HTMLInputElement)?.value||0)||0));
      const price=Math.round(Number((root.querySelector("#phpPrice")as HTMLInputElement)?.value||0)||0);
      if(!name){ toastErr("Enter the item name"); return; }
      if(!(price>0)){ toastErr("Enter a valid price"); return; }
      if(_phpEditId){
        if(!(await _dbOk(supabase.from("physio_pricing").update({label:name,sessions:sess,price}).eq("id",_phpEditId),"Update physio pricing"))) return;
        toast("Pricing updated — reflected on the Physiotherapy page");
      } else {
        if(_phpList.some((p:any)=>String(p.label).toLowerCase()===name.toLowerCase())){ toastErr("That item already exists"); return; }
        const sort=(_phpList.reduce((m:number,p:any)=>Math.max(m,Number(p.sort)||0),0))+10;
        if(!(await _dbOk(supabase.from("physio_pricing").insert({label:name,sessions:sess,price,sort}),"Add physio pricing"))) return;
        toast("Pricing item added");
      }
      w._phpCancel(); await loadPhysioPricing();
    };
    w._phpEdit=(id:any)=>{
      const p=_phpList.find((x:any)=>String(x.id)===String(id)); if(!p) return; _phpEditId=p.id;
      const set=(i:string,v:any)=>{ const el=root.querySelector("#"+i)as HTMLInputElement|null; if(el) el.value=String(v??""); };
      set("phpName",p.label); set("phpSessions",p.sessions); set("phpPrice",p.price);
      const b=root.querySelector("#phpAddBtn"); if(b) b.textContent="Save changes";
      const c=root.querySelector("#phpCancelBtn")as HTMLElement|null; if(c) c.style.display="";
    };
    w._phpCancel=()=>{
      _phpEditId=null;
      ["phpName","phpSessions","phpPrice"].forEach(i=>{ const el=root.querySelector("#"+i)as HTMLInputElement|null; if(el) el.value=""; });
      const b=root.querySelector("#phpAddBtn"); if(b) b.textContent="+ Add item";
      const c=root.querySelector("#phpCancelBtn")as HTMLElement|null; if(c) c.style.display="none";
    };
    w._phpToggle=async(id:any)=>{
      const p=_phpList.find((x:any)=>String(x.id)===String(id)); if(!p) return;
      if(!(await _dbOk(supabase.from("physio_pricing").update({is_active:!p.is_active}).eq("id",id),"Update physio pricing"))) return;
      toast(p.is_active?"Item disabled":"Item enabled"); await loadPhysioPricing();
    };
    w._phpDelete=async(id:any)=>{
      const p=_phpList.find((x:any)=>String(x.id)===String(id)); if(!p) return;
      if(!window.confirm('Remove "'+p.label+'" from the pricing master? Past payments keep their stored amounts.')) return;
      if(!(await _dbOk(supabase.from("physio_pricing").delete().eq("id",id),"Remove physio pricing"))) return;
      toast("Removed"); await loadPhysioPricing();
    };
    // ---- Physiotherapy Session Details (treatment-plan section) helpers ----
    // ===== ONE definition of "which session is this patient on" =====
    // The same patient was reading 2/8 (assessment header), 1/8 (Session progress) and 1/? (visit
    // history) because three places each computed it their own way. Everything below now derives
    // from these two helpers.
    // `sessions_completed` keeps its stored meaning — sessions actually FINISHED. A patient with 1
    // finished session is ON session 2, so the displayed progress is completed+1, capped at the plan
    // total once the course is finished.
    function _phCurrentSession(done:any,planned:any):number{
      const d=Math.max(0,Number(done)||0), p=Math.max(0,Number(planned)||0);
      return p?Math.min(d+1,p):d+1;
    }
    // Sessions actually completed, reconciled across the TWO places physio_data records them.
    // sessions_completed is the counter; visits[] is the log the physiotherapist appends to when a
    // session is marked complete — and the two drift: K. Anu held sessions_completed = 0 while
    // visits already carried {n:1,"Completed"}. Progress then read 0 (showing session 1 of 6 forever)
    // and, worse, the re-check-in guard saw visit n=1 already logged and refused to advance, so the
    // count could never move again. Taking the higher of the two makes a logged session count even
    // when the counter was not bumped with it.
    function _phDoneOf(pd:any):number{
      const c=Number(pd&&pd.sessions_completed)||0;
      const logged=((pd&&pd.visits)||[]).reduce((m:number,v:any)=>Math.max(m,Number(v&&v.n)||0),0);
      return Math.max(c,logged);
    }
    function _phProgressText(done:any,planned:any):string{
      const p=Math.max(0,Number(planned)||0);
      return p?(_phCurrentSession(done,planned)+" / "+p):String(_phCurrentSession(done,planned));
    }
    // ===== Session / treatment plan dropdown — built from the pricing master, never hardcoded =====
    // The options used to be literal markup ("5 / 8 / 10 Sessions"), so the plans configured in
    // Settings → Physiotherapy pricing (Consultation, 6/8/12-session packs) never reached this page
    // and editing the master changed nothing here. Options are now generated from the active master
    // rows — value = that plan's session count, label = the master's own label — so any future
    // change in Settings appears here with no code change. "Custom Package" is kept as the escape
    // hatch for a one-off count that isn't in the master.
    // Rows are de-duplicated by session count because the <option> value IS the count (two plans of
    // the same length would otherwise be indistinguishable on selection).
    function _phRenderPlanSel(){
      const sel=root.querySelector("#phTpPlan")as HTMLSelectElement|null; if(!sel) return;
      const keep=sel.value;
      const seen:Record<string,boolean>={};
      let html='<option value="">— Select —</option>';
      _phpActive().forEach((p:any)=>{
        const n=String(Math.max(0,Number(p.sessions)||0));
        if(seen[n]) return; seen[n]=true;
        html+='<option value="'+n+'">'+_orgEsc(p.label||(n+" Sessions"))+'</option>';
      });
      html+='<option value="custom">Custom Package</option>';
      sel.innerHTML=html;
      if(keep&&Array.from(sel.options).some(o=>o.value===keep)) sel.value=keep;   // survive a master refresh
    }
    // Does the pricing master define a plan with exactly this session count? Decides whether a saved
    // sessions_planned maps to a master option or has to fall back to "Custom Package" — this used
    // to be a hardcoded [5,8,10] membership test.
    function _phPlanInMaster(n:number):boolean{ return _phpActive().some((p:any)=>Number(p.sessions)===Number(n)); }
    // Fill the Session progress dropdown with one option per session in the selected package
    // (1/8 … 8/8), pre-selecting the session the patient is currently on. Replaces the old read-only
    // text field: the therapist can now correct the count instead of it being unfixable.
    function _phRenderProgressSel(){
      const sel=root.querySelector("#phTpProgress")as HTMLSelectElement|null; if(!sel) return;
      const planned=_phTpSessions();
      const rawPlan=(root.querySelector("#phTpPlan")as HTMLSelectElement|null)?.value||"";
      const done=Number(_phOpenAppt&&_phOpenAppt.sessionsCompleted)||0;
      if(!rawPlan){ sel.innerHTML='<option value="">Select a session / treatment plan first</option>'; sel.disabled=true; return; }
      // A plan that carries no session count (e.g. a one-off "Consultation") has nothing to step through.
      if(!planned){ sel.innerHTML='<option value="">Not applicable — this plan has no session count</option>'; sel.disabled=true; return; }
      sel.disabled=false;
      const cur=_phCurrentSession(done,planned);
      let html="";
      for(let i=1;i<=planned;i++) html+='<option value="'+i+'"'+(i===cur?' selected':'')+'>'+i+' / '+planned+' Sessions</option>';
      sel.innerHTML=html;
    }
    w._phTpProgressChange=()=>{};   // the choice is read on Save session details
    // Say so when the counter is ahead of the logged visits instead of quietly showing fewer rows
    // than the progress claims. That gap is REAL for anyone treated while the sticky `_completed`
    // flag was suppressing visit logging, and for any count set by hand on the progress dropdown —
    // those sessions have no date/pain/notes on record, and inventing rows to fill the table would
    // be inventing clinical history.
    function _phVisitGapNote(r:any):string{
      const done=Number(r&&r.sessionsCompleted)||0, logged=((r&&r.visits)||[]).length;
      if(done<=logged) return "";
      const miss=done-logged;
      return '<div style="font-size:11.5px;color:var(--muted);padding:6px 2px;line-height:1.5">⚠ '+miss+' completed session'+(miss===1?"":"s")+' ha'+(miss===1?"s":"ve")+' no visit record.'
        +'<div style="color:var(--faint)">Counted in progress but never logged — correct the count on <b>Session progress</b> if it is wrong.</div></div>';
    }
    // Sessions for the selected plan — the master row's own session count, or the Custom Package input.
    function _phTpSessions():number{
      const plan=(root.querySelector("#phTpPlan")as HTMLSelectElement)?.value||"";
      if(plan==="custom") return Math.max(0,Math.round(Number((root.querySelector("#phTpCustom")as HTMLInputElement)?.value||0)||0));
      return Number(plan)||0;
    }
    // Auto amount from the pricing master: Package → the matching pack price (falls back to
    // per-session rate × sessions when no pack matches); Per Visit → the per-session rate.
    function _phTpAutoAmt(n:number,model:string):number{
      if(model!=="pack") return _phpPerSession();
      // Price straight from the master row the therapist actually picked. _phpPackFor only matches
      // n>1, so a zero-session plan (e.g. "Consultation") priced at 0 the moment it became
      // selectable — its configured price was unreachable.
      const own=_phpActive().find((x:any)=>Number(x.sessions)===Number(n)); if(own) return Number(own.price)||0;
      const pack=_phpPackFor(n); if(pack) return Number(pack.price)||0;
      return n>0?_phpPerSession()*n:_phpPerSession();
    }
    w._phTpPlanChange=()=>{
      const plan=(root.querySelector("#phTpPlan")as HTMLSelectElement)?.value||"";
      const f=root.querySelector("#phTpCustomFld")as HTMLElement|null; if(f) f.style.display=plan==="custom"?"":"none";
      w._phTpAmtSync();
    };
    w._phTpAmtSync=()=>{
      const model=(root.querySelector("#phTpPayType")as HTMLSelectElement)?.value||"pack";
      const auto=_phTpAutoAmt(_phTpSessions(),model);
      const amt=root.querySelector("#phTpAmt")as HTMLInputElement|null;
      if(amt){
        // Nothing configured for this option → leave the field EMPTY and say why. Pre-filling a
        // number here means the therapist saves it and Reception collects it, so an unconfigured
        // rate must look unset, not like a price.
        amt.value=auto>0?String(auto):"";
        amt.placeholder=auto>0?"":"No rate configured — set it in Settings → Physiotherapy pricing";
        amt.title=auto>0?"Auto-filled from the pricing master (pack price, or per-visit rate)":"No price is configured for this option. Add it in Settings → Physiotherapy pricing, or type the amount to charge.";
      }
      _phRenderProgressSel();   // package size changed → rebuild 1/N … N/N and keep the current session selected
    };

    async function loadPhysioData(){
      if(!_phpList.length){ try{ loadPhysioPricing(); }catch(_){} }   // pricing card + defaults ride along
      try{
        // "%phys%" (not "%physio%") also catches the legacy "Physio" / "Physiotherapy" spellings and
        // combined service strings ("Diabetes Counselling + Physiotherapy"), the same way _recSvcCode
        // matches them everywhere else.
        const [ar,pr]=await Promise.all([
          supabase.from("appointments").select("*").ilike("service","%phys%").order("appt_date",{ascending:false}).limit(500),
          supabase.from("payments").select("*").order("created_at",{ascending:false})
        ]);
        // One payment per appointment, and a PAID row always wins over a stale due row — this is what
        // keeps the payment status on this page identical to Reception's.
        // PHYSIO money only: collect stamps payments.service ("Physio" / "Blood test" / "Diabetes" —
        // see _svcPayLabel), and a combined visit hangs SEVERAL services' payments off the same
        // appointment row. Mapping appointment_id alone let a blood-test collection become this
        // page's Payment cell (reported for Ally: combined "Physiotherapy + Blood Test" visit showed
        // "₹1,500 paid · UPI" — her blood-test money — while the physio fee was still pending).
        // Rows explicitly tagged another service are skipped; untagged legacy rows still count.
        const pays:Record<string,any>={};
        (pr.data||[]).forEach((p:any)=>{ if(!p.appointment_id) return;
          const _psvc=String(p.service||""); if(_psvc&&!/phys/i.test(_psvc)) return;
          const k=String(p.appointment_id); const cur=pays[k];
          if(!cur||(p.status==="paid"&&cur.status!=="paid")) pays[k]=p; });
        const rows=(ar.data||[]);
        // Pull the advisor's physio panel for these leads (name/phone/condition/referral/notes) so the
        // assessment form is pre-filled from what the Health Advisor already recorded.
        const leadIds=Array.from(new Set(rows.map((a:any)=>a.lead_id).filter(Boolean)));
        _phLeadInfo={};
        if(leadIds.length){
          try{
            const {data:lr}=await supabase.from("leads").select("meta_lead_id,name,phone,advisor_profile,notes").in("meta_lead_id",leadIds);
            (lr||[]).forEach((l:any)=>{ const ap=l.advisor_profile||{}; _phLeadInfo[String(l.meta_lead_id)]={name:l.name||"",phone:l.phone||"",physio:ap.physio||{},notes:l.notes||""}; });
          }catch(_){}
        }
        _phAll=rows.map((a:any)=>{
          const pay=pays[String(a.id)]; const pd=a.physio_data||{};
          const info=_phLeadInfo[String(a.lead_id)]||{}; const adv=info.physio||{};
          const consult=_phConsult(a,pd);
          const planned=Number(pd.sessions_planned)||0, done=_phDoneOf(pd);
          // Dates on this page are the VISIT (check-in), not the booked/lead date — see _visitStamp.
          const vs=_visitStamp(a);
          return { id:a.id, lead_id:a.lead_id, name:a.client_name||info.name||"Client", ph:a.phone||info.phone||"", _date:vs.key, date:vs.date, time:vs.time,
            status:a.status||"expected", stage:a.stage||"", session:a.session||"", pt:a.hc_pt||"",
            condition:pd.condition||adv.condition||"", sessionsPlanned:planned, sessionsCompleted:done,
            payModel:pd.payment_model||"per_visit", packPrice:Number(pd.pack_price)||_phpPerSession(),
            assessment:pd.assessment||{}, painLevel:pd.pain_level, visits:pd.visits||[],
            nextDate:pd.next_session||"", consult,
            // Straight from the advisor's Physiotherapy panel (leads.advisor_profile.physio).
            advReferral:adv.referral||"", advMode:adv.mode||"", advSlot:adv.timeSlot||"", advReports:(adv.reports||[]).join(", "),
            advRemarks:adv.remarks||info.notes||"", advApptDate:adv.apptDate||"",
            payStatus:pay?pay.status:"due", payAmt:pay?Number(pay.amount)||0:0, payMethod:pay?(pay.method||""):"", payVerified:pay?!!pay.verified:false,
            phData:pd, raw:a };
        });
      }catch(e:any){ _phAll=[]; if(/physio_data|column/i.test(e.message||"")) toast("Run supabase-migration-module-columns.sql to enable physio data"); }
      _phApplyDateFilter();
    }
    function _phApplyDateFilter(){
      const [from,to]=_phDateRange();
      _phFiltered=_phAll.filter((r:any)=>{ if(!r._date)return true; const d=new Date(/T/.test(r._date)?r._date:(r._date+"T12:00:00")); if(from&&d<from)return false; if(to&&d>to)return false; return true; });
      _phRenderAll();
    }
    w._phDateF=(d:string)=>{ _phDate=d; const show=d==="cust"; ["phFrom","phTo"].forEach(id=>{const el=root.querySelector("#"+id)as HTMLElement;if(el)el.style.display=show?"inline":"none";}); const ab=root.querySelector("#phApplyBtn")as HTMLElement|null; if(ab) ab.style.display=show?"inline-flex":"none"; root.querySelectorAll("#phDateFilt .pill").forEach((b:any)=>b.classList.remove("on")); const idx={today:0,tmrw:1,wk:2,cust:3}[d]??0; root.querySelectorAll("#phDateFilt .pill")[idx]?.classList.add("on"); if(d!=="cust") _phApplyDateFilter(); };   // presets apply at once; Custom waits for the Apply button
    w._phApplyDate=()=>{ if(_phDate==="cust") _phApplyDateFilter(); };   // triggered by the Custom-range Apply button
    // Search (name / phone) + consultation-status filter, applied on top of the date range.
    w._phSearch=(v:string)=>{ _phSearchQ=String(v||""); _phRenderAll(); };
    // The KPI cards and the filter pills drive ONE state (_phStatus), so they can never disagree —
    // the pills are just the four consultation statuses, the cards add the other views.
    const PH_FILTERS:{k:string;label:string;test:(r:any)=>boolean}[]=[
      {k:"all",label:"All",test:()=>true},
      {k:"waiting",label:"Waiting",test:(r:any)=>r.consult==="waiting"},
      {k:"in_session",label:"In session",test:(r:any)=>r.consult==="in_session"},
      {k:"completed",label:"Completed",test:(r:any)=>r.consult==="completed"},
      {k:"cancelled",label:"Cancelled",test:(r:any)=>r.consult==="cancelled"},
      {k:"active_plans",label:"Active plans",test:(r:any)=>r.sessionsPlanned>0&&r.sessionsCompleted<r.sessionsPlanned},
      {k:"payment_due",label:"Payment due",test:(r:any)=>r.payStatus!=="paid"},
    ];
    const _phFilterOf=(k:string)=>PH_FILTERS.find(x=>x.k===k)||PH_FILTERS[0];
    w._phStatusF=(k:string)=>{ _phStatus=k||"all"; _phRenderAll(); };
    // KPI card → filter the table to that card, then bring the table into view. Clicking the active
    // card again clears it, the same toggle-to-clear the Reception status cards and the Blood Test
